import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c2-001","clusterId":"C","werkstueckRef":"C.4.3","stufe":1,"question":"Ein Gesundheitsportal wirbt: „Unser Immun-Tee stärkt Ihre Abwehr und macht eine Masernimpfung überflüssig.“ Welche Frage prüft diese Behauptung am besten?","options":["Kann ein Getränk, das die allgemeine Abwehr unterstützt, dem Körper die genaue Information über das Masernvirus liefern, die er zum Erkennen braucht?","Wie viele Menschen in meinem Umfeld trinken diesen Tee schon und fühlen sich seitdem gesünder und leistungsfähiger?","Ist der Tee aus pflanzlichen Zutaten hergestellt, die schon seit langer Zeit als bewährte Hausmittel verwendet werden?","Wirkt die Werbeaussage glaubwürdig, weil sie von einem Portal mit sehr vielen Besucherinnen und Besuchern stammt?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Abwehrebenen. Die angeborene Abwehr ist schnell und grob: Sie springt auf typische Bausteine ganzer Erregergruppen an, erkennt aber nicht den einzelnen Erreger und merkt sich nichts. Die adaptive Abwehr mit B- und T-Zellen wird langsamer aktiviert, ist aber präzise und hinterlässt Gedächtniszellen, die jahrzehntelang im Körper patrouillieren. Für Masern braucht der Körper genau diese spezifische Information über den Erreger. Eine Impfung liefert sie in harmloser Form, ein allgemein „stärkendes“ Getränk kann das nicht. Die anderen Fragen prüfen Verbreitung, Tradition oder Reichweite der Quelle, aber nicht, ob die behauptete Ursache-Wirkung-Kette überhaupt möglich ist.","coreRule":"⚡ Wer eine Impfung ersetzen will, muss zeigen, wie die Maßnahme dem Körper die spezifische Information über genau diesen Erreger liefert. Allgemeine „Stärkung“ reicht dafür nicht.","beleg":"Werkstück C.4.3 (Kontext & Tiefe); Fn. gl-c-mustererkennung (Aster u. a. 2026, S. 169 und 181)","status":"entwurf","scenario":"","kurz":"Eine Impfung liefert dem Körper die spezifische Information über den Erreger, die für Masern nötig ist. Ein Tee, der die Abwehr allgemein „stärkt“, kann das nicht. Der Fehler liegt darin, schnelle, grobe Abwehr mit gezielter, gedächtnisbildender zu verwechseln.","prueffrage":"Welche Belege nennt das Portal dafür, dass Teetrinker ohne Impfung seltener an Masern erkranken?","rueckmeldung":[{"option":1,"text":"Wohlbefinden im Bekanntenkreis ist leicht zu beobachten und wirkt überzeugend. Es zeigt aber nicht, ob jemand vor Masern geschützt ist, und gerade das behauptet die Werbung. Gefühlte Fitness ersetzt keine spezifische Immunität."},{"option":2,"text":"Eine lange Tradition und pflanzliche Zutaten wirken vertrauenswürdig. Sie sagen aber nichts darüber, ob ein Getränk dem Körper den Erreger „vorstellen“ kann. Wie alt oder natürlich ein Mittel ist, beantwortet diese Frage nicht."},{"option":3,"text":"Ein Portal mit vielen Besuchern erreicht viele Menschen. Die Reichweite sagt aber nichts darüber, ob die Aussage stimmt. Entscheidend ist, ob die behauptete Wirkung überhaupt möglich ist, und das lässt sich an der Aussage selbst prüfen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Wie funktioniert das Immunsystem?","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/wie-funktioniert-das-immunsystem.html","abruf":"2026-10-12"},{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Aster u. a. (Hrsg.) 2026, Robbins, Cotran & Kumar Pathologic Basis of Disease, 11. Aufl., Elsevier","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c6acbfa5e8db883d"}},{"id":"qx-c2-002","clusterId":"C","werkstueckRef":"C.4.3","stufe":2,"question":"In einem Gespräch heißt es: „Gegen HIV hilft nur ein stärkeres Immunsystem, und das lässt sich über Ernährung und Lebensstil erreichen.“ Ein Arzt entgegnet, dass das Problem anderswo liegt. Welche Überlegung zeigt am besten, warum HIV die Abwehr als Ganzes zusammenbrechen lässt?","options":["Das Virus zerstört gerade die Zellen, die die gezielte Abwehr koordinieren; ohne sie laufen B- und T-Zellen ins Leere, selbst wenn alle anderen Abwehrzellen vorhanden sind.","Das Virus vermehrt sich im Inneren von Körperzellen, wo Antibiotika es nicht erreichen; deshalb kann es sich im Körper halten, selbst wenn die Abwehr zunächst voll funktionsfähig ist.","Das Immunsystem kann sich auch gegen den eigenen Körper richten (Autoimmunreaktion); dann schadet die Abwehr dem Gewebe, selbst wenn alle Abwehrzellen vorhanden sind.","Dauerhafter Schlafmangel und Mangelernährung schwächen die Abwehr; wer lange beides erlebt, bekommt deshalb leichter Infektionen, selbst wenn alle Abwehrzellen vorhanden sind."],"correctIndex":0,"explanation":"HIV greift gezielt die Helfer-T-Zellen an, die „Kommandozentrale“ der adaptiven Immunantwort. Diese Zellen koordinieren die gesamte Operation, also auch die B-Zellen, die Antikörper bilden, und die Killer-T-Zellen. Fällt die Kommandozentrale aus, bricht das gesamte System zusammen. Ein gesunder Lebensstil unterstützt die Abwehr nur allgemein; er ersetzt aber keine spezifische Immunantwort. Dass sich ein Virus im Zellinneren vor Antibiotika schützt, erklärt, warum es bleibt, nicht aber, warum die Abwehr versagt. Eine Autoimmunreaktion ist eine fehlgeleitete Abwehr, hier geht es aber um den Verlust der koordinierenden Zellen. Schlafmangel und Mangelernährung schwächen die Abwehr zwar allgemein, lassen die koordinierenden Zellen aber nicht gezielt schwinden.","coreRule":"⚡ Ein System fällt nicht nur aus, wenn alles schwach ist, sondern auch, wenn sein zentraler Koordinator ausfällt. Bei HIV sind das die Helfer-T-Zellen.","beleg":"Werkstück C.4.3 (Anwendung & Relevanz, Bei AIDS & HIV)","status":"entwurf","scenario":"Bei einer HIV-Infektion sinkt die Zahl der Helfer-T-Zellen, die als Koordinatoren der gezielten (adaptiven) Abwehr arbeiten, über Jahre stark ab. Am Ende erkranken Betroffene an Infektionen, die ein gesundes Immunsystem problemlos beherrscht.","kurz":"HIV zerstört gezielt die Helfer-T-Zellen, die B- und Killer-T-Zellen koordinieren; ohne sie läuft die gezielte Abwehr ins Leere. Wer nur auf „mehr Abwehr“ setzt, übersieht, dass hier die Steuerung fehlt, nicht die Menge an Abwehrzellen.","prueffrage":"Was zeigen Blutwerte von Menschen mit HIV über die Jahre, und ändert eine gesunde Lebensweise etwas an diesem Verlauf?","rueckmeldung":[{"option":1,"text":"Dass sich Viren im Zellinneren vor Antibiotika schützen, ist richtig und erklärt, warum HIV im Körper bleibt. Warum die Abwehr dabei zusammenbricht, sagt es aber nicht, denn es setzt eine voll funktionsfähige Abwehr voraus."},{"option":2,"text":"Eine Autoimmunreaktion ist eine fehlgeleitete Abwehr gegen den eigenen Körper. Bei HIV ist das Problem das Gegenteil: Die koordinierenden Zellen gehen verloren, und Infektionen werden nicht mehr beherrscht."},{"option":3,"text":"Schlafmangel und Mangelernährung schwächen die Abwehr tatsächlich allgemein, daher klingt die Antwort naheliegend. Sie lassen die koordinierenden Zellen aber nicht gezielt schwinden, und ein gesunder Lebensstil ersetzt keine spezifische Immunantwort."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Human Immunodeficiency Virus (HIV) Infection","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/human-immunodeficiency-virus-hiv-infection/human-immunodeficiency-virus-hiv-infection","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC: About HIV","oeffentlich":true,"url":"https://www.cdc.gov/hiv/about/index.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1e27c063a168b849"}},{"id":"qx-c2-003","clusterId":"C","werkstueckRef":"C.4.3","stufe":3,"question":"Was ist an diesem Argument fehlerhaft, und wo wird aus einer an sich vernünftigen Sorge um die eigene Abwehr ein Risiko?","scenario":"In einem Forum steht: „Impfungen überlasten das Immunsystem. Stärk lieber deine Abwehr mit gesunder Ernährung, viel Schlaf und einem Immun-Tee, dann brauchst du keine Impfung.“","options":["Allgemeine Stärkung ersetzt nicht die spezifische Information über einen bestimmten Erreger; riskant wird es, wenn das vage Stärken gegen die Impfung ausgespielt wird.","Impfungen ersetzen keine Hygiene und gesunde Lebensweise; riskant wird es, wenn man sich allein auf eine Impfung verlässt und Händewaschen oder Schlaf vernachlässigt.","Mehr Vitamine bedeuten nicht automatisch eine stärkere Abwehr; riskant wird es, wenn man Nahrungsergänzung hoch dosiert einnimmt, weil Überschüsse schaden können.","Der Impfschutz lässt bei manchen Krankheiten mit der Zeit nach; riskant wird es, wenn man Auffrischungen versäumt und sich dauerhaft geschützt glaubt."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil unterstützt die allgemeine Funktion des Immunsystems, Ernährung und Schlaf sind also nicht wirkungslos. Aber weder Tee noch Schlaf noch Diät können ihm die spezifische Information geben, einen bestimmten Erreger wie Masern oder Tetanus zu erkennen. Genau das leistet eine Impfung: Sie zeigt dem Immunsystem ein harmloses Erkennungsmerkmal (ein Antigen), sodass es Gedächtniszellen aufbaut, ohne die echte Gefahr zu erleben. Der Überlastungs-Einwand trägt nicht, denn das Immunsystem begegnet täglich tausenden Antigenen. Die Sorge um die eigene Abwehr kippt dort ins Riskante, wo sie gegen die Impfung ausgespielt wird: Dann drohen vermeidbare Erkrankungen. Dass Impfungen keine Hygiene ersetzen, ist richtig, aber der Beitrag verlässt sich nicht auf die Spritze, sondern verwirft sie. Zu hohe Vitamindosen können schaden, doch von Nahrungsergänzung ist hier keine Rede. Und dass Impfschutz nachlassen kann, ist ein Grund für Auffrischungen, kein Fehler in diesem Argument.","coreRule":"⚡ Wer nur die allgemeine Abwehr stärkt, hat noch keine Information über den bestimmten Feind.","quote":"Die allgemeine Sorge um ein gesundes Immunsystem ist positiv.","quoteLabel":"Merksatz:","beleg":"Werkstück C.4.3 (Anwendung & Relevanz; Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ernährung und Schlaf unterstützen die Abwehr allgemein, doch keine Diät kann ihr beibringen, einen bestimmten Erreger zu erkennen. Genau das leistet die Impfung. Riskant wird die Sorge, wenn man sie gegen die Impfung ausspielt.","prueffrage":"Welche Belege nennt der Forumsbeitrag für seine beiden Behauptungen?","rueckmeldung":[{"option":1,"text":"Dass Impfungen Hygiene und gesunde Lebensweise nicht ersetzen, stimmt. Der Beitrag verlässt sich aber gerade nicht auf die Spritze, sondern verwirft sie. Der Fehler liegt also in der Gegenrichtung."},{"option":2,"text":"Zu hohe Vitamindosen können tatsächlich schaden. Im Beitrag ist aber nur von Ernährung, Schlaf und Tee die Rede, nicht von hoch dosierten Präparaten. Die Aufgabe fragt nach dem Fehler in diesem Argument."},{"option":3,"text":"Bei manchen Krankheiten kann der Impfschutz mit der Zeit nachlassen, deshalb gibt es Auffrischungen. Das ist aber kein Fehler dieses Beitrags, der gar nicht impfen will, statt Auffrischungen zu versäumen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"url","kurz":"Offit u. a. 2002, Addressing parents' concerns: do multiple vaccines overwhelm or weaken the infant's immune system?, Pediatrics 109(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1542/peds.109.1.124","url":"https://pubmed.ncbi.nlm.nih.gov/11773551/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7c491ea735328570"}},{"id":"qx-c2-004","clusterId":"C","werkstueckRef":"C.4.3","stufe":4,"question":"Wie lässt sich Jenners Rolle angesichts dieser Hinweise am treffendsten beschreiben?","scenario":"Im Geschichtsunterricht heißt es: „Edward Jenner hat 1796 die Impfung erfunden.“ Du recherchierst nach und findest zwei Hinweise: Ein Bauer namens Benjamin Jesty hatte seine Familie schon 1774 mit Kuhpocken geimpft. Außerdem wurde in Europa seit Jahrzehnten mit echtem Pockenmaterial geimpft (Variolation), was gelegentlich selbst Pocken auslöste.","options":["Er war der Erste, der Kuhpocken zum Impfen verwendete, und begründete damit ein Verfahren, das es zuvor in keiner Form gegeben hatte.","Er übernahm lediglich Jestys Verfahren; die Erfindung gebührt Jesty, und Jenners Rolle in der Geschichte ist deshalb unbedeutend.","Er prüfte ein bereits praktiziertes Verfahren systematisch, veröffentlichte die Ergebnisse und trug wesentlich zu seiner Verbreitung bei.","Ein Urteil über seine Rolle ist nicht möglich, solange nicht geklärt ist, wer als Erster geimpft hat; die Priorität entscheidet alles."],"correctIndex":2,"explanation":"Der Satz „X hat Y erfunden“ behauptet eine Priorität, und die lässt sich prüfen: Jesty impfte schon 1774 mit Kuhpocken, und die Variolation mit echtem Pockenmaterial war seit Jahrzehnten verbreitet. Damit fällt „erster Anwender“ weg. Jenners Leistung liegt in einem anderen Schritt: Er prüfte das Verfahren systematisch, veröffentlichte seine Ergebnisse 1798 und warb unermüdlich dafür; Antikörper und Gedächtniszellen kannte er nicht, diese Mechanismen wurden erst viel später verstanden. Bei Erfindungsgeschichten lohnt sich deshalb die Frage, was genau jemand getan hat: ausprobiert, belegt oder bekannt gemacht. Wer Jenner zum ersten Kuhpocken-Impfer macht, übersieht Jesty und die ältere Variolation; wer die Erfindung allein Jesty zuschreibt, übersieht dieselbe Variolation, und unbedeutend ist Jenners Beitrag ebenfalls nicht, denn Prüfung und Verbreitung sind eigene Leistungen. Dass die Frage der Priorität offen bleibt, hindert nicht daran, zu beurteilen, was Jenner nachweislich getan hat.","coreRule":"⚡ Bei Erfindungsmythen genau fragen, was jemand als Erster getan hat: Wer ein Verfahren zuerst benutzt, hat es noch nicht zuerst geprüft.","beleg":"Werkstück C.4.3 (Die Melkerinnen und die Pocken); Fn. gl-c-jenner (Jenner 1798; Riedel 2005, S. 22, 23 und 25)","status":"entwurf","kurz":"Jenner war nicht der Erste: Jesty impfte schon 1774, die Variolation ist noch älter. Seine Leistung liegt woanders: Er prüfte das Verfahren systematisch, veröffentlichte die Ergebnisse und verbreitete es. Wer nur nach dem Ersten fragt, übersieht das.","prueffrage":"Was genau tat Jenner 1796 und in den Jahren danach, und was davon ist durch Quellen belegt?","rueckmeldung":[{"option":0,"text":"Mit Kuhpocken impfte vor Jenner schon Jesty, und mit echtem Pockenmaterial wurde in Europa seit Jahrzehnten geimpft. Dass Jenners Name so eng mit der Impfung verbunden ist, macht die Antwort plausibel, nicht aber richtig."},{"option":1,"text":"Jesty impfte tatsächlich früher mit Kuhpocken. Daraus folgt aber weder, dass ihm „die Erfindung“ zufällt, denn die Variolation war älter, noch dass Jenner unbedeutend war: Prüfung und Verbreitung sind eigene Leistungen."},{"option":3,"text":"Wer zuerst impfte, ist hier tatsächlich schwer zu sagen. Daran hängt das Urteil aber nicht: Was Jenner nachweislich getan hat, lässt sich unabhängig von der Prioritätsfrage beurteilen."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Riedel 2005, Edward Jenner and the History of Smallpox and Vaccination, Baylor Univ Med Cent Proc 18(1) (PMC1200696)","oeffentlich":true,"doi":"10.1080/08998280.2005.11928028","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jenner 1798, An Inquiry into the Causes and Effects of the Variolæ Vaccinæ, London: Sampson Low","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f0220cab773cb947"}},{"id":"qx-c2-005","clusterId":"C","werkstueckRef":"C.4.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ein Mittel „heile Krebs“?","options":["Die Behauptung ist unplausibel, weil Krebs hunderte verschiedene Krankheiten mit je eigenen Mutationen umfasst, sodass ein einziges Mittel für alle kaum denkbar ist.","Die Behauptung ist unplausibel, weil ein Mittel, das Krebs heilt, für jeden Hersteller ein riesiges Geschäft wäre und sich deshalb kaum unterdrücken ließe.","Die Behauptung ist unplausibel, weil eine Unterdrückung des Mittels unzählige Mitwisser in aller Welt bräuchte und sich ein solches Geheimnis über Jahre nicht halten ließe.","Die Behauptung ist plausibel, weil natürliche Stoffe oft Vorbild für Arzneimittel sind und manche Krebsmedikamente ursprünglich aus Pflanzen gewonnen wurden."],"correctIndex":0,"explanation":"Unter „Krebs“ fallen hunderte verschiedene Krankheiten. Lungenkrebs verhält sich völlig anders als Hautkrebs, und jeder Tumor hat eine eigene genetische Signatur, denn Krebs entsteht, wenn körpereigene Zellen durch Mutationen in ihrer DNA die Kontrolle über Wachstum und Teilung verlieren. Schon deshalb ist die Idee „eines“ Heilmittels für alle Krebsarten biologisch unplausibel; moderne Therapien zielen auf die spezifischen Mutationen des jeweiligen Tumors. Die Verschwörungserzählung ersetzt diese Überlegung durch eine bequeme Schuldzuweisung. Dass ein heilendes Mittel ein gutes Geschäft wäre und sich eine Unterdrückung kaum geheim halten ließe, spricht zwar gegen die Verschwörungserzählung, sagt aber nichts über die Biologie des Krebses. Und dass viele Arzneimittel aus Pflanzen stammen, macht ein Mittel gegen alle Krebsarten nicht plausibler.","coreRule":"⚡ Krebs ist keine einzelne Krankheit, sondern hunderte; ein einziges Wundermittel für alle ist biologisch unplausibel.","beleg":"Werkstück C.4.4 (Kernidee; Kontext & Tiefe; Red Flags)","status":"entwurf","scenario":"Ein Beitrag im Netz verspricht: „Dieses natürliche Mittel heilt Krebs, doch die Pharmaindustrie unterdrückt es.“ Du willst herausfinden, ob die Behauptung biologisch überhaupt plausibel ist.","kurz":"Weil „Krebs“ hunderte verschiedene Krankheiten mit je eigenen Mutationen bündelt, ist ein einziges Heilmittel biologisch kaum denkbar. Der Fehler wäre, stattdessen die Verschwörungsgeschichte zu prüfen, die über die Biologie nichts sagt.","prueffrage":"Gleichen sich Lungenkrebs und Hautkrebs in Ablauf und Behandlung, oder unterscheiden sie sich deutlich?","rueckmeldung":[{"option":1,"text":"Das Argument spricht tatsächlich gegen die Verschwörungserzählung: Ein heilendes Mittel wäre ein Riesengeschäft. Gefragt war aber nach der biologischen Plausibilität, und dazu sagt das Geschäftsinteresse nichts."},{"option":2,"text":"Ein Geheimnis mit so vielen Mitwissern wäre schwer zu halten, das spricht gegen die Unterdrückungsgeschichte. Die Frage zielte aber auf die Biologie des Krebses, und dazu sagt dieses Argument nichts."},{"option":3,"text":"Daran stimmt: Viele Arzneimittel, auch manche Krebsmedikamente, haben pflanzliche Wurzeln. Woher ein Wirkstoff stammt, sagt aber nicht, ob er gegen hunderte verschiedene Krankheiten wirken kann; plausibler wird das Heilversprechen dadurch nicht."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cfb3471f73e8b468"}},{"id":"qx-c2-006","clusterId":"C","werkstueckRef":"C.4.4","stufe":2,"question":"Welche Antwort prüft die Behauptung am besten und liegt in der Sache richtig?","scenario":"Im Netz kursiert: „Man kann einen Tumor einfach aushungern oder entsäuern – mit der richtigen Diät.“ Eine Bekannte, deren Mutter an Krebs erkrankt ist, überlegt deshalb, die Behandlung zugunsten einer strengen Diät aufzuschieben.","options":["Ernährung kann das Erkrankungsrisiko beeinflussen, aber kein Ernährungsplan hungert einen bereits bestehenden Tumor aus oder „entsäuert“ ihn; er kann die Behandlung höchstens begleiten, nicht ersetzen.","Weil Tumoren viel Zucker verbrauchen, genügt eine strenge, lange durchgehaltene Diät, um sie auszuhungern; die Behandlung kann dann ruhig warten.","Ernährung hat auf Krebs überhaupt keinen Einfluss; weder das Risiko einer Erkrankung noch der Verlauf hängt davon ab, was man isst, daher ist jede Diät sinnlos.","Krebszellen reagieren besonders empfindlich auf Säure; eine konsequent basische Ernährung kann den Tumor deshalb zurückdrängen, und die Behandlung kann später folgen."],"correctIndex":0,"explanation":"Eine gesunde Ernährung kann das Krebsrisiko senken, doch ein bereits bestehender, durch Mutationen veränderter Tumor lässt sich nicht gezielt „aushungern“ oder „entsäuern“. Krebszellen sind anpassungsfähige Überlebenskünstler und finden immer einen Weg, sich zu ernähren. Ebenso verdächtig sind Theorien, die „den“ Krebs als eine einzige Krankheit mit einer einzigen Ursache und Heilung darstellen. Gefährlich wird so ein Ansatz, wenn er eine medizinische Behandlung ersetzt oder verzögert, denn bei Krebs entscheidet oft die Zeit zwischen heilbar und unheilbar. Die Behauptung, Krebs werde durch „Übersäuerung“ verursacht, ist ein klares Warnsignal für Krebs-Unsinn.","coreRule":"⚡ Ernährung kann das Risiko beeinflussen, aber sie heilt keinen bestehenden, mutierten Tumor. Wer sie als Ersatz für eine Behandlung anbietet, gefährdet Leben.","beleg":"Werkstück C.4.4 (Anwendung & Relevanz, Gegen „Krebs-Diäten“ & „Entgiftungs“-Mythen; Red Flags)","status":"entwurf","kurz":"Ernährung kann das Risiko beeinflussen, aber einen bestehenden Tumor weder aushungern noch entsäuern; die Zellen sind anpassungsfähig. Gefährlich wird die Diät, wenn sie die Behandlung ersetzt oder verzögert, denn bei Krebs entscheidet oft die Zeit.","prueffrage":"Gibt es Studien an Krebskranken, in denen eine Diät allein Tumoren verkleinert hat, und wer hat sie durchgeführt?","rueckmeldung":[{"option":1,"text":"Dass Tumorzellen viel Zucker verbrauchen, stimmt und lässt „Aushungern“ plausibel klingen. Die Zellen finden aber andere Wege, sich zu versorgen, und eine aufgeschobene Behandlung kann Zeit kosten, die über heilbar oder unheilbar entscheidet."},{"option":2,"text":"Daran stimmt, dass eine Diät einen bestehenden Tumor nicht beseitigt. Der Schluss, Ernährung habe nie Einfluss, geht aber zu weit: Eine gesunde Ernährung kann das Erkrankungsrisiko senken und die Behandlung begleiten. Sie ersetzt sie nur nicht."},{"option":3,"text":"Säure als Ursache und basische Kost als Gegenmittel wirken einfach und natürlich. Der Körper hält den Säuregrad des Blutes aber in engen Grenzen, eine Diät entsäuert keinen Tumor; wer dafür die Behandlung aufschiebt, verliert wertvolle Zeit."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"53896b83eab33431"}},{"id":"qx-c2-007","clusterId":"C","werkstueckRef":"C.4.4","stufe":3,"question":"Warum ist genau dieser Vorschlag gefährlich, obwohl Ernährung und Entspannung an sich nützlich sein können?","options":["Weil Ernährung und Entspannung die Wirkung einer Chemotherapie grundsätzlich abschwächen, sobald beides zusammen angewandt wird.","Weil Maßnahmen, die Nebenwirkungen der Behandlung lindern, den Tumor angeblich weniger stark bekämpfen lassen.","Weil jede Gewohnheit, die länger als einige Monate durchgehalten wird, die Krebszellen zur Anpassung und Resistenz zwingt.","Weil das Programm die Therapie ersetzen soll und der Patient so wertvolle Zeit verliert."],"correctIndex":3,"explanation":"Der Fehler liegt nicht in der Begleitung, sondern im Ersatz. Ein gesunder Lebensstil und psychologische Unterstützung können eine Krebstherapie sinnvoll ergänzen. Gefährlich wird es, wenn sie an die Stelle der Behandlung treten: Keine Diät kann einen bereits existierenden, genetisch mutierten Tumor aushungern, und wer stattdessen wartet, verliert wertvolle Zeit. Bei Krebs ist Zeit oft ein entscheidender Faktor, eine Verzögerung kann den Unterschied zwischen heilbar und unheilbar bedeuten. Die anderen Begründungen erfinden Wirkungen, die es nicht gibt: Ergänzende Maßnahmen schwächen die Therapie nicht pauschal ab, und eine Linderung von Nebenwirkungen lässt den Tumor nicht unbehandelt wachsen. Ebenso wenig zwingt eine Gewohnheit die Krebszellen allein durch ihre Dauer zur Resistenz. Resistenzen entstehen durch Selektion: Zellen, die Therapien am besten widerstehen, überleben und vermehren sich.","coreRule":"⚡ Begleiten ist erlaubt, ersetzen ist der Kipppunkt – bei Krebs zählt jede Verzögerung.","beleg":"Werkstück C.4.4 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Ein Patient hat gerade die Diagnose Krebs erhalten. Die Ärztin empfiehlt eine Operation mit anschließender Chemotherapie. Eine Anbieterin von „ganzheitlicher Krebsberatung“ sagt zu ihm: „Mit meinem Ernährungs- und Entspannungsprogramm brauchst du die Operation und die Chemotherapie nicht. Warte erst einmal ab, wie es wirkt.“","quote":"","quoteLabel":"","kurz":"Gefährlich ist nicht das Programm selbst, sondern dass es die Behandlung ersetzen soll. Wer abwartet, statt sich behandeln zu lassen, verliert Zeit, und bei Krebs kann eine Verzögerung über heilbar oder unheilbar entscheiden.","prueffrage":"Was verspricht die Anbieterin genau, und auf welche Belege für die Wirkung ihres Programms bei Tumoren stützt sie sich?","rueckmeldung":[{"option":0,"text":"Die Sorge, Zusätzliches könne die Therapie stören, liegt nahe. Ernährung und Entspannung schwächen eine Chemotherapie aber nicht grundsätzlich ab; gefährlich ist hier, dass das Programm die Behandlung ersetzen soll."},{"option":1,"text":"Dass eine Behandlung nur wirkt, wenn sie spürbar zusetzt, liegt nahe, weil Wirkung und Nebenwirkungen bei der Chemotherapie oft zusammen auftreten. Den Tumor bekämpft aber die Therapie selbst, gelinderte Beschwerden schwächen sie nicht."},{"option":2,"text":"Resistenz ist ein reales Phänomen, deshalb wirkt „Anpassung“ plausibel. Sie entsteht aber durch Selektion unter Therapie, nicht durch lange durchgehaltene Gewohnheiten, und mit der Gefahr dieses Vorschlags hat das nichts zu tun."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"195f46467fe75f0b"}},{"id":"qx-c2-008","clusterId":"C","werkstueckRef":"C.4.4","stufe":4,"question":"Eine Patientin liest: „Der Tumor sprach auf die Chemotherapie zunächst gut an, ist nach einem Jahr aber trotz unveränderter Behandlung wieder gewachsen.“ Sie fragt, ob die Therapie von Anfang an gelogen war. Welche Erklärung ist die sparsamste?","options":["Unter der Therapie überleben vor allem Zellen, die sie besser vertragen. Sie vermehren sich weiter, und der Tumor besteht bald überwiegend aus ihren Nachkommen.","Manche Chemotherapien lösen Jahre später einen neuen, zweiten Tumor aus. Der jetzt wachsende Tumor ist deshalb ein anderer als der ursprünglich behandelte.","Bei manchen Medikamenten gewöhnt sich der Körper daran und baut sie schneller ab. Dann erreicht weniger Wirkstoff den Tumor, obwohl alle Tumorzellen gleich empfindlich bleiben.","Der Tumor bildet mit der Zeit neue Blutgefäße, die ihn mit Nährstoffen versorgen. Dadurch wächst er wieder, obwohl die Therapie alle Zellen weiterhin gleich gut trifft."],"correctIndex":0,"explanation":"Ein Tumor ist keine einheitliche Masse, sondern ein Gemisch aus Zellen mit leicht unterschiedlichen Mutationen, die um Platz und Nährstoffe konkurrieren. Eine Therapie wirkt wie ein Filter: Zellen, die sie schlechter vertragen, sterben, und die Zellen, die sie besser überstehen, vermehren sich weiter. Das ist natürliche Selektion im Kleinen, und sie erklärt den Rückfall ohne Zusatzannahmen; die Behandlung war also nicht „gelogen“, sie hat die empfindlichen Zellen tatsächlich getroffen. Ein Zweittumor nach früherer Chemotherapie kommt vor, wäre aber ein neuer Krebs und erklärt nicht, warum derselbe Tumor wieder wächst. Eine Gewöhnung des Körpers an ein Medikament gibt es bei manchen Mitteln, doch hier sind die Tumorzellen ja gerade unterschiedlich empfindlich. Neue Blutgefäße ermöglichen Wachstum, erklären aber nicht, warum die Therapie plötzlich nicht mehr trifft.","coreRule":"⚡ Ein Tumor ist Evolution im Kleinen: Was die Therapie überlebt, vermehrt sich – und der Rückfall ist dann kein Widerspruch, sondern genau das, was man erwarten muss.","beleg":"Werkstück C.4.4 (Kontext & Tiefe, Krebs ist Evolution im eigenen Körper)","status":"entwurf","scenario":"Ein erkennbarer Tumor besteht meist aus Milliarden Zellen, die sich bei jeder Teilung leicht verändern können. Eine Therapie tötet nicht alle diese Zellen gleich gut.","kurz":"Der Tumor ist ein Gemisch unterschiedlich empfindlicher Zellen. Die Therapie traf die empfindlichen, die besser überlebenden vermehrten sich weiter. Der Rückfall ist also kein Beleg dafür, dass sie von Anfang an wirkungslos war.","prueffrage":"Sprechen die Zellen, die nach einem Jahr wachsen, noch genauso auf das Mittel an wie die Zellen zu Beginn?","rueckmeldung":[{"option":1,"text":"Zweittumoren nach einer Chemotherapie kommen tatsächlich vor. Dann wäre der wachsende Tumor aber ein neuer Krebs, und das erklärt nicht, warum der behandelte Tumor selbst wieder wächst."},{"option":2,"text":"Bei manchen Medikamenten wird der Wirkstoff tatsächlich schneller abgebaut. Die Option setzt aber gleich empfindliche Tumorzellen voraus, obwohl sie sich bei jeder Teilung verändern. Zudem braucht sie eine zusätzliche Annahme."},{"option":3,"text":"Neue Blutgefäße können einen Tumor mit Nährstoffen versorgen und sein Wachstum ermöglichen. Warum die Therapie dann nicht mehr wirkt, klärt das nicht, denn die Option lässt alle Zellen gleich gut getroffen bleiben."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dfa4f88ebf002347"}},{"id":"qx-c2-009","clusterId":"C","werkstueckRef":"C.4.5","stufe":1,"question":"Was ist an dem Schluss der Mitprobandin fehlerhaft, und was erklärt deine Beschwerden am besten?","scenario":"In einer Medikamentenstudie klärt dich eine Ärztin ausführlich über mögliche Nebenwirkungen des Prüfmittels auf. Kurz nach der Einnahme bekommst du Kopfschmerzen und Übelkeit. Später wird bekannt, dass du zur Placebo-Gruppe gehörtest und nur eine wirkstofffreie Tablette erhalten hast. Eine Mitprobandin sagt: „Dann hast du dir die Beschwerden nur eingebildet.“","options":["Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „keine Wirkung“, denn auch ein Placebo kann Beschwerden lindern, weil es die Hoffnung auf Besserung weckt.","Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „keine echten Beschwerden“, denn negative Erwartungen können reale körperliche Symptome auslösen.","Der Schluss ist fehlerhaft: Aus einem einzelnen Fall lässt sich nichts folgern, denn erst Vergleiche vieler Teilnehmender zeigen, ob eine Tablette Beschwerden auslöst.","Der Schluss ist fehlerhaft: Wer sich in einer Studie beobachtet fühlt, verhält sich anders (Beobachtungseffekt), denn dadurch verändert sich, was gemessen wird."],"correctIndex":1,"explanation":"Die Mitprobandin vermischt zwei Dinge: „ohne Wirkstoff“ und „ohne echte Wirkung“. Wer über mögliche Nebenwirkungen aufgeklärt wird, verspürt mit höherer Wahrscheinlichkeit genau diese, auch wenn er nur eine Scheinbehandlung bekommt; das heißt Nocebo-Effekt, das Gegenstück zum Placebo. Negative Erwartungen können zum Beispiel die Stressachse des Körpers anregen (vgl. Colloca & Barsky 2020, New England Journal of Medicine). Die Symptome sind also real; ihr Auslöser ist die Erwartung, nicht ein Wirkstoff. Ein Placebo kann zwar auch Beschwerden lindern, doch du hattest keine Besserung, sondern genau die angekündigten Beschwerden. Dass ein Einzelfall wenig beweist, stimmt, die Mitprobandin irrt aber an anderer Stelle. Und der Beobachtungseffekt betrifft verändertes Verhalten, nicht die angekündigten Symptome.","coreRule":"⚡ Erwartung wirkt in beide Richtungen: Placebo bessert, Nocebo belastet. „Kein Wirkstoff“ heißt nicht „keine echten Symptome“.","beleg":"Werkstück C.4.5 (Kernidee; Kontext & Tiefe); Fn. gl-c-colloca (Colloca/Barsky 2020, NEJM 382, S. 554–561)","status":"entwurf","kurz":"Aus „kein Wirkstoff“ folgt nicht „keine echten Beschwerden“. Wer ausführlich über Nebenwirkungen aufgeklärt wird, erwartet sie, und diese Erwartung kann reale Symptome auslösen (Nocebo-Effekt), auch ohne Wirkstoff.","prueffrage":"Was hat die Ärztin vor der Einnahme erklärt, und welche Beschwerden traten kurz danach auf?","rueckmeldung":[{"option":0,"text":"Ein Placebo kann tatsächlich Beschwerden lindern, und der Satz „kein Wirkstoff, also keine Wirkung“ ist wirklich zu einfach. Bei dir ist aber keine Besserung eingetreten, sondern genau das, was angekündigt war. Das ist die umgekehrte Richtung."},{"option":2,"text":"Ein einzelner Fall beweist tatsächlich wenig. Die Mitprobandin irrt aber an anderer Stelle: Sie setzt „kein Wirkstoff“ mit „keine echten Beschwerden“ gleich. Und die Frage, was deine Beschwerden erklärt, bleibt hier offen."},{"option":3,"text":"Dass Beobachtung Verhalten verändern kann, ist real. Es erklärt aber nicht, warum gerade die zuvor angekündigten Beschwerden auftraten. Dafür ist die ausführliche Aufklärung der naheliegende Auslöser, nicht das Gefühl, beobachtet zu werden."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Häuser, Hansen & Enck 2012, Nocebo phenomena in medicine: their relevance in everyday clinical practice, Dtsch Arztebl Int 109(26) (PMC3401955)","oeffentlich":true,"doi":"10.3238/arztebl.2012.0459","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Colloca & Barsky 2020, Placebo and Nocebo Effects, New England Journal of Medicine 382(6)","oeffentlich":false,"doi":"10.1056/NEJMra1907805"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6bce6a7f3ddee3da"}},{"id":"qx-c2-010","clusterId":"C","werkstueckRef":"C.4.5","stufe":2,"question":"Was folgt aus der Umfrage des Herstellers für seine Behauptung?","scenario":"Ein Hersteller wirbt: „Unsere blaue Tablette beruhigt nachweislich stärker als die rote.“ Als Beleg nennt er eine Umfrage, in der Testpersonen die blaue Tablette beruhigender fanden und sie sich nach der Einnahme ruhiger fühlten. Wirkstoff und Dosis beider Tabletten sind laut Hersteller identisch.","options":["Sie zeigt nur, dass die Farbe Erwartungen weckt und das Empfinden prägt; ob sie auch die tatsächliche Wirkung verändert, bleibt offen.","Sie sagt kaum etwas aus, weil eine Vergleichsgruppe ohne Tablette fehlt; ohne unbehandelte Kontrollgruppe lässt sich keine Wirkung beurteilen.","Sie spricht dafür, dass sich die Wirkung von Medikamenten allgemein über die Farbe steuern lässt, denn die Befragten reagierten auf die blaue Tablette stärker.","Sie spricht dafür, dass die blaue Tablette ihren Wirkstoff schneller freisetzt, denn die Testpersonen fühlten sich nach ihr ruhiger."],"correctIndex":0,"explanation":"Schon die Farbe einer Pille prägt die Erwartung: Blau und Grün verbinden Menschen eher mit einer beruhigenden Wirkung. Wer eine blaue Tablette für beruhigend hält und sie dann einnimmt, fühlt sich deshalb oft tatsächlich ruhiger. Das ist ein Erwartungseffekt, der durch Symbolik und Kontext entsteht. Die Umfrage erfasst nur das Empfinden der Testpersonen. Ob die Farbe auch die tatsächliche Wirkung verändert, ist weniger klar: In einem Überblick über zwölf Studien (de Craen u. a. 1996) fielen die Befunde zur Wirksamkeit uneinheitlich aus. Der Schluss von „fühlt sich beruhigender an“ auf „wirkt stärker“ ist deshalb nicht gedeckt. Eine Vergleichsgruppe gibt es bereits, nämlich die rote Tablette mit gleichem Wirkstoff. Von einem einzelnen Produkt lässt sich nicht auf alle Medikamente schließen. Und aus Angaben zum Befinden lässt sich nicht ableiten, wie schnell ein Wirkstoff freigesetzt wird.","coreRule":"⚡ Wer nur das Empfinden nach einer Behandlung erfasst, misst auch die Erwartung mit. Ob ein Merkmal wie die Pillenfarbe die Wirkung selbst verändert, zeigt erst ein verblindeter Vergleich.","beleg":"Werkstück C.4.5 (Kontext & Tiefe, Die Symbolik); Fn. gl-c-pillenfarbe (de Craen u. a. 1996, BMJ 313, S. 1624–1626)","status":"entwurf","kurz":"Die Umfrage erfasst nur, wie ruhig sich die Testpersonen fühlten, und dieses Gefühl kann schon die blaue Farbe prägen. Ob die Tablette tatsächlich stärker wirkt, bleibt offen; wer von „fühlt sich beruhigender an“ auf „wirkt stärker“ schließt, übergeht diese Lücke.","prueffrage":"Wer hat in der Umfrage was angegeben, und gab es daneben eine Messung, die nicht von den Testpersonen selbst stammt?","rueckmeldung":[{"option":1,"text":"Dass der Beleg dünn ist, stimmt. Eine Vergleichsgruppe gibt es aber bereits: die rote Tablette mit gleichem Wirkstoff und gleicher Dosis. Schwach ist die Umfrage, weil sie nur das Empfinden erfasst, nicht die tatsächliche Wirkung."},{"option":2,"text":"Von einem einzelnen Produkt lässt sich nicht auf alle Medikamente schließen. Selbst für diese Tablette zeigt die Umfrage nur das Empfinden der Befragten, nicht, ob die Farbe die tatsächliche Wirkung verändert."},{"option":3,"text":"Dass sich jemand nach der Einnahme ruhiger fühlt, sagt nichts darüber, wie schnell ein Wirkstoff freigesetzt wird. Zur Freisetzung gibt das Szenario keinerlei Hinweis, und das Gefühl lässt sich schon durch die Farbe und die damit verbundene Erwartung erklären."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"de Craen u. a. 1996, Effect of colour of drugs: systematic review of perceived effect of drugs and of their effectiveness, BMJ 313 (PMC2359128)","oeffentlich":true,"doi":"10.1136/bmj.313.7072.1624","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2cf2398d22f702ac"}},{"id":"qx-c2-011","clusterId":"C","werkstueckRef":"C.4.5","stufe":3,"question":"In einem Vortrag heißt es: „Ein Patient mit orangengroßen Tumoren bekam eine Spritze mit einem angeblichen Wundermittel, die Tumoren verschwanden. Später erfuhr er, dass das Mittel wertlos sei, und der Krebs kam zurück. Glaube kann also Tumoren schmelzen lassen.“ Was ist der entscheidende Haken an diesem Beleg?","options":["Der Bericht beruht auf Tierversuchen, und deren Ergebnisse lassen sich nicht ohne Weiteres auf den Menschen übertragen.","Die berichtenden Ärzte hatten ein finanzielles Eigeninteresse am Mittel, sodass ein Interessenkonflikt den Bericht verzerrt.","Die Richtung der Ursache ist unklar: Womöglich schrumpften die Tumoren zuerst und lösten den Glauben aus (umgekehrte Kausalität).","Es ist ein einzelner, nachträglicher Bericht ohne Vergleichsgruppe, der Spontanverläufe und Erinnerungsfehler nicht ausschließt."],"correctIndex":3,"explanation":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe kann nicht zeigen, was die Ursache war. Spontane Verläufe, Fehldiagnosen und Erinnerungsfehler passen genauso zur Geschichte wie ein Erwartungseffekt, und ob sich alles so zugetragen hat, lässt sich gar nicht prüfen. Dazu kommt der Abgleich mit der Datenlage: Kontrollierte Studien finden Placebo-Wirkungen fast nur bei Beschwerden, die Patienten selbst einschätzen, etwa Schmerz oder Übelkeit. Die große Cochrane-Übersicht (Hróbjartsson und Gøtzsche, 2010) fand insgesamt keine wichtigen klinischen Wirkungen von Placebos „im Allgemeinen“. Dass Glaube einen Tumor auflöst, wäre deshalb eine außergewöhnliche Behauptung, für die ein Einzelfall als Beleg nicht reicht. Der Fall ist allerdings auch nicht „widerlegt“: Man kann ihn nicht prüfen, und genau das macht ihn als Beweis wertlos. Die anderen Gedanken sind als allgemeine Warnungen bedenkenswert, passen aber nicht auf diesen Fall: Berichtet wird von einem Patienten, nicht von einem Tierversuch. Von einem finanziellen Eigeninteresse der Ärzte ist keine Rede. Und die Spritze kam vor dem Verschwinden der Tumoren, die Richtung des Zusammenhangs ist also nicht vertauscht.","coreRule":"⚡ Ein Einzelfall ohne Vergleich beweist keine Wirkung, auch kein Wunder.","beleg":"Werkstück C.4.5 (Die Operation ohne Skalpell; Kontext & Tiefe); Fn. gl-c-klopfer (Klopfer 1957, S. 337–339); Fn. gl-c-placebo-grenzen (Hróbjartsson/Gøtzsche 2010, Cochrane CD003974)","status":"entwurf","scenario":"Der Fall stammt aus den 1950er Jahren und wurde erst nachträglich aufgeschrieben, nach einer persönlichen Mitteilung eines der behandelnden Ärzte. Eine Vergleichsgruppe gab es nicht.","kurz":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe zeigt nicht, was die Tumoren schwinden ließ. Spontane Verläufe oder Erinnerungsfehler passen genauso gut zur Geschichte wie ein Erwartungseffekt, und prüfen lässt sich der Fall nicht.","prueffrage":"Wann und von wem wurde der Fall aufgeschrieben, und lässt sich heute noch nachprüfen, was damals mit dem Patienten geschah?","rueckmeldung":[{"option":0,"text":"Dass Tierversuche nicht ohne Weiteres auf Menschen übertragbar sind, ist eine berechtigte Warnung. Hier passt sie aber nicht: Berichtet wird von einem Patienten, nicht von einem Tierversuch."},{"option":1,"text":"Ein Eigeninteresse der Berichtenden ist ein gutes Warnsignal. In der Schilderung steht davon aber nichts, die Option fügt eine Voraussetzung hinzu. Der Haken liegt in der Art des Berichts selbst."},{"option":2,"text":"Umgekehrte Kausalität gibt es wirklich. Hier passt sie aber nicht zur Reihenfolge: Die Spritze kam zuerst, danach verschwanden die Tumoren. Die Richtung des Zusammenhangs ist nicht vertauscht, das Problem ist ein anderes."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hróbjartsson & Gøtzsche 2010, Placebo interventions for all clinical conditions, Cochrane Database Syst Rev (PMC7156905)","oeffentlich":true,"doi":"10.1002/14651858.CD003974.pub3","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Klopfer 1957, Psychological variables in human cancer, Journal of Projective Techniques 21(4)","oeffentlich":false,"doi":"10.1080/08853126.1957.10380794"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c707a4b76f8df101"}},{"id":"qx-c2-012","clusterId":"C","werkstueckRef":"C.4.5","stufe":4,"question":"Welche Schlussfolgerung ist aus diesem Befund am besten begründet?","scenario":"Eine Kollegin bekommt Kopfschmerzen, sobald sie glaubt, der WLAN-Router laufe – auch dann, wenn er ausgeschaltet ist. Eine große, im Auftrag der WHO erstellte Übersicht von 41 Experimenten kommt zu folgendem Ergebnis: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen auf Beschwerden. Beschwerden traten aber häufiger auf, wenn den Versuchspersonen eine Strahlung angekündigt wurde. Das galt unabhängig davon, ob wirklich gesendet wurde.","options":["Die Beschwerden gehen auf Regression zur Mitte zurück, weil Kopfschmerzen nach einem Höhepunkt meist von selbst wieder nachlassen.","Die Erwartung der Kollegin ist der naheliegende Auslöser, weil die Beschwerden dem geglaubten und nicht dem tatsächlichen Reiz folgen.","Eine dritte Größe wie Bildschirmarbeit ist der naheliegende Auslöser, weil sie Router-Nutzung und Kopfschmerzen gleichermaßen begünstigen kann.","Der Befund ist kaum aussagekräftig, weil ohne eine Vergleichsbedingung nicht zu klären ist, was Funkfelder tatsächlich bewirken."],"correctIndex":1,"explanation":"Die Übersicht fand: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen, Symptome traten aber vermehrt auf, wenn die Exposition angekündigt war – also bezogen auf den wahrgenommenen, nicht auf den realen Feldzustand. Das spricht dafür, dass nicht die Strahlung, sondern die Erwartung die Beschwerden erzeugt. Das erklärt auch den Fall der Kollegin: Ihre Kopfschmerzen sind real, die negative Erwartung kann sie erzeugen (Nocebo-Effekt). „Real“ heißt also nicht „von außen verursacht“, und „von der Erwartung verursacht“ heißt nicht „erfunden“. Auf den Einzelfall übertragen ist das nur eine Wahrscheinlichkeitsaussage: Die Erwartung ist die naheliegendste Erklärung, aber im Einzelfall bleibt es eine Schlussfolgerung. Ob sie bei der Kollegin zutrifft, ließe sich nur durch eine verblindete Prüfung klären. Die anderen Gedanken sind bekannte Erklärungen, passen hier aber nicht: Regression zur Mitte betrifft das Abklingen nach einem Höhepunkt, nicht Beschwerden, die dem Glauben an den Router folgen. Eine dritte Größe erklärt nicht, warum die Beschwerden dem Glauben statt dem tatsächlichen Senden folgen, denn genau das wurde in den Versuchen getrennt. Und Vergleichsbedingungen gab es durchaus: echte gegen nicht gesendete Felder, angekündigte gegen nicht angekündigte.","coreRule":"⚡ Wo die Beschwerden dem geglaubten statt dem tatsächlichen Reiz folgen, liegt Nocebo nahe.","beleg":"Werkstück C.4.5 (Bei Verschwörungsmythen, Nocebo); Fn. gl-c-nocebo-emf (Bosch-Capblanch u. a. 2024, Environment International 187, Art. 108612)","status":"entwurf","kurz":"Die Beschwerden folgten dem geglaubten, nicht dem tatsächlichen Senden, das spricht für die Erwartung als Auslöser. Der Fehler liegt darin, „real gespürt“ mit „von außen verursacht“ gleichzusetzen. Im Einzelfall bleibt es die naheliegendste Erklärung.","prueffrage":"Wann treten die Beschwerden auf, und was passiert in den Fällen, in denen der Router gar nicht läuft?","rueckmeldung":[{"option":0,"text":"Dass Kopfschmerzen nach einem Höhepunkt oft von selbst nachlassen, ist ein bekanntes Prinzip. Es erklärt aber nicht, warum die Beschwerden dem Glauben an den Router folgen, auch bei ausgeschaltetem Gerät."},{"option":2,"text":"Bildschirmarbeit oder Ähnliches kann als gemeinsame Ursache tatsächlich Zusammenhänge erzeugen. Hier folgen die Beschwerden aber dem Glauben statt dem realen Senden, und genau das trennten die Versuche. Das erklärt eine dritte Größe nicht."},{"option":3,"text":"Vergleichsbedingungen gab es durchaus: echte gegen nicht gesendete Felder und angekündigte gegen nicht angekündigte Strahlung. Nur für die Kollegin selbst bleibt es eine Wahrscheinlichkeitsaussage, nicht für den Befund insgesamt."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Bosch-Capblanch u. a. 2024, The effects of radiofrequency electromagnetic fields exposure on human self-reported symptoms: A systematic review of human experimental studies, Environment International 187 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1016/j.envint.2024.108612","url":"https://pubmed.ncbi.nlm.nih.gov/38640611/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6b6263058a003fc0"}},{"id":"qx-c2-013","clusterId":"C","werkstueckRef":"C.4.6","stufe":1,"question":"Ein Freund erzählt dir begeistert: „Ich hatte eine schwere Erkältung, am schlimmsten ging es mir am dritten Tag. Da habe ich einen Kräutertee für 50 Euro gekauft. Vier Tage später war ich fast beschwerdefrei. Der Tee wirkt!“ Welche Erklärung für seine Besserung ist am sparsamsten, wenn du nur dieses Wissen hast?","options":["Die Besserung erklärt sich auch ohne Wirkung des Tees: Erkältungen klingen von allein ab, und gekauft wurde der Tee auf dem Höhepunkt der Beschwerden.","Die Besserung erklärt sich durch einen Störfaktor: Er hat vermutlich gleichzeitig ein weiteres Mittel genommen, das die Beschwerden gelindert hat.","Die Besserung erklärt sich durch umgekehrte Kausalität: Er hat den Tee erst gekauft, als es ihm schon besser ging, und beides nur verknüpft.","Die Besserung erklärt sich durch Überlebensverzerrung: Von Misserfolgen hört man kaum etwas, deshalb gelten Erfolgsgeschichten als typisch."],"correctIndex":0,"explanation":"Erkältungen sind selbstlimitierend: Das Immunsystem heilt sie meist von allein. Wer sich auf dem Höhepunkt der Beschwerden zu einer Behandlung entschließt, startet an einem Punkt, von dem aus es ohnehin bergauf geht. Dazu kommt die Erwartung, dass das Mittel hilft (Placebo-Effekt). Die zeitliche Abfolge „Mittel genommen, dann besser“ sagt nichts darüber, ob das Mittel die Ursache war (Post-hoc-Fehlschluss). Mit einer Kontrollgruppe ohne Behandlung ließe sich der natürliche Verlauf von einer echten Wirkung trennen. Aus dem Fall folgt weder, dass der Tee wirkt, noch dass er sicher wirkungslos ist. Die anderen Gedanken sind bekannte Denkfehler oder Störquellen, passen aber nicht zu diesem Fall: Von einem zweiten Mittel ist keine Rede, die sparsamste Erklärung braucht keines. Gekauft wurde der Tee am schlimmsten Tag, nicht erst nach der Besserung. Und Überlebensverzerrung erklärt, warum man Erfolgsgeschichten häufiger hört, nicht aber, warum es diesem Freund besser ging.","coreRule":"⚡ Besserung nach einem Mittel ist noch keine Wirkung des Mittels.","beleg":"Werkstück C.4.6 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Eine Erkältung klingt meist von selbst ab, und der Tee wurde auf dem Höhepunkt gekauft, als es ohnehin bergauf ging. Dass der Tee vor der Besserung kam, macht ihn noch nicht zur Ursache. Das lässt sich nur mit Vergleichsfällen ohne Tee prüfen.","prueffrage":"An welchem Tag kaufte dein Freund den Tee, und wie ging es ihm an diesem Tag im Vergleich zu den Tagen davor?","rueckmeldung":[{"option":1,"text":"Dass mehrere Mittel zugleich wirken, kommt vor und verwischt manchmal Wirkungen. Hier ist aber von keinem zweiten Mittel die Rede. Eine Erklärung, die etwas Zusätzliches annehmen muss, ist gerade nicht die sparsamste."},{"option":2,"text":"Umgekehrte Kausalität gibt es, sie passt aber nicht zur Schilderung: Der Tee wurde am dritten Tag gekauft, dem schlimmsten, nicht erst nach der Besserung. Die Reihenfolge im Fall spricht gegen diese Deutung."},{"option":3,"text":"Überlebensverzerrung erklärt, warum wir vor allem Erfolgsgeschichten hören. Sie sagt aber nichts darüber, warum es genau diesem Freund besser ging. Sie beantwortet damit eine andere Frage als die gestellte."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0e6a1ba62d39f5bc"}},{"id":"qx-c2-014","clusterId":"C","werkstueckRef":"C.4.6","stufe":2,"question":"Welche Erklärung für den Leistungsabfall ist am besten begründet?","scenario":"Eine Tennisspielerin hat die beste Saison ihrer Karriere gespielt und landet deshalb auf dem Titel eines Sportmagazins. In der Folgesaison spielt sie schlechter, bleibt aber weiter eine starke Spielerin. Kollegen sprechen vom „Fluch des Covers“.","options":["Der Medienrummel lenkt Sportlerinnen so ab, dass ihre Leistung danach dauerhaft unter dem früheren Durchschnitt liegt und kaum zurückkehrt.","Profi-Leistungen sind frei von Zufall, weshalb als Ursache nur psychologischer Druck oder Verletzungen in Frage kommen.","Sie kam aufs Cover, weil ihre Leistung gerade außergewöhnlich hoch war; nach einem Extremwert liegt der nächste meist wieder näher am Normalniveau.","Magazine wählen bevorzugt Sportlerinnen, die ihren Karrierehöhepunkt bereits überschritten haben und ohnehin schon nachlassen."],"correctIndex":2,"explanation":"Eine Rekordsaison ist ein Extremwert, und genau deshalb erscheint die Spielerin auf dem Cover. In jedem System, in das Zufall involviert ist, liegt nach einem Extremwert der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt. Diese Regression zur Mitte erklärt den Abfall ohne zusätzliche Annahmen, denn sie braucht weder einen Fluch noch eine dauerhafte Ablenkung. Die Spielerin kann dabei weiterhin sehr gut sein, nur nicht mehr auf dem außergewöhnlichen Höhepunkt. Das erwartete Muster wäre also: Rückgang, aber weiterhin starkes Niveau. Dasselbe Prinzip erklärt, warum nach dem schlimmsten Tag einer schwankenden Krankheit mit hoher Wahrscheinlichkeit eine Besserung folgt, unabhängig von einer Behandlung.","coreRule":"⚡ Wer wegen einer Rekordleistung auffällt, wird danach meist wieder normaler – ohne Fluch.","beleg":"Werkstück C.4.6 (Anwendung & Relevanz, In der Sport- und Wirtschaftswelt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"9ced5798fb44a856","vermerk":"Prüfpult"},"kurz":"Aufs Cover kam sie wegen eines Extremwerts, und nach einem Extremwert liegt der nächste Wert wahrscheinlich näher am Durchschnitt. Ein Fluch ist dafür nicht nötig: Rückgang bei weiter starkem Niveau ist genau das zu Erwartende.","prueffrage":"Wie lagen ihre Ergebnisse in den Jahren vor der Rekordsaison, und wo liegt die Folgesaison im Vergleich dazu?","rueckmeldung":[{"option":0,"text":"Medienrummel kann tatsächlich Kraft kosten, daher wirkt die Erklärung plausibel. Sie behauptet aber einen dauerhaften Abfall unter das frühere Niveau, wofür eine einzige Saison nichts zeigt; die Spielerin bleibt stark."},{"option":1,"text":"Druck und Verletzungen kommen als Ursachen durchaus vor. Falsch ist aber die Voraussetzung: Auch Profi-Leistungen schwanken, etwa durch Tagesform oder knappe Sätze, und diese Schwankung kann den Rückgang ohne weitere Ursache erklären."},{"option":3,"text":"Dass die Auswahl vom Leistungsverlauf abhängt, ist richtig gedacht, aber die Reihenfolge stimmt nicht: Sie kam aufs Cover, weil sie auf dem Höhepunkt stand, nicht weil sie schon nachließ. Die Auswahl erfolgte also nach einem Extremwert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9ced5798fb44a856"}},{"id":"qx-c2-015","clusterId":"C","werkstueckRef":"C.4.6","stufe":3,"question":"Bei welcher Art von Erkrankung wäre sein Vorhaben am gefährlichsten?","options":["Bei einer Krankheit, die weder von allein abklingt noch schwankt, etwa Typ-1-Diabetes, weil die Methode dort eine wirksame Therapie ersetzen würde.","Bei einer Krankheit, die ohnehin von allein abklingt, etwa einer Erkältung, weil die Methode dort den Verlauf spürbar verlängern würde.","Bei einer Krankheit mit stark schwankenden Beschwerden, etwa unspezifischen Rückenschmerzen, weil dort Besserung und Verschlechterung kaum zu unterscheiden wären.","Bei einer Krankheit, die länger als eine Woche dauert, etwa einem hartnäckigen Husten, weil die Erwartung dann ihre Wirkung verlöre und jede Linderung ausbliebe."],"correctIndex":0,"explanation":"Eine Methode, die nur von Erwartung, Selbstheilung und Regression zur Mitte lebt, richtet bei Krankheiten, die ohnehin abklingen oder stark schwanken, kaum Schaden an: Die Besserung wäre auch ohne sie gekommen, und der Körper bekommt Zeit zur Heilung. Gefährlich wird es erst dort, wo eine Besserung nicht von allein zu erwarten ist, etwa bei Typ-1-Diabetes, einer schweren bakteriellen Infektion oder den meisten Krebsarten. Dort entsteht der Schaden nicht durch die Methode selbst, sondern dadurch, dass sie eine wirksame Therapie verdrängt und wertvolle Zeit verloren geht. Die Frage „Wäre es auch von allein besser geworden?“ entscheidet also nicht nur darüber, ob du eine Heilungsgeschichte glaubst, sondern auch darüber, wie riskant der Einsatz ist.","coreRule":"⚡ Gefährlich wird eine Scheinwirkung dort, wo die Krankheit nicht von allein besser wird und die Methode die echte Therapie ersetzt.","beleg":"Werkstück C.4.6 (Der Kipppunkt)","status":"entwurf","scenario":"Ein Bekannter schwärmt: „Die sanfte Naturmethode hat mir und meiner Familie schon oft geholfen. Ich nehme sie jetzt einfach bei allem.“ Du weißt: Ihre Wirkung beruht nur auf Erwartung, Selbstheilung und dem Abflachen zufälliger Beschwerdespitzen.","kurz":"Gefährlich wird die Methode dort, wo keine Besserung von allein zu erwarten ist: Sie verdrängt dann eine wirksame Therapie, und wertvolle Zeit geht verloren. Bei Krankheiten, die abklingen oder schwanken, richtet sie kaum Schaden an.","prueffrage":"Was geschieht bei jeder der genannten Krankheiten, wenn sie gar nicht wirksam behandelt wird?","rueckmeldung":[{"option":1,"text":"Dass eine Erkältung von allein abklingt, stimmt. Gerade deshalb verlängert eine wirkungslose Methode den Verlauf nicht spürbar: Die Besserung käme auch so, und der Körper bekommt die Zeit, die er zur Heilung braucht."},{"option":2,"text":"Bei schwankenden Beschwerden lässt sich tatsächlich schwer sagen, ob eine Besserung von der Methode kommt. Gefährlich ist das aber kaum: Die Beschwerdespitzen flachen ohnehin wieder ab, die Besserung käme also auch ohne sie."},{"option":3,"text":"Dass die Erwartung nach einer Woche ihre Wirkung verlöre, ist nicht belegt und erklärt keine Gefahr. Entscheidend ist nicht die Dauer, sondern ob eine Besserung von allein zu erwarten ist und eine wirksame Therapie verdrängt würde."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hanna u. a. 2020, Mortality due to cancer treatment delay: systematic review and meta-analysis, BMJ 371 (PMC7610021)","oeffentlich":true,"doi":"10.1136/bmj.m4087","abruf":"2026-10-12"},{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"44e2d0ca7ba60fe4"}},{"id":"qx-c2-016","clusterId":"C","werkstueckRef":"C.4.6","stufe":4,"question":"Welche Prüffrage fehlt, bevor man den Blitzer als Ursache der Besserung ansieht?","scenario":"Eine Gemeinde baut nach dem schlimmsten Unfalljahr ihrer Geschichte an einer Kreuzung einen Blitzer ein; im Jahr darauf passieren dort weniger Unfälle. Der Bürgermeister sieht darin den Beweis, dass der Blitzer wirkt.","options":["Ob die Kosten des Blitzers im Verhältnis zum Nutzen vertretbar sind, denn nur dann lässt sich die Maßnahme als sinnvoll bewerten.","Wie sich vergleichbare Kreuzungen ohne Blitzer entwickelt haben, denn so lässt sich eine Wirkung von der Rückkehr zum Durchschnitt trennen.","Ob die Anwohner den Blitzer befürworten, denn die Akzeptanz entscheidet darüber, ob die Maßnahme politisch durchsetzbar bleibt.","Ob die Unfallzahlen aus einer repräsentativen Stichprobe stammen, denn nur dann lassen sich die Ergebnisse auf andere Orte übertragen."],"correctIndex":1,"explanation":"Ein außergewöhnlich schlechtes Jahr, eine Maßnahme genau danach, anschließend Besserung: Das ist das typische Muster der Regression zur Mitte. Nach einem extremen Ausreißer liegt der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt, auch ohne jede Maßnahme. Erst der Vergleich mit ähnlichen Kreuzungen, die keinen Blitzer bekommen haben, trennt diesen natürlichen Verlauf von einer echten Wirkung. Der Blitzer kann trotzdem wirken; es fehlt nur der Beleg. Die anderen Fragen sind in anderer Lage durchaus sinnvoll, klären hier aber nicht, ob der Rückgang vom Blitzer kommt: Kosten und Nutzen betreffen die Frage, ob sich die Maßnahme lohnt, nicht, ob sie die Ursache war. Die Zustimmung der Anwohner sagt etwas über Durchsetzbarkeit, nicht über Unfälle. Und gezählt wurden alle Unfälle an der Kreuzung, es geht also nicht um eine Stichprobe, von der man auf andere schließen müsste.","coreRule":"⚡ Ohne Vergleichsgruppe bleibt offen, ob die Maßnahme wirkte oder der Zufall zur Normalität zurückkehrte.","beleg":"Werkstück C.4.6 (Kontext & Tiefe: Regression zur Mitte; Red Flags: fehlende Kontrollgruppe; Verbindungen: Kontrollgruppen); Übertragung auf ein Alltagsbeispiel","status":"entwurf","quote":"","quoteLabel":"","kurz":"Nach einem Ausreißerjahr liegt der nächste Wert meist ohnehin näher am Durchschnitt, auch ohne Maßnahme. Erst der Vergleich mit ähnlichen Kreuzungen ohne Blitzer zeigt, ob mehr dahintersteckt. Der Blitzer kann wirken, belegt ist es noch nicht.","prueffrage":"War das schlimmste Unfalljahr an dieser Kreuzung ein Ausreißer, und hätte es danach auch ohne Blitzer besser werden können?","rueckmeldung":[{"option":0,"text":"Kosten und Nutzen sind eine gute Frage, wenn es darum geht, ob sich die Maßnahme lohnt. Sie setzt aber schon voraus, dass der Blitzer den Rückgang bewirkt hat, und genau das ist hier offen."},{"option":2,"text":"Die Haltung der Anwohner sagt etwas darüber, ob die Maßnahme politisch tragfähig ist. Über die Unfälle sagt sie nichts, also auch nicht, ob der Rückgang auf den Blitzer zurückgeht."},{"option":3,"text":"Repräsentativität zählt, wenn man von wenigen Fällen auf andere Orte schließen will. Hier wurden aber alle Unfälle an dieser einen Kreuzung gezählt, und strittig ist die Ursache vor Ort, nicht die Übertragbarkeit."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Allsop 2010, The Effectiveness of Speed Cameras. A review of evidence. Executive Summary, RAC Foundation","oeffentlich":true,"url":"https://www.racfoundation.org/wp-content/uploads/speed-camera-effectiveness-allsop-exec-summary.pdf","seite":"PDF-S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0e5c17bf82515da9"}},{"id":"qx-c2-017","clusterId":"C","werkstueckRef":"C.4.7","stufe":1,"question":"Du liest die Meldung und willst sie prüfen, bevor du sie weiterleitest: Was ist der entscheidende Denkfehler dieser Schlagzeile?","scenario":"Eine Schlagzeile warnt vor „Dihydrogenmonoxid im Leitungswasser“: Es sei Bestandteil des sauren Regens, könne in gasförmigem Zustand schwere Verbrennungen verursachen, und sein Einatmen sei tödlich. Ein Chemiker erklärt, „Dihydrogenmonoxid“ sei nur ein ungewöhnlicher chemischer Name für H₂O, also für Wasser.","options":["Die Meldung nennt Eigenschaften eines Stoffes, aber weder Dosis noch Kontext; ohne sie sagt „kann tödlich sein“ nichts über die tatsächliche Gefahr.","Die Meldung beschreibt Eigenschaften, die der Stoff gar nicht hat; schon die genannten Tatsachenbehauptungen sind sachlich falsch.","Die Meldung verwendet einen Fachnamen; wer Fachnamen benutzt, will damit immer Angst erzeugen und das Publikum bewusst täuschen.","Die Meldung nennt Gefahren, die in großen Mengen wirklich bestehen; weil die Eigenschaften stimmen, ist die Warnung im Kern berechtigt."],"correctIndex":0,"explanation":"Wasser steckt im sauren Regen, heißer Wasserdampf kann schwere Verbrühungen verursachen, und Wasser in der Lunge führt zum Ertrinken. Die Aussagen sind einzeln richtig, aber ohne Menge und Kontext sagen sie nichts über das Risiko: Bei den allermeisten Stoffen ist eine kleine Dosis harmlos und eine sehr hohe schädlich (Ausnahmen wie erbgutschädigende Stoffe nimmt man ohne sichere Schwelle an), auch bei Wasser. Die Meldung nutzt einen unvertrauten Fachnamen und verschweigt genau die Information, die über Gefahr oder Sicherheit entscheidet. Zu prüfen wäre also: Welche Menge liegt vor, wo liegt die schädliche Schwelle, und wie verhält sich beides zur alltäglichen Belastung?","coreRule":"⚡ Nicht die Substanz allein, sondern die Menge im Kontext entscheidet über die Gefahr.","beleg":"Werkstück C.4.7 (Das tödliche Wasser)","status":"entwurf","kurz":"Die genannten Eigenschaften von Wasser stimmen einzeln, sagen aber ohne Menge und Kontext nichts über das Risiko: Meist ist eine kleine Menge harmlos und eine sehr große schädlich. Der unvertraute Fachname lässt das vergessen.","prueffrage":"Treffen die drei Warnungen auf Wasser zu, und was folgt daraus für das Glas Leitungswasser auf deinem Tisch?","rueckmeldung":[{"option":1,"text":"Bei so ungewöhnlichen Warnungen vermutet man leicht, sie seien erfunden. Doch die Tatsachen stimmen: Wasser steckt im sauren Regen, Dampf kann verbrühen, und eingeatmetes Wasser kann zum Ertrinken führen; es fehlt die Menge, nicht die Wahrheit."},{"option":2,"text":"Der unvertraute Name wirkt hier tatsächlich bedrohlich und verdeckt, worum es geht. Dass Fachnamen immer täuschen sollen, trägt aber nicht: Sie sind üblich und verraten keine Absicht; entscheidend ist, was die Meldung verschweigt."},{"option":3,"text":"Einzeln stimmen die Eigenschaften, und manche werden erst bei großen Mengen gefährlich. Gerade deshalb ist die Warnung ohne Menge und Kontext irreführend: Leitungswasser in alltäglicher Menge ist harmlos."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Grandjean, P. (2016): Paracelsus Revisited: The Dose Concept in a Complex World. Basic & Clinical Pharmacology & Toxicology 119(2), 126–132","oeffentlich":true,"doi":"10.1111/bcpt.12622","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4942381/","abruf":"2026-10-12"},{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f72d7f4b5212d19"}},{"id":"qx-c2-018","clusterId":"C","werkstueckRef":"C.4.7","stufe":2,"question":"Welche Frage und welche Vergleichsgrößen entkräften diese Schlagzeile am besten?","scenario":"In einer Chatgruppe kursiert die Meldung „Spuren von Formaldehyd in Impfstoffen gefunden!“ und löst Entsetzen aus. Eine Teilnehmerin schreibt: „Formaldehyd ist ein Gift. Wo Gift drin ist, darf nichts in meinen Körper!“ Du willst sachlich antworten.","options":["Wie viel ist es, und wie verhält sich die Menge zu dem, was Obst enthält und der Körper selbst ständig bildet?","Wer hat die Meldung ursprünglich verbreitet, und lässt sich dazu eine geprüfte Originalquelle finden?","Wurde der Stoff mit einer verlässlichen Methode nachgewiesen, und bestätigt ein unabhängiges Labor das Ergebnis?","Welchen Nutzen hat die Impfung, und wie verhält sich ihr Risiko zu dem der Krankheit, gegen die sie schützt?"],"correctIndex":0,"explanation":"Nicht die bloße Anwesenheit eines Stoffs entscheidet über seine Gefährlichkeit, sondern seine Menge im Verhältnis zu Grenzwert und natürlichen Quellen. Hier ist die Menge klein: Eine Impfdosis enthält höchstens 0,1 Milligramm Formaldehyd. Ein Apfel oder eine Birne enthält insgesamt mehr, und der Körper bildet selbst ständig weitaus höhere, aber völlig harmlose Mengen. Die Frage „Wie viel, verglichen womit?“ macht aus einem Schreckenswort eine prüfbare Größenordnung. Die anderen Fragen sind für sich vernünftig: Quelle, Nachweis und Nutzen-Risiko-Abwägung gehören zur sorgfältigen Prüfung. Sie klären aber nicht, ob die gefundene Menge überhaupt etwas bedeutet, und genau darauf beruht die Schlagzeile.","coreRule":"⚡ Frag bei jedem „Gift gefunden“ nach der Menge und dem Vergleichswert.","beleg":"Werkstück C.4.7 (Anwendung & Relevanz, Chemophobie); Fn. gl-c-formaldehyd (Kuhrt u. a. 2021; Packungsbeilage INFANRIX; Centre for Food Safety Hongkong)","status":"entwurf","kurz":"Entscheidend ist nicht, dass ein Stoff vorkommt, sondern wie viel davon und im Vergleich zu was. Der Denkfehler: „Gift“ als Eigenschaft eines Stoffs zu behandeln, statt die Menge zu prüfen, die hier kleiner ist als in einem Apfel.","prueffrage":"Was genau steht in der Meldung, und was müsstest du zusätzlich wissen, um ihre Bedeutung einschätzen zu können?","rueckmeldung":[{"option":1,"text":"Eine Quellenprüfung gehört dazu und ist an sich vernünftig. Sie klärt aber nur, woher die Meldung stammt. Selbst eine saubere Originalquelle würde nicht zeigen, ob die genannte Spur überhaupt etwas bedeutet."},{"option":2,"text":"Ein verlässlicher Nachweis ist sinnvoll, hilft hier aber wenig: Spuren sind tatsächlich enthalten, ein bestätigter Befund stützt die Schlagzeile also eher. Offen bleibt, ob die Menge etwas bedeutet, und darauf kommt es an."},{"option":3,"text":"Nutzen und Risiko gegeneinander abzuwägen gehört zur sorgfältigen Prüfung, ist aber eine größere Frage. Ob die gefundene Spur Formaldehyd etwas bedeutet, klärt sich dadurch nicht; die Schlagzeile bleibt unbeantwortet."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. FDA: Common Ingredients in FDA-Approved Vaccines","oeffentlich":true,"url":"https://www.fda.gov/vaccines-blood-biologics/safety-availability-biologics/common-ingredients-fda-approved-vaccines","abruf":"2026-10-12"},{"typ":"url","kurz":"Centre for Food Safety Hongkong: Foods Known to Contain Naturally Occurring Formaldehyde","oeffentlich":true,"url":"https://www.cfs.gov.hk/english/whatsnew/whatsnew_fa/files/formaldehyde.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"GlaxoSmithKline: Packungsbeilage INFANRIX („≤100 mcg of residual formaldehyde“ je 0,5-ml-Dosis), nach Landkarte Fn. gl-c-formaldehyd","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fb0a99c6be899fa0"}},{"id":"qx-c2-019","clusterId":"C","werkstueckRef":"C.4.7","stufe":3,"question":"Welche Einschätzung der beiden Aussagen trifft zu, und was folgt daraus für den Umgang mit dem Stoff?","options":["Die Leserin liegt richtig: Wo keine sichere Schwelle angenommen wird, ist jede Menge gleich riskant, deshalb gilt Nulltoleranz und der Abstand zur schädlichen Dosis wird nicht bewertet.","Beide liegen falsch: Auch ohne angenommene sichere Schwelle sinkt das Risiko mit der Dosis, ohne ganz zu verschwinden, deshalb senkt man solche Stoffe so weit wie vernünftig möglich und bewertet den Abstand zur schädlichen Dosis.","Der Kollege liegt richtig: Stoffe ohne angenommene Schwelle unterliegen keiner Dosis-Wirkungs-Beziehung, deshalb ist jede nachgewiesene Spur gleich harmlos und der Abstand zur schädlichen Dosis spielt keine Rolle.","Die Leserin liegt im Ergebnis richtig: Zwar steigt das Risiko mit der Dosis, doch weil es nie ganz verschwindet, muss jeder Nachweis zu einem Verbot führen, ohne dass der Abstand zur schädlichen Dosis bewertet wird."],"correctIndex":1,"explanation":"Beide Aussagen machen aus einem Kontinuum eine Ja-Nein-Frage. Für erbgutschädigende Stoffe und ionisierende Strahlung nimmt man vorsorglich keine sichere Schwelle an: Das Risiko sinkt nach dieser Annahme mit der Dosis, verschwindet aber nicht ganz. „Keine Schwelle“ heißt also nicht „jede Menge gleich gefährlich“ und auch nicht „Dosis egal“. Behörden bewerten deshalb den Abstand zwischen der tatsächlichen Belastung und der Dosis, die im Tierversuch Tumoren auslöst, und senken solche Stoffe so weit, wie es vernünftigerweise möglich ist (ALARA-Prinzip). Auch hier hängt das Risiko von der Dosis ab.","coreRule":"⚡ Auch ohne sichere Schwelle gilt: Das Risiko wächst mit der Dosis – Null gibt es nicht, aber auch nicht „alles gleich schlimm“.","beleg":"Werkstück C.4.7 (Kontext & Tiefe, „Die Kurve ist entscheidend“); Fn. gl-c-schwelle (Mußhoff u. a. 2015, S. 602–603; Schrenk 2011, S. 317)","status":"entwurf","scenario":"Eine Redaktion berichtet: In einem Brot wurden Spuren eines Stoffes gefunden, der das Erbgut schädigen kann. Eine Leserin schreibt: „Bei erbgutschädigenden Stoffen gibt es keine sichere Menge – also ist schon jede Spur gleich gefährlich wie eine große Dosis, und man muss das Brot komplett meiden.“ Ein Kollege widerspricht: „Unsinn – so winzige Spuren sind einfach harmlos, auf die genaue Menge kommt es da gar nicht an.“","kurz":"Ohne angenommene Schwelle sinkt das Risiko mit der Dosis, ohne ganz zu verschwinden. „Jede Spur gleich gefährlich“ und „Spuren sind harmlos“ übersehen das beide. Richtig ist, so weit wie vernünftig möglich zu senken und den Abstand zur schädlichen Dosis zu bewerten.","prueffrage":"Was würden Leserin und Kollege jeweils über eine Spur sagen, die zehnmal größer wäre als die im Brot gefundene?","rueckmeldung":[{"option":0,"text":"Dass bei solchen Stoffen vorsorglich keine sichere Schwelle angenommen wird, stimmt. Daraus folgt aber nicht, dass jede Menge gleich riskant ist: Das Risiko sinkt mit der Dosis, deshalb wird der Abstand zur schädlichen Dosis sehr wohl bewertet."},{"option":2,"text":"Dass eine winzige Spur nur ein kleines Risiko bedeutet, stimmt. „Keine Schwelle“ heißt aber nicht „Menge egal“: Das Risiko hängt weiter von der Dosis ab und verschwindet nicht ganz, deshalb bleibt der Abstand zur schädlichen Dosis entscheidend."},{"option":3,"text":"Dass das Risiko mit der Dosis steigt und nie ganz verschwindet, stimmt. Daraus folgt aber kein Verbot bei jedem Nachweis: Weil die Dosis zählt, bewertet man den Abstand zur schädlichen Dosis und senkt die Belastung so weit wie vernünftig möglich."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schrenk, D. (2011): Lebensmittel – Nahrungsergänzungsmittel – Arzneimittel. Toxikologische Bewertung und Abgrenzung. Pharmazie in unserer Zeit 40(4), 316–324 (doi 10.1002/pauz.201100426)","oeffentlich":false},{"typ":"literatur","kurz":"Mäntele, W. (2021): Elektrosmog und Ökoboom. Springer, Kap. „Gibt es einen Schwellwert für die Dosis?“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"13f340ab8984a986"}},{"id":"qx-c2-020","clusterId":"C","werkstueckRef":"C.4.8","stufe":1,"question":"Ein Gesprächspartner sagt: „Der Zweite Hauptsatz der Thermodynamik verbietet es grundsätzlich, dass ein Lebewesen unbegrenzt lange lebt. Entropie nimmt immer zu, also muss jeder Organismus irgendwann zerfallen.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er übersieht, dass ein Organismus ein offenes System ist: Energie fließt zu, Entropie wird abgegeben, und so kann seine Ordnung lokal bestehen bleiben.","Er verallgemeinert voreilig: Aus wenigen beobachteten Lebewesen schließt er auf alle Organismen, obwohl die Stichprobe viel zu klein ist.","Er argumentiert im Kreis: Er setzt den Zerfall jedes Organismus schon voraus und folgert ihn dann scheinbar aus dem Hauptsatz.","Er stellt die Gegenposition verzerrt dar und widerlegt nur eine Karikatur (Strohmann), statt auf die stärkste Fassung einzugehen."],"correctIndex":0,"explanation":"Kein System setzt den Zweiten Hauptsatz außer Kraft. Er verbietet einem offenen System aber nicht, seine Ordnung beliebig lange zu halten, solange Energie nachfließt und Entropie nach außen abgegeben wird. Ein Lebewesen ist ein solches offenes System im Stoff- und Energiefluss: Es ist eine lokale Senke niedriger Entropie und hält diese Ordnung nur durch fortwährende Energiezufuhr und die Abgabe von Entropie nach außen aufrecht. Jede Reparatur kostet Energie, aber ein Verbot unbegrenzter Lebensdauer folgt daraus nicht. Dass Körper nicht unbegrenzt in Wartung investieren, ist eine Frage der evolutionär eingestellten Energieverteilung (Fortpflanzung statt Instandhaltung), keine physikalische Notwendigkeit. Schon der Evolutionsbiologe George C. Williams wies 1957 den Vergleich des Organismus mit einer verschleißenden Maschine zurück. Die Gegenthese, der Tod sei physikalisch unvermeidlich, wird vertreten, bleibt aber umstritten, denn bei manchen Arten steigt das Sterberisiko mit dem Alter kaum oder gar nicht. Der Fehlschluss besteht darin, aus dem Hauptsatz ein Verbot abzuleiten, das er für ein offenes System gar nicht ausspricht. Die anderen Denkfehler gibt es durchaus, der Gesprächspartner begeht sie hier aber nicht: Er verallgemeinert nicht aus wenigen Beobachtungen, sondern beruft sich auf ein allgemeines Gesetz. Sein Schluss ist auch kein Kreis, denn Entropiezunahme und Zerfall des Organismus sind verschiedene Aussagen. Und es gibt keine Gegenposition, die er verzerrt wiedergäbe.","coreRule":"⚡ Ein Gesetz über abgeschlossene Systeme beweist nichts über offene. Reparatur kostet Energie, verboten ist sie nicht.","beleg":"Werkstück C.4.8 (Kontext & Tiefe, Hierarchie der Grenzen); Fn. gl-c-williams (Williams 1957, S. 398 und 401–402)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Zweite Hauptsatz verbietet einem offenen System nicht, seine Ordnung zu halten, solange Energie zufließt und Entropie nach außen geht. Der Fehler ist, aus einem Gesetz ein Verbot abzuleiten, das es gar nicht ausspricht.","prueffrage":"Bleibt ein Kühlschrank innen dauerhaft kalt, obwohl Wärme von selbst immer vom Warmen zum Kalten fließt, und was braucht er dafür?","rueckmeldung":[{"option":1,"text":"Voreilige Verallgemeinerung ist ein häufiger Fehler, und „immer“ legt ihn nahe. Hier stützt sich die Aussage aber nicht auf wenige beobachtete Fälle, sondern auf ein allgemeines Gesetz. Die Schwäche liegt darin, was daraus gefolgert wird."},{"option":2,"text":"Die Schlussfolgerung klingt wie die Prämisse in anderen Worten, daher wirkt es zirkulär. Entropiezunahme und Zerfall jedes Organismus sind aber verschiedene Aussagen. Der Schluss von der einen auf die andere trägt nicht, ist aber kein Kreis."},{"option":3,"text":"Ein Strohmann setzt eine Gegenposition voraus, die verzerrt wiedergegeben wird. Der Gesprächspartner vertritt hier eine eigene These und widerlegt niemanden. Der Fehler steckt im Schluss selbst, nicht in der Darstellung einer anderen Meinung."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Schaible, R. u. a. (2015): Constant mortality and fertility over age in Hydra. PNAS 112(51), 15701–15706","oeffentlich":true,"doi":"10.1073/pnas.1521002112","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4697432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jones, O. R. u. a. (2014): Diversity of ageing across the tree of life. Nature 505(7482), 169–173","oeffentlich":true,"doi":"10.1038/nature12789","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4157354/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3e4624fbf4862cca"}},{"id":"qx-c2-021","clusterId":"C","werkstueckRef":"C.4.8","stufe":2,"question":"Wie sollte die Werbung vor dem Hintergrund der Studienlage beurteilt werden?","scenario":"Ein Online-Shop verspricht: „Antioxidantien-Kapseln stoppen den Rost des Alterns und verlängern dein Leben.“ Zur Prüfung liegt dir eine Übersichtsarbeit vor, die 78 Studien mit insgesamt 296.707 Teilnehmenden ausgewertet hat, Gesunde ebenso wie Kranke.","options":["Die Behauptung ist nicht prüfbar: „Rost des Alterns“ ist nur ein Bild, und solange der Begriff unscharf bleibt, kann keine Studie etwas darüber sagen.","Die Behauptung ist gut begründet, denn freie Radikale schädigen Zellen nachweislich, und Antioxidantien fangen sie ab, sodass der Mechanismus die Aussage trägt.","Die Behauptung ist nicht belegt: Große Studien fanden keine geringere Sterblichkeit, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine höhere.","Die Behauptung ist schon deshalb zu verwerfen, weil der Shop am Verkauf verdient; wer ein Interesse hat, dessen Aussage kann nicht stimmen."],"correctIndex":2,"explanation":"Die plausible Idee „Altern ist molekularer Rost, also hilft ein Rostschutz“ ist kein Beleg. Ob Kapseln die Sterblichkeit tatsächlich senken, entscheidet sich an Studien mit vielen Teilnehmenden, und die liegen vor: Die Cochrane-Übersicht von Bjelakovic u. a. (2012) wertete 78 Studien mit 296.707 Teilnehmenden aus. Antioxidantien als Nahrungsergänzung senkten die Sterblichkeit nicht, Beta-Carotin und Vitamin E scheinen sie sogar zu erhöhen. Dass freie Radikale Schäden verursachen, ist zudem nur ein Teil des Bildes: Es gibt viele weitere Schadensquellen, und ein einzelner Wirkstoff kann nicht alle abdecken. Wer ein Ein-Wirkstoff-Versprechen prüft, fragt deshalb nicht, ob der Mechanismus einleuchtet, sondern ob die Wirkung am Menschen belegt ist. Die anderen Gedanken klingen vernünftig, passen aber nicht: Die Behauptung ist durchaus prüfbar, denn die Studien haben die Sterblichkeit gemessen. Ein einleuchtender Mechanismus ersetzt diese Messung nicht. Und ein Verkaufsinteresse des Shops ist ein Grund zur Vorsicht, widerlegt die Aussage aber nicht.","coreRule":"⚡ Ein einleuchtender Mechanismus ersetzt keinen Beleg: Wer „Rostschutz“ verspricht, muss zeigen, dass Kapseln die Sterblichkeit senken – große Studien zeigen das bisher nicht.","beleg":"Werkstück C.4.8 (Ebene 2: Die Chemie; Red Flags); Fn. gl-c-antioxidantien (Bjelakovic u. a. 2012, Cochrane CD007176)","status":"entwurf","kurz":"Ob Kapseln das Leben verlängern, zeigt sich an der Sterblichkeit in Studien, nicht am Bild vom „Rost“. Solche Studien mit fast 300.000 Teilnehmenden fanden keine Senkung, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine Erhöhung.","prueffrage":"Woran könntest du erkennen, ob die Kapseln bei Menschen tatsächlich etwas bewirken, und nicht nur im Reagenzglas oder in der Theorie?","rueckmeldung":[{"option":0,"text":"Dass „Rost des Alterns“ nur ein Bild ist, stimmt. Geprüft werden kann aber der Kern des Versprechens, ein längeres Leben, und die Studien haben genau das gemessen. Die Behauptung ist also durchaus prüfbar."},{"option":1,"text":"Dass freie Radikale Zellen schädigen können, leuchtet ein, doch ein einleuchtender Mechanismus ersetzt keine Messung am Menschen. Außerdem ist das nur eine von vielen Schadensquellen, und ein einzelner Wirkstoff deckt nicht alle ab."},{"option":3,"text":"Ein Verkaufsinteresse ist ein guter Anlass für genaueres Hinsehen. Es sagt aber nichts darüber, ob die Aussage stimmt: Auch Interessierte können recht haben, geklärt wird das an den Studien, nicht an den Motiven des Shops."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Bjelakovic, G. u. a. (2012): Antioxidant supplements for prevention of mortality in healthy participants and patients with various diseases. Cochrane Database of Systematic Reviews (3), CD007176","oeffentlich":true,"doi":"10.1002/14651858.CD007176.pub2","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8407395/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d05352648bad1aaa"}},{"id":"qx-c2-022","clusterId":"C","werkstueckRef":"C.4.8","stufe":3,"question":"Welche Einschätzung der Aussage ist am besten begründet?","options":["Die Aussage ist plausibel, aber nicht belegt: Der Mausbefund stützt den Zielkonflikt nicht, und beim Menschen fehlt bisher ein gesichertes Beispiel für ein solches Gen.","Die Aussage ist belegt: Bei Fadenwürmern, Fliegen und Mäusen sind mehrere Gene mit solchen Zielkonflikten beschrieben, also gilt das ebenso für p53 beim Menschen.","Die Aussage ist widerlegt: Wenn zusätzliche p53-Kopien das Altern nicht beschleunigen, kann p53 im Alter keinen Schaden anrichten, und die Hypothese entfällt.","Die Aussage ist verlässlich, denn sie stammt von einer Biologin, und bei Fachleuten darf man davon ausgehen, dass die Behauptung im Fach gut abgesichert ist."],"correctIndex":0,"explanation":"Die Hypothese ist plausibel: Ein Gen, das in der Jugend krebsverdächtige Zellen rigoros entfernt, könnte im Alter auch nützliche Stammzellen opfern. Plausibel ist aber nicht bewiesen. Bei „Super-p53“-Mäusen mit zusätzlichen, normal gesteuerten p53-Kopien trat der Krebsschutz ohne beschleunigtes Altern auf; mehr Schutz durch p53 kostet also nicht zwangsläufig schnelleres Altern, und der behauptete Zielkonflikt wird dadurch nicht gestützt. Für den Menschen gibt es bislang keinen überzeugenden Fall, in dem das verantwortliche Gen identifiziert wäre. Ein stimmiges Erklärungsbild ersetzt keine Evidenz, und Befunde aus einer Art lassen sich nicht ungeprüft auf eine andere übertragen. Die anderen Gedanken klingen für sich vernünftig, passen aber nicht: Dass bei anderen Genen und Arten solche Zielkonflikte beschrieben sind, belegt sie für p53 und den Menschen nicht. Der Mausbefund widerlegt die Hypothese ebenfalls nicht, denn dort war p53 nur normal gesteuert vermehrt, nicht verändert. Und die Fachkenntnis der Biologin ersetzt keine Belege.","coreRule":"⚡ Ein schönes Erklärungsbild ist noch kein Befund: Prüfe, ob Experimente es tatsächlich stützen und ob sie für die Art gelten, über die du sprichst.","beleg":"Werkstück C.4.8 (Das Adaptive Talent; Anwendung & Relevanz); Fn. gl-c-p53 (García-Cao u. a. 2002, EMBO J 21 (22), S. 6225–6235); Fn. gl-c-austad (Austad/Hoffman 2018, S. 289)","status":"entwurf","scenario":"Eine Biologin sagt: „p53 ist das klassische Beispiel für antagonistische Pleiotropie: In der Jugend schützt das Gen vor Krebs, im Alter treibt es den Zerfall voran.“ Du kennst zwei Befunde: Mäuse mit zusätzlichen, normal gesteuerten p53-Kopien waren besser vor Krebs geschützt und alterten trotzdem normal. Bei Fadenwürmern, Fliegen und Mäusen sind mehrere Gene mit solchen Zielkonflikten beschrieben, beim Menschen ist bislang kein Gen dieser Art zweifelsfrei identifiziert.","kurz":"Die Aussage ist plausibel, aber nicht belegt: Im Mausversuch ging mehr p53-Krebsschutz nicht mit schnellerem Altern einher, und beim Menschen ist kein Gen mit solchem Zielkonflikt gesichert. Ein stimmiges Bild ist noch keine Evidenz.","prueffrage":"Was geschah bei den Mäusen mit zusätzlichen p53-Kopien mit der Krebsrate und mit der Alterung?","rueckmeldung":[{"option":1,"text":"Bei anderen Genen und Arten sind solche Zielkonflikte tatsächlich beschrieben. Das sagt aber nichts über p53 und nichts über den Menschen, und dort ist bislang kein Gen dieser Art zweifelsfrei identifiziert."},{"option":2,"text":"Der Mausbefund stützt den Zielkonflikt tatsächlich nicht. Widerlegt ist die Hypothese damit aber nicht: Dort war p53 nur normal gesteuert vermehrt, ein Schaden im Alter durch anders wirkendes p53 bleibt offen."},{"option":3,"text":"Fachleute kennen ihr Gebiet meist gut, und das ist ein Grund, die Aussage ernst zu nehmen. Ob sie gesichert ist, zeigt aber nur die Evidenz, und die ist hier lückenhaft: Der Mausbefund stützt sie nicht, beim Menschen fehlt ein gesichertes Gen."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"García-Cao, I. u. a. (2002): „Super p53“ mice exhibit enhanced DNA damage response, are tumor resistant and age normally. EMBO Journal 21(22), 6225–6235","oeffentlich":true,"doi":"10.1093/emboj/cdf595","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC137187/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"58e56e54536a020b"}},{"id":"qx-c2-023","clusterId":"C","werkstueckRef":"C.4.9","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Muster?","options":["Wo Tiere ohnehin früh sterben, lohnt sich Körperwartung kaum; Art A investiert eher in Fortpflanzung und altert deshalb früher.","Kleinere Tiere altern schneller, weil die Lebensdauer mit der Körpergröße zunimmt; deshalb altert Art A im Labor früher als Art B.","Wo der Stoffwechsel schneller läuft, wird die begrenzte Lebensenergie früher verbraucht; Art A altert deshalb im Labor schneller.","Wo Fressfeinde drohen, belastet Dauerstress den Körper; Art A altert deshalb schneller, weil dieser Stress ihre Zellen vorzeitig verschleißt."],"correctIndex":0,"explanation":"Die Evolution investiert nur so viel in Reparatur und Wartung des Körpers („Soma“), wie nötig ist, um ihn bis zur erfolgreichen Fortpflanzung am Leben zu erhalten (Disposable-Soma-Theorie). Stirbt eine Art in der Natur meist früh, bringt aufwendige Wartung für spätere Jahre kaum zusätzlichen Nachwuchs; die Ressourcen gehen besser in Fortpflanzung. Übertragen auf die Beobachtung heißt das: Art A altert auch im geschützten Labor früher, weil Selektion ihre Ausstattung auf die kurze Lebenserwartung in der Natur eingestellt hat (eine Übertragung der Theorie, kein direkter Befund). Bei nur zwei Arten bleibt Zufall allerdings nicht ausgeschlossen. Die anderen Gedanken sind bekannte Erklärungsmuster, passen aber nicht: Beide Arten sind ähnlich groß, die Körpergröße erklärt den Unterschied also nicht. Von einem unterschiedlichen Stoffwechsel ist keine Rede. Und im Labor drohen keine Fressfeinde, sodass Dauerstress durch sie das frühe Altern dort nicht erklärt.","coreRule":"⚡ Wartung lohnt sich nur so weit, wie ein Körper realistisch lebt, um seine Gene weiterzugeben.","beleg":"Werkstück C.4.9 (Ebene 1: Die Biologie, Disposable Soma Theory; Anwendung auf Fressfeinde und Laborbedingungen ist Transfer, nicht im Buchtext belegt)","status":"entwurf","scenario":"Eine Forscherin vergleicht zwei ähnlich große Tierarten: Art A hat viele Fressfeinde und stirbt in der Natur meist schon im ersten Lebensjahr, Art B hat kaum Feinde und lebt oft viele Jahre. Im Labor, wo keine Fressfeinde drohen, zeigt Art A nach kurzer Zeit deutliche Alterserscheinungen, Art B erst viel später.","kurz":"Wo Tiere in der Natur meist früh sterben, zahlt sich aufwendige Körperwartung kaum aus; die Selektion lenkt Ressourcen eher in Fortpflanzung. Art A altert darum auch im sicheren Labor früher. Größe, Stoffwechsel oder Stress erklären das nicht.","prueffrage":"Worin unterscheiden sich die beiden Arten in der Natur, und bleibt dieser Unterschied im Labor sichtbar, obwohl dort keine Fressfeinde drohen?","rueckmeldung":[{"option":1,"text":"Größere Tiere leben tatsächlich oft länger, als Trend über viele Arten hinweg. Hier sind beide Arten aber ähnlich groß, also kann die Größe diesen Unterschied nicht erklären."},{"option":2,"text":"Ein schnellerer Stoffwechsel gilt als mögliche Ursache für kürzere Lebensdauer, das ist ein bekanntes Muster. Im Szenario steht aber nichts über unterschiedliche Stoffwechselraten, die Erklärung setzt also etwas voraus, das nicht gegeben ist."},{"option":3,"text":"Dauerstress durch Fressfeinde kann den Körper belasten, das ist plausibel. Das frühe Altern zeigt sich aber gerade im Labor, wo keine Fressfeinde drohen, und kann deshalb nicht von diesem Stress herrühren."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b8a68728b489501"}},{"id":"qx-c2-024","clusterId":"C","werkstueckRef":"C.4.9","stufe":2,"question":"Welche Erklärung für die niedrige Krebsrate bei Kindern ist am besten begründet?","options":["Krebs ist eine Alterskrankheit, und das genügt als Erklärung: Kinder erkranken selten, weil sie jung sind, mehr gibt es da nicht zu klären.","Ein Schutzmechanismus erkennt und beseitigt beschädigte Zellen früh, und in jungen Zellen haben sich erst wenige Mutationen angesammelt.","Die Rate ist gar nicht niedriger, sondern es gibt in der Bevölkerung nur wenige Kinder und deshalb auch nur wenige Krebsfälle (Basisrate).","Bei Kindern wird Krebs seltener erkannt, weil sie seltener zur Vorsorge gehen, sodass die niedrige Rate vor allem ein Messartefakt ist."],"correctIndex":1,"explanation":"„Jung“ ist hier keine Erklärung, sondern ein Sammelbegriff für zwei Mechanismen. Ein Wächtergen wie p53 erkennt Zellen mit beschädigter DNA und kann ihren programmierten Zelltod (Apoptose) auslösen, bevor sie zu Krebszellen werden; dieser Schutz wirkt von Anfang an. Den Unterschied zwischen Kindern und Älteren macht vor allem die Zahl der Mutationen: Junge Zellen haben erst wenige angesammelt, und mit den Jahren können auch Schutzgene wie p53 selbst getroffen werden. Wer eine Alltagserklärung wie „weil jung“ prüft, fragt also: Welche Mechanismen stecken dahinter, und trägt jeder einzelne? Die anderen Gedanken klingen sinnvoll, passen hier aber nicht: „Alterskrankheit“ benennt die Beobachtung, erklärt sie aber nicht. Gefragt ist die Rate, und die bleibt von der Zahl der Kinder unberührt. Für ein Messartefakt spricht nichts, denn schwere Symptome bei Kindern werden in der Regel ärztlich abgeklärt.","coreRule":"⚡ Prüfe Sammelbegriffe wie „weil jung“: Zerlege sie in die Mechanismen, die tatsächlich wirken. Hier schützt der Wächter p53, und es gibt noch wenig Fehler, die sich angehäuft haben.","beleg":"Werkstück C.4.9 (Der Wächter kehrt zurück, zweiter Absatz); Verweis auf C.4.4","status":"entwurf","scenario":"Eine Kollegin sagt: „Krebs ist eine Alterskrankheit, bei Kindern kommt er kaum vor. Das liegt doch nur daran, dass Kinder jung sind, mehr steckt nicht dahinter.“ Du willst wissen, was dieses „jung“ konkret bedeutet.","kurz":"„Jung“ erklärt nichts, solange man nicht fragt, was dahintersteckt: Schutzmechanismen wie p53 wirken früh, und junge Zellen haben erst wenige Mutationen angesammelt. „Alterskrankheit“ benennt nur die Beobachtung.","prueffrage":"Was genau unterscheidet eine junge Zelle von einer alten, und lässt sich jeder dieser Unterschiede einzeln benennen?","rueckmeldung":[{"option":0,"text":"Dass Krebs im Alter häufiger ist, stimmt. Damit ist aber nur die Beobachtung benannt, nicht erklärt, was „jung“ bedeutet; genau diese Frage bleibt bei „mehr gibt es da nicht zu klären“ offen."},{"option":2,"text":"Wenige Kinder ergeben wenige Fälle, aber keine niedrigere Rate. Die Rate ist ein Anteil und bleibt von der Zahl der Kinder unberührt, daher erklärt dieser Gedanke nicht, warum der Anteil klein ist."},{"option":3,"text":"Verzerrte Erfassung kann Raten tatsächlich beeinflussen. Hier gibt es dafür aber keinen Anhaltspunkt: Schwere Symptome bei Kindern werden in der Regel ärztlich abgeklärt, sodass nicht viel unentdeckt bleiben dürfte."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Zhang, H. u. a. (2024): Unraveling the Guardian: p53’s Multifaceted Role in the DNA Damage Response and Tumor Treatment Strategies. International Journal of Molecular Sciences 25(23), 12928","oeffentlich":true,"doi":"10.3390/ijms252312928","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11641486/","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: The Genetics of Cancer","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/genetics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6412f30ad479154a"}},{"id":"qx-c2-025","clusterId":"C","werkstueckRef":"C.4.9","stufe":3,"question":"Eine Forscherin behauptet: „Freie Radikale rosten uns zu Tode – oxidativer Schaden ist die Ursache des Alterns.“ Welche Beobachtung spricht am stärksten gegen diese Behauptung?","options":["Bei Mäusen beschleunigten zusätzliche oxidative Schäden das Altern nicht, und der Nacktmull wird trotz hoher oxidativer Schäden außergewöhnlich alt.","Im Gewebe älterer Tiere findet man deutlich mehr oxidativ geschädigte Eiweiße, Fette und DNA-Abschnitte als im Gewebe junger Tiere.","Freie Radikale entstehen ständig als Nebenprodukt der Zellatmung in den Mitochondrien und lassen sich in jeder atmenden Zelle nachweisen.","Raucher sind einem erhöhten oxidativen Stress ausgesetzt und haben im Durchschnitt eine kürzere Lebenserwartung als Nichtraucher."],"correctIndex":0,"explanation":"Wenn oxidativer Schaden die Ursache des Alterns wäre, müsste jeder Eingriff, der ihn verändert, auch die Lebensdauer verändern. Genau das tritt nicht ein: Mehr oxidativer Schaden beschleunigte das Altern von Mäusen nicht, und eine Art mit hohen oxidativen Schäden wird dennoch außergewöhnlich alt. Auch Veränderungen der Schutzenzyme änderten die Lebensdauer von Mäusen in einer großen Versuchsreihe nur in einem von 18 Fällen. Weil dieselben Moleküle auch als Signalstoffe wirken, gilt oxidativer Schaden heute als ein Baustein des Alterns unter vielen, nicht als seine Ursache. Wer eine Theorie prüft, fragt also: Was müsste gelten, wenn sie stimmt – und tritt es ein? Die anderen Beobachtungen stimmen, sprechen aber nicht gegen die Behauptung: Dass sich im Alter mehr oxidative Schäden finden, zeigt nur, dass sie auftreten, nicht dass sie das Altern verursachen. Dass Radikale im Stoffwechsel entstehen, ist unstrittig und prüft die Ursachenbehauptung nicht. Und dass Raucher früher sterben, passt zur Theorie, lässt sich aber ebenso durch viele andere Schäden des Rauchens erklären.","coreRule":"⚡ Prüfe eine Ursachenbehauptung mit der Gegenprobe: Ändert sich das Ergebnis, wenn du die vermutete Ursache veränderst? Oxidativer Schaden ist ein Baustein des Alterns, nicht seine alleinige Ursache.","beleg":"Werkstück C.4.9 (Ebene 2: Oxidativer Stress); Fn. gl-c-radikale (Pérez u. a. 2009: nur 1 von 18 Veränderungen der Schutzenzyme änderte die Lebensdauer; López-Otín u. a. 2013: mehr oxidative Schäden beschleunigen das Altern nicht; Gladyshev 2014; zum Nacktmull Verweis auf Andziak u. a. 2006, Werkstück C.4.11)","status":"entwurf","scenario":"Die Theorie der freien Radikale galt lange als wichtigste Erklärung des Alterns. Du prüfst, ob sie sich halten lässt.","kurz":"Wäre oxidativer Schaden die Ursache des Alterns, müsste mehr davon das Leben verkürzen. Das trat bei Mäusen nicht ein, und der Nacktmull wird trotz hoher Schäden sehr alt. Dass Schäden im Alter zunehmen, zeigt nur, dass sie auftreten.","prueffrage":"In welchen Versuchen wurde der oxidative Schaden gezielt verändert, und wie alt wurden die Tiere danach?","rueckmeldung":[{"option":1,"text":"Dass im Alter mehr oxidativ geschädigte Moleküle vorliegen, stimmt. Es zeigt aber nur, dass diese Schäden auftreten, nicht dass sie das Altern verursachen. Mit der Behauptung ist das vereinbar und spricht deshalb nicht gegen sie."},{"option":2,"text":"Die Entstehung freier Radikale in den Mitochondrien ist unstrittig. Sie sagt aber nur, woher die Radikale kommen, und prüft nicht, ob ihr Schaden das Altern verursacht. Für oder gegen die Ursachenbehauptung folgt daraus nichts."},{"option":3,"text":"Raucher haben mehr oxidativen Stress und leben im Schnitt kürzer, das stimmt. Das passt eher zur Behauptung als gegen sie. Rauchen schädigt den Körper jedoch auf viele andere Arten, sodass der Befund die Ursache nicht eindeutig trifft."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Pérez, V. I. u. a. (2009): Is the oxidative stress theory of aging dead? Biochimica et Biophysica Acta 1790(10), 1005–1014","oeffentlich":true,"doi":"10.1016/j.bbagen.2009.06.003","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2789432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217, Abschnitt „Mitochondrial Dysfunction“","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Andziak, B. u. a. (2006): High oxidative damage levels in the longest-living rodent, the naked mole-rat. Aging Cell 5(6), 463–471 (doi 10.1111/j.1474-9726.2006.00237.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0d7e66a63d9c42c7"}},{"id":"qx-c2-026","clusterId":"C","werkstueckRef":"C.4.9","stufe":4,"question":"Welche Einschätzung des Ansatzes ist am besten begründet?","scenario":"Ein Start-up wirbt für einen Wirkstoff, der gezielt „Zombie-Zellen“ (seneszente Zellen) aus dem Gewebe entfernen soll, und nennt ihn den „ersten Schritt zur Verjüngung“. Eine Investorin fragt dich, was man davon realistischerweise erwarten darf.","options":["Der Ansatz behandelt nur Folgeerscheinungen des Alterns: Er lindert Beschwerden wie bei einer Krankheitstherapie, ohne den zugrunde liegenden Verschleiß zu berühren.","Der Ansatz greift in die Gene ein: Er verändert Erbanlagen, die früh im Leben nützen und später schaden, und setzt so an der Ursache des Alterns an.","Der Ansatz zielt darauf, den zellulären Verschleiß zu verlangsamen: Er entfernt Zellen, die sich angesammelt haben, und soll das Altern so bremsen, ohne in die Gene einzugreifen.","Der Ansatz ersetzt abgenutzte Gewebe durch neue: Er arbeitet wie eine Stammzell- oder Organersatztherapie und lässt den vorhandenen Verschleiß bestehen."],"correctIndex":2,"explanation":"Entscheidend ist, an welcher Stelle der Ansatz eingreift. Das Entfernen seneszenter „Zombie-Zellen“ setzt am Verschleiß der Zellen an und soll ihn verlangsamen, ähnlich wie das Ankurbeln der zelleigenen Reinigungsprozesse (Autophagie). Ob und wie gut das beim Menschen funktioniert, sagt diese Einordnung nicht, und das Altern selbst abzuschaffen, ist damit ohnehin nicht gemeint. Eine Werbeaussage wie „Verjüngung“ verlangt deshalb Belege aus Studien am Menschen, nicht nur ein plausibles Wirkprinzip. Die anderen Ansätze gibt es durchaus, sie beschreiben diesen Wirkstoff aber nicht: Er lindert nicht bloß Beschwerden, wie es die klassische Medizin bei Herzinfarkt, Krebs oder Alzheimer tut, sondern greift an angesammelten Zellen an. Er verändert keine Gene oder Epigenetik, wie es etwa CRISPR oder die Reprogrammierung von Zellen täten. Und er ersetzt nichts durch Neues, sondern nimmt nur Vorhandenes weg.","coreRule":"⚡ Frag bei Anti-Aging-Versprechen, wo der Ansatz eingreift: bei den Folgen (Krankheiten), beim Verschleiß (Zellen, Chemie) oder bei den Grundlagen (Gene). Daran hängt, was er leisten kann und was nicht.","beleg":"Werkstück C.4.9 (Anwendung & Relevanz, Die drei Stufen des Anti-Aging)","status":"entwurf","kurz":"Der Wirkstoff setzt am zellulären Verschleiß an: Er entfernt angesammelte Zellen und soll so das Altern bremsen. Ein plausibles Wirkprinzip ist aber kein Beleg, „Verjüngung“ bräuchte Studien am Menschen.","prueffrage":"Welche Ergebnisse aus Studien am Menschen nennt das Start-up für seinen Wirkstoff, und was genau wurde dort gemessen?","rueckmeldung":[{"option":0,"text":"Solche Ansätze gibt es, etwa die Behandlung von Herzinfarkt oder Krebs. Dieser Wirkstoff lindert aber nicht nur Beschwerden, er greift bei angesammelten Zellen an, also an einem Teil des Verschleißes selbst."},{"option":1,"text":"Eingriffe in Gene oder Epigenetik gibt es tatsächlich, etwa mit CRISPR. Dieser Wirkstoff verändert aber keine Erbanlagen, er entfernt Zellen aus dem Gewebe, ganz ohne an den Genen anzusetzen."},{"option":3,"text":"Stammzell- und Organersatztherapien sind ein echter Ansatz, aber ein anderer. Hier wird nichts Neues eingesetzt: Der Wirkstoff nimmt nur vorhandene, angesammelte Zellen weg und lässt den Verschleiß damit nicht einfach bestehen."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Chaib, S.; Tchkonia, T.; Kirkland, J. L. (2022): Cellular senescence and senolytics: the path to the clinic. Nature Medicine 28(8), 1556–1568","oeffentlich":true,"doi":"10.1038/s41591-022-01923-y","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9599677/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"47122b9158b4c50e"}},{"id":"qx-c2-027","clusterId":"C","werkstueckRef":"C.4.10","stufe":1,"question":"Ein Labor hält menschliche Bindegewebszellen in einer Petrischale mit bester Nährlösung, wechselt das Medium regelmäßig und hält alle Bedingungen konstant. Nach etwa 50 Teilungen stellen die Zellen die Teilung ein, bleiben aber am Leben. Was erklärt diesen Befund am besten?","options":["Die Zellen haben eine eigene Teilungsgrenze: Bei jeder Teilung verkürzen sich die Schutzkappen an den Chromosomenenden, bis die Zelle den Teilungsstopp auslöst.","Im Medium häufen sich Stoffwechselabfälle der Zellen an, die ab einer bestimmten Menge die Teilung hemmen, bis die Kultur zum Stillstand kommt.","Die Zellen lösen nach etwa 50 Teilungen den programmierten Zelltod aus, mit dem der Körper überzählige oder gealterte Zellen gezielt beseitigt.","Die Zellen teilen sich nur auf äußere Wachstumssignale hin; nach etwa 50 Teilungen bleibt dieses Signal dauerhaft aus und die Zellen reagieren nicht mehr."],"correctIndex":0,"explanation":"Der Befund spricht gegen die Annahme, die Umgebung sei schuld: Die Bedingungen waren konstant und ideal, und der Teilungsstopp trat trotzdem nach etwa 50 Teilungen ein. Das deutet auf eine Grenze, die in der Zelle selbst liegt. Tatsächlich geht beim Kopieren der DNA bei jeder Teilung ein winziges Stück der Telomere verloren, der Schutzkappen an den Chromosomenenden (vergleichbar mit den Plastikkappen an Schnürsenkeln). Werden sie zu kurz, deutet die Zelle das als mögliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und hört auf, sich zu teilen, ein Schutz vor Krebs. Die Zellen leben weiter, sind aber seneszent, gleichsam „Zombie-Zellen“. Diese nach Leonard Hayflick benannte Grenze zeigt früh, dass Altern auch von innen kommt. Sie bedeutet aber nicht, dass ein Programm den ganzen Körper altern lässt. Stoffwechselabfälle können eine Kultur tatsächlich bremsen, doch hier wurde das Medium regelmäßig gewechselt. Programmierter Zelltod kommt vor, die Zellen blieben aber am Leben. Wachstumssignale sind nötig, doch die Bedingungen blieben konstant, ein plötzlich ausbleibendes Signal gibt es also nicht.","coreRule":"⚡ Wenn ein Effekt trotz konstanter, idealer Außenbedingungen eintritt, such die Ursache im System selbst.","beleg":"Werkstück C.4.10 (Die tickende Uhr in der Petrischale; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Kommilitonin sagt: „Zellen in einer idealen Umgebung müssten sich doch ewig teilen können. Wenn sie aufhören, muss die Nährlösung schuld sein.“ Du sollst beurteilen, ob das stimmt.","quote":"","quoteLabel":"","kurz":"Die Bedingungen waren ideal und konstant, der Teilungsstopp kam trotzdem. Der Fehler liegt nahe, die Umgebung verantwortlich zu machen. Der Befund deutet auf eine Grenze in der Zelle: Telomere verkürzen sich mit jeder Teilung, bis ein Stopp ausgelöst wird.","prueffrage":"Was hat sich im Labor über die Zeit verändert, und was blieb für die Zellen konstant?","rueckmeldung":[{"option":1,"text":"Dass sich Abfallstoffe anhäufen und eine Kultur bremsen können, ist durchaus möglich. Hier wurde das Medium aber regelmäßig gewechselt, und der Stopp kam trotzdem nach etwa 50 Teilungen. Die Umgebung bleibt so als Ursache unbelegt."},{"option":2,"text":"Programmierter Zelltod kommt tatsächlich vor und räumt gealterte Zellen ab. Im Befund sterben die Zellen aber nicht, sie bleiben am Leben und hören nur auf, sich zu teilen. Zum Beobachteten passt das nicht."},{"option":3,"text":"Zellen brauchen Wachstumssignale, damit hat die Antwort recht. Doch die Bedingungen blieben konstant und ideal, ein plötzlich ausbleibendes Signal gibt es also nicht. Die Ursache liegt wieder außerhalb, obwohl der Befund auf eine Grenze in der Zelle selbst weist."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"41b70871e91a3e08"}},{"id":"qx-c2-028","clusterId":"C","werkstueckRef":"C.4.10","stufe":2,"question":"Welche Erklärung ist am sparsamsten für diesen Befund?","options":["Die Zellen verbrauchen mit der Zeit die Nährstoffe so stark, dass der Mangel die Teilung stoppt; Tumorzellen kommen mit deutlich weniger Nährstoffen aus.","Die Zellen stoppen die Teilung selbst, als Schutz vor Krebs, wenn sie die Verkürzung als mögliche DNA-Schädigung deuten; Tumorzellen umgehen diese Bremse.","Die Zellen beseitigen sich selbst durch programmierten Zelltod, wenn die Verkürzung als mögliche DNA-Schädigung gedeutet wird; Tumorzellen entgehen ihm.","Ein Störfaktor in der Kultur, etwa eine Verunreinigung, hemmt die Teilung; Tumorzellen sind gegen diesen Störfaktor besonders widerstandsfähig."],"correctIndex":1,"explanation":"Der Befund enthält drei Hinweise: Die Nährlösung ist nicht der Engpass, die Zellen leben nach dem Stopp weiter, und die Chromosomenenden sind kürzer geworden. Das passt zu einer eingebauten Bremse: Bei jeder Teilung geht ein Stück der Schutzkappen (Telomere) verloren. Erreichen sie eine kritische Kürze, wird das als mögliche DNA-Schädigung gedeutet, das Wächter-Gen p53 stoppt die Teilung, und die Zelle bleibt als seneszente „Zombie-Zelle“ am Leben. Das verhindert, dass beschädigte Zellen sich unkontrolliert vermehren. Tumorzellen teilen sich unbegrenzt, weil sie oft das Enzym Telomerase reaktivieren und so die Grenze umgehen. Nährstoffmangel bremst Kulturen oft, wurde hier aber durch die erneuerte Lösung ausgeschlossen. Programmierter Zelltod ist ein anderer Weg, doch die Zellen leben ja weiter. Ein Störfaktor in der Schale müsste auch die Tumorzellen treffen und bräuchte eine Zusatzannahme, während die verkürzten Schutzkappen schon alles erklären.","coreRule":"⚡ Wähle die Erklärung, die alle Beobachtungen zugleich trägt, und prüfe jede Alternative an dem, was sie vorhersagen würde.","beleg":"Werkstück C.4.10 (Kontext & Tiefe, Der Seneszenz-Stopp; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Labor züchtet gesunde menschliche Zellen in einer Nährlösung, die immer wieder erneuert wird, sodass nichts knapp wird. Nach etwa 50 Teilungen hören die Zellen auf, sich zu teilen, bleiben aber am Leben und verbrauchen weiter Nährstoffe. Messungen zeigen, dass die Schutzkappen an den Chromosomenenden mit jeder Teilung kürzer geworden sind und nun eine kritische Länge erreicht haben. Gleichzeitig teilen sich Zellen aus einem Tumor unter denselben Bedingungen unbegrenzt weiter.","quote":"","quoteLabel":"","kurz":"Verkürzte Schutzkappen, erneuerte Nährlösung und überlebende Zellen passen zu einer eingebauten Teilungsbremse, die Tumorzellen umgehen. Nahe liegt dagegen ein Mangel oder ein Störfaktor, doch beides bräuchte Zusatzannahmen und erklärt die Kappen nicht.","prueffrage":"Was lässt sich in der Schale beobachten, nachdem die Teilung aufgehört hat, und was zeigt die Messung an den Chromosomenenden?","rueckmeldung":[{"option":0,"text":"Nährstoffmangel bremst Kulturen oft und liegt als Erklärung nahe. Hier ist er aber durch die erneuerte Lösung ausgeschlossen, und die Zellen verbrauchen nach dem Stopp weiter Nährstoffe. Die Anngenügsamkeit der Tumorzellen ist zudem nur dazugedacht."},{"option":2,"text":"Dass verkürzte Schutzkappen als mögliche DNA-Schädigung gedeutet werden, stimmt, und programmierter Zelltod ist ein realer Folgeweg. Hier sterben die Zellen aber nicht, sondern bleiben am Leben, ohne sich zu teilen."},{"option":3,"text":"Eine Verunreinigung ist denkbar, müsste aber auch die Tumorzellen in derselben Schale treffen. Das gelingt nur mit der Zusatzannahme besonderer Resistenz, und die verkürzten Schutzkappen blieben unerklärt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"826d081e477b21b4"}},{"id":"qx-c2-029","clusterId":"C","werkstueckRef":"C.4.10","stufe":3,"question":"Ein Forschungsteam schlägt vor, in gesunden Körperzellen das Enzym Telomerase dauerhaft zu aktivieren, damit sie sich unbegrenzt teilen können und das Altern aufgehalten wird. Krebszellen sind häufig deshalb „unsterblich“, weil sie Telomerase wieder anschalten. Welches Dilemma folgt daraus?","options":["Telomerase-Hemmer würden Tumoren bremsen, aber auch Stammzellen schädigen, die ihre Teilungsfähigkeit brauchen; das Dilemma liegt also in der Krebstherapie.","Telomerase würde die Zellen zwar länger teilungsfähig halten, doch das Altern hat viele weitere Ursachen, sodass der Körper trotzdem weiter altern würde.","Wer sich eine solche Behandlung leisten kann, würde länger leben als andere; das Dilemma liegt dann in der ungleichen Verteilung der gewonnenen Lebensjahre.","Telomerase könnte gesunden Zellen dieselbe Unsterblichkeit geben wie Krebszellen, sodass die schützende Teilungsgrenze entfiele und das Krebsrisiko stiege."],"correctIndex":3,"explanation":"Normale Zellen können sich nur etwa 40 bis 60 Mal teilen. Wenn die Telomere kritisch kurz werden, deutet die Zelle das als mögliche gefährliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und stellt die Teilung ein. Diese Grenze schützt damit vor Krebs. Krebszellen umgehen sie häufig, indem sie Telomerase reaktivieren. Wer Telomerase in gesunden Zellen aktiviert, nimmt ihnen deshalb dieselbe Bremse. Ein möglicher Gewinn (länger teilungsfähige Zellen) ist untrennbar mit einem Risiko (ungebremstes Wachstum geschädigter Zellen) verbunden. Das Dilemma entsteht, weil Nutzen und Schaden am selben Mechanismus hängen. Telomerase-Hemmer in der Krebstherapie werfen ein eigenes Dilemma auf, doch das ist die Gegenrichtung und nicht Gegenstand des Vorschlags. Dass Altern viele Ursachen hat, schmälert den Nutzen, beschreibt aber keinen Konflikt von Nutzen und Risiko am selben Mechanismus. Gerechtigkeitsfragen einer solchen Behandlung sind real, folgen aber nicht aus dem, was über Krebszellen und Telomerase gesagt ist.","coreRule":"⚡ Wer eine Schutzgrenze aufhebt, um einen Nutzen zu gewinnen, nimmt auch den Schutz weg, den sie geboten hat: Prüfe, wofür die Grenze da ist, bevor du sie abschaffen willst.","beleg":"Werkstück C.4.10 (Anwendung & Relevanz); vgl. Werkstück C.4.4","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Dieselbe Telomerase, die Zellen länger teilungsfähig hielte, schaltet auch die Teilungsgrenze aus, die normalerweise vor Krebs schützt. Nutzen und Risiko hängen am selben Mechanismus, deshalb lässt sich der Gewinn nicht vom Schaden trennen.","prueffrage":"Was geschieht normalerweise, wenn die Telomere einer gesunden Zelle sehr kurz geworden sind?","rueckmeldung":[{"option":0,"text":"Hemmer gegen Tumoren, die Stammzellen mittreffen, sind tatsächlich ein eigenes Dilemma. Es liegt aber in der Gegenrichtung, denn der Vorschlag will Telomerase einschalten, nicht hemmen. Gefragt ist, was dieses Einschalten selbst mit sich bringt."},{"option":1,"text":"Dass Altern viele Ursachen hat, begrenzt den möglichen Nutzen. Es beschreibt aber nur einen kleineren Gewinn und keinen Konflikt, bei dem Nutzen und Schaden am selben Mechanismus hängen. Von einem Risiko ist in dieser Antwort keine Rede."},{"option":2,"text":"Die Verteilung gewonnener Lebensjahre ist eine reale Gerechtigkeitsfrage. Sie folgt aber nicht aus dem, was über Krebszellen und Telomerase gesagt ist, und betrifft weder den Mechanismus noch das Krebsrisiko."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7666b8a5abcc5fb1"}},{"id":"qx-c2-030","clusterId":"C","werkstueckRef":"C.4.10","stufe":4,"question":"Wie ist die Aussage „Die Forschung hat bewiesen: höchstens 120 bis 150 Jahre“ einzuordnen?","scenario":"Ein Artikel meldet: „Die Forschung hat bewiesen: Der Mensch kann höchstens 120 bis 150 Jahre alt werden.“ Als Grundlage dient eine Modellrechnung, die aus den Blutwerten von Hunderttausenden Menschen schätzt, wann die körperliche Widerstandsfähigkeit vollständig verloren ginge. Andere Forschergruppen werten stattdessen die tatsächlich erreichten Höchstalter aus und kommen zu voneinander abweichenden Ergebnissen: Die eine sieht die Höchstalter seit Jahrzehnten bei 114 Jahren stagnieren, die andere findet ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze.","options":["Als Schätzung eines Modells; weil Auswertungen tatsächlicher Höchstalter zu abweichenden Ergebnissen kommen, ist „bewiesen“ zu stark.","Als bewiesen, weil die Modellrechnung auf den Daten von Hunderttausenden Menschen beruht und eine so große Stichprobe das Ergebnis absichert.","Als Zirkelschluss; weil das Modell die Grenze schon in seine Annahmen einbaut, kann es sie am Ende nur als Ergebnis wieder ausgeben.","Als Aussage, die zunächst unbeurteilbar ist; erst wenn bekannt ist, wer die Modellrechnung finanziert hat, lässt sich ihr Gewicht einschätzen."],"correctIndex":0,"explanation":"Eine Modellrechnung, die aus Blutwerten einen Punkt „totalen Resilienzverlusts“ schätzt (Pyrkov u. a. 2021: etwa 120–150 Jahre), ist eine Modellschätzung, kein direkt beobachteter Wert. Das zeigt schon der Blick auf die Gegenseite: Eine Auswertung der jährlichen Höchstalter (Dong u. a. 2016) sieht seit den 1990er Jahren eine Stagnation bei 114 Jahren, eine andere (Barbi u. a. 2018) ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze. Wo sich methodisch unterschiedliche Auswertungen nicht einig sind, ist die Frage offen. Eine große Stichprobe ändert an der Natur einer Modellschätzung nichts. Wer eine offene Forschungsfrage als „bewiesen“ meldet, zeigt mehr Sicherheit, als die Belege hergeben. Ein Zirkelschluss liegt nicht vor: Das Modell schätzt die Grenze aus den Blutwerten, es setzt sie nicht voraus. Wer die Studie finanziert hat, ist eine gute Zusatzfrage, doch die Einordnung ist schon aus den widersprüchlichen Auswertungen möglich.","coreRule":"⚡ Eine Modellschätzung ist kein Beweis, und widersprechen sich unabhängige Auswertungen, ist die Frage offen.","beleg":"Werkstück C.4.10 (Die Berechnungen; Der Stand der Forschung); Fn. gl-c-lebensspanne (Pyrkov u. a. 2021, Nat. Commun. 12, Art. 2765); Fn. gl-c-lebensspanne-dissens (Dong u. a. 2016, Nature 538, S. 257–259; Barbi u. a. 2018, Science 360, S. 1459–1461; Warner u. a. 2005)","status":"entwurf","kurz":"Aus Blutwerten wird ein Grenzwert geschätzt, nicht beobachtet, und Auswertungen der tatsächlichen Höchstalter kommen zu anderen Ergebnissen. Wo sich die Auswertungen uneinig sind, ist die Frage offen, und „bewiesen“ meldet mehr Sicherheit, als die Belege hergeben.","prueffrage":"Was wurde für die Modellrechnung tatsächlich gemessen, und welcher Wert wurde daraus erst errechnet?","rueckmeldung":[{"option":1,"text":"Hunderttausende Datensätze wirken gewichtig, und die Blutwerte sind echt gemessen. Aus ihnen wird aber ein Grenzwert hochgerechnet, und dieser Rechenschritt bleibt eine Schätzung, egal wie groß die Stichprobe ist."},{"option":2,"text":"Der Vorwurf klingt methodenkritisch. Das Modell schätzt die Grenze jedoch aus den Blutwerten und setzt sie nicht schon voraus, deshalb schließt sich hier kein Kreis."},{"option":3,"text":"Die Frage nach der Finanzierung ist eine sinnvolle Zusatzprüfung. Für die Einordnung braucht es sie hier aber nicht, denn schon die voneinander abweichenden Auswertungen der tatsächlichen Höchstalter zeigen, dass „bewiesen“ zu stark ist."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Pyrkov u. a. 2021, Longitudinal analysis of blood markers reveals progressive loss of resilience and predicts human lifespan limit, Nature Communications 12 (PMC8149842)","oeffentlich":true,"doi":"10.1038/s41467-021-23014-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dong, Milholland & Vijg 2016, Evidence for a limit to human lifespan, Nature 538 (PMC11673931)","oeffentlich":true,"doi":"10.1038/nature19793","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barbi u. a. 2018, The plateau of human mortality: Demography of longevity pioneers, Science 360 (PMC6457902)","oeffentlich":true,"doi":"10.1126/science.aat3119","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"333cdbb440d9d7ca"}},{"id":"qx-c2-031","clusterId":"C","werkstueckRef":"C.4.11","stufe":1,"question":"Ein Museumstext behauptet: „Vor etwa 300 Millionen Jahren gab es Libellen mit der Spannweite von Möwen – das beweist, dass die Schwerkraft damals deutlich geringer war.“ Welche Prüfung trifft den Kern der Behauptung am besten?","options":["Gibt es unabhängige Belege für eine geringere Schwerkraft, und lässt sich die Größe der Libellen auch ohne sie erklären?","Sind die Fossilien tatsächlich rund 300 Millionen Jahre alt, und wurden die Spannweiten an vollständigen Funden gemessen?","Wer hat den Museumstext verfasst, und hat diese Person eine fachliche Ausbildung in Paläontologie oder Geologie?","Sind die Funde repräsentativ, oder stammen sie alle aus einer einzigen Fundstelle mit besonderen Bedingungen?"],"correctIndex":0,"explanation":"Der Schluss „riesige Tiere, also geringere Schwerkraft“ ist eine Erklärung unter mehreren. Gute Prüfung heißt, nach unabhängigen Belegen für genau diese Ursache zu fragen und zu klären, ob eine andere Erklärung dasselbe leistet. Hier gibt es sie: Nach gängigen Modellen (Berner 2006; Krause u. a. 2018) lag der Sauerstoffgehalt vor rund 300 Millionen Jahren bei etwa 25 bis 30 Prozent (heute 21), gestützt durch fossile Holzkohle. Insekten haben ein einfaches Atmungssystem, das von höherer Sauerstoffkonzentration profitierte; das macht große Körper plausibel (Clapham/Karr 2012). Für eine andere Schwerkraft gibt es keinen Beleg; die Größe lässt sich auch ohne diese Annahme über den Sauerstoff erklären. Auch die Sauerstofferklärung bleibt eine begründete Vermutung, kein bewiesener Befund. Alter und Vollständigkeit der Funde zu prüfen ist sinnvoll, doch das Szenario nennt sie als belegt, und selbst gesicherte Funde sagen nichts über die Ursache der Größe. Die Frage nach dem Verfasser des Textes prüft eine Person, nicht die Behauptung. Und ob die Funde repräsentativ sind, betrifft, wie verbreitet solche Riesen waren, nicht, warum sie so groß werden konnten.","coreRule":"⚡ Eine Behauptung prüfst du, indem du nach unabhängigen Belegen für genau die genannte Ursache fragst und nach einfacheren Erklärungen suchst.","beleg":"Werkstück C.4.11 (Der Sauerstoffgehalt); Fn. gl-c-karbon (Sauerstoffwerte: Berner 2006, Krause u. a. 2018; Insektengröße: Clapham/Karr 2012)","status":"entwurf","scenario":"Fossilien aus dem Karbon belegen riesige libellenähnliche Insekten, sogenannte Riesenlibellen. Zugleich weisen unabhängige Spuren (etwa fossile Holzkohle) und mehrere Klimamodelle auf einen Sauerstoffanteil der Luft von etwa 25 bis 30 Prozent hin, gegenüber 21 Prozent heute.","kurz":"Aus „riesig“ folgt nicht „geringe Schwerkraft“: Das ist nur eine von mehreren möglichen Erklärungen. Gefragt werden muss nach unabhängigen Belegen dafür und danach, ob etwas anderes die Größe ebenso erklärt, hier etwa ein höherer Sauerstoffgehalt.","prueffrage":"Was an der Behauptung im Museumstext ist durch Fossilien belegt, und was ist daraus erst gefolgert?","rueckmeldung":[{"option":1,"text":"Alter und Vollständigkeit der Funde zu prüfen ist sinnvoll, doch das Szenario nennt sie bereits als belegt. Selbst gesicherte Funde sagen noch nichts darüber, warum die Tiere so groß wurden."},{"option":2,"text":"Die Frage nach dem Verfasser wirkt wie gründliches Prüfen, nimmt aber eine Person in den Blick statt die Aussage. Auch eine Fachfrau kann sich irren, und der Satz muss sich an seinen Belegen messen lassen."},{"option":3,"text":"Ob die Funde repräsentativ sind, ist eine gute Frage, sagt aber nur, wie verbreitet solche Riesen waren. Warum sie so groß werden konnten, bleibt davon unberührt, und genau darauf zielt die Behauptung."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Krause u. a. 2018, Stepwise oxygenation of the Paleozoic atmosphere, Nature Communications 9 (PMC6172248)","oeffentlich":true,"doi":"10.1038/s41467-018-06383-y","abruf":"2026-10-12"},{"typ":"doi","kurz":"Clapham & Karr 2012, Environmental and biotic controls on the evolutionary history of insect body size, PNAS 109(27) (PMC3390886)","oeffentlich":true,"doi":"10.1073/pnas.1204026109","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Berner 2006, GEOCARBSULF: A combined model for Phanerozoic atmospheric O2 and CO2, Geochim Cosmochim Acta 70(23)","oeffentlich":false,"doi":"10.1016/j.gca.2005.11.032"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"929aa2d91d33f4ae"}},{"id":"qx-c2-032","clusterId":"C","werkstueckRef":"C.4.11","stufe":2,"question":"Eine Schülerin behauptet: „Ein Blauwal ist so riesig, weil Meerestiere einfach stärkere Gene für Wachstum haben als Landtiere.“ Was spricht am stärksten gegen diese Erklärung?","options":["Ein Tier im Wasser wird vom Auftrieb getragen, ein Landtier muss sein ganzes Gewicht selbst stützen und braucht dafür im Verhältnis immer massivere Knochen.","Körpergröße ist bei Tieren zu einem erheblichen Teil erblich, und große Eltern haben meist große Nachkommen, sodass Gene bei Größenunterschieden durchaus mitwirken.","Wasser enthält weniger gelösten Sauerstoff als Luft, sodass große Körper im Wasser mit der Atmung und Versorgung ihrer Zellen eher schwerer zurechtkommen.","Blauwale legen für ihre weiten Wanderungen dicke Fettreserven an, die einen großen Teil ihres Körpergewichts ausmachen, ohne dass sie dabei Nahrung aufnehmen."],"correctIndex":0,"explanation":"Die Erklärung über „stärkere Gene“ übersieht, dass die Umgebung die Möglichkeiten vorgibt. Wasser trägt einen großen Teil des Körpergewichts durch Auftrieb, sodass ein Meerestier sein Gewicht kaum selbst stützen muss. An Land setzt die Schwerkraft dagegen eine Obergrenze: Je schwerer ein Landtier wird, desto massiver müssen seine tragenden Knochen im Verhältnis werden; schon Galilei hielt 1638 fest, dass Riesentiere im Wasser bestehen können, an Land aber nicht ohne veränderte Körperproportionen. Dass Körpergröße zum Teil erblich ist, stimmt, ist aber kein Gegenargument, sondern spricht eher dafür, dass Gene eine Rolle spielen. Dass Wasser weniger gelösten Sauerstoff enthält, erschwert große Körper eher, erklärt also nicht, warum Meerestiere größer werden. Fettreserven sind ein Teil des Körpergewichts, sagen aber nichts darüber, was dieses Gewicht überhaupt tragbar macht.","coreRule":"⚡ Bevor du Unterschiede den Genen zuschreibst, prüfe die physikalischen Rahmenbedingungen: An Land begrenzt die Schwerkraft die Größe, im Wasser trägt der Auftrieb mit.","beleg":"Werkstück C.4.11 (Die Stärke der Erdanziehungskraft, Blauwal/Auftrieb); Fn. gl-c-schwerkraft (Galilei 1638: Riesentiere im Wasser; Campione/Evans 2012, BMC Biology 10, 60)","status":"entwurf","scenario":"Die Größe von Tieren hängt nicht nur von ihren Genen ab, sondern auch von den physikalischen Bedingungen, unter denen sie leben. Landtiere und Meerestiere tragen ihr Gewicht unter sehr verschiedenen Bedingungen.","kurz":"Wasser trägt durch Auftrieb einen großen Teil des Gewichts, an Land setzt die Schwerkraft dagegen eine Grenze, denn schwerere Tiere brauchen im Verhältnis massivere Knochen. Wer allein Gene anführt, übersieht, dass die Umgebung die Möglichkeiten vorgibt.","prueffrage":"Wie schwer werden die größten Tiere im Meer und an Land, und worin unterscheiden sich ihre Lebensbedingungen außer in den Genen?","rueckmeldung":[{"option":1,"text":"Dass Größe zum Teil erblich ist, stimmt. Genau deshalb widerlegt es die Behauptung nicht, sondern stützt sie eher. Offen bleibt, was die Umgebung erlaubt, und das behandelt dieser Hinweis nicht."},{"option":2,"text":"Weniger gelöster Sauerstoff im Wasser stimmt, macht große Körper dort aber eher schwerer. Es erklärt also nicht, warum Meerestiere größer werden, und sagt auch nichts gegen die Gen-Erklärung."},{"option":3,"text":"Fettreserven sind ein Teil des Körpergewichts, das stimmt. Sie sagen aber nichts darüber, was dieses Gewicht überhaupt tragbar macht, und gehen deshalb am Kern der Behauptung vorbei."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Campione & Evans 2012, A universal scaling relationship between body mass and proximal limb bone dimensions in quadrupedal terrestrial tetrapods, BMC Biology 10 (PMC3403949)","oeffentlich":true,"doi":"10.1186/1741-7007-10-60","abruf":"2026-10-12"},{"typ":"doi","kurz":"Biewener 2005, Biomechanical consequences of scaling, Journal of Experimental Biology 208(9)","oeffentlich":true,"doi":"10.1242/jeb.01520","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galilei 1638, Unterredungen und mathematische Demonstrationen über zwei neue Wissenszweige (dt. von Oettingen 1890, Ostwald's Klassiker 11)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"aa78f105be248302"}},{"id":"qx-c2-033","clusterId":"C","werkstueckRef":"C.4.11","stufe":3,"question":"Wie solltest du diese Aussage einschätzen?","scenario":"Jemand sagt: „Oxidation und Schwerkraft verhindern am Ende immer echte biologische Unsterblichkeit – das ist Physik, da gibt es keine Ausnahme.“ Du weißt: Die Maus lebt nur wenige Jahre. Der Nacktmull, ein Nagetier ähnlicher Größe, wird rund zehnmal so alt wie eine Maus, obwohl seine Zellen deutlich mehr oxidative Schäden aufweisen als die einer Maus.","options":["Als gesicherter Befund, weil physikalische Gesetze keine Ausnahmen kennen und langlebige Tiere sich nur langsamer abnutzen.","Als widerlegt, weil eine Regel ohne Ausnahme schon durch ein einziges Gegenbeispiel fällt und der Nacktmull eines liefert.","Als plausible Vermutung, nicht als Befund, weil ein Gegenbeispiel zur Vorsicht mahnt und die Aussage unbewiesen bleibt.","Als belanglos, weil sich Beobachtungen an einer Tierart nicht ohne Weiteres auf andere Arten übertragen lassen."],"correctIndex":2,"explanation":"Die Aussage klingt nach Physik, ist aber eine Vermutung über das Altern, kein gemessenes Ergebnis. Der Nacktmull zeigt, warum Vorsicht angebracht ist: Er lebt trotz deutlich höherer oxidativer Schäden (Andziak u. a. 2006) rund zehnmal so lange wie eine Maus ähnlicher Größe. Das widerlegt die Vermutung nicht, zeigt aber, dass viel Oxidation nicht zwingend ein kurzes Leben bedeutet. Zur Schwerkraft sagt das Beispiel nichts; dieser Teil der Aussage ist ebenso wenig belegt, nur behauptet. Dass Oxidation und Schwerkraft echte biologische Unsterblichkeit am Ende immer verhindern, bleibt deshalb eine Vermutung, kein Befund. Physikalische Gesetze kennen tatsächlich keine Ausnahmen, doch dass Oxidation und Schwerkraft ein solches Gesetz des Alterns bilden, ist hier nicht belegt. Widerlegt wäre die Aussage erst durch ein unsterbliches Lebewesen, und auch der Nacktmull stirbt am Ende. Dass sich Befunde einer Art nicht ohne Weiteres auf andere übertragen lassen, ist berechtigt, doch eine Aussage, die für alle Lebewesen gelten soll, muss sich auch an einer einzelnen Art messen lassen.","coreRule":"⚡ Plausible Grenzen sind keine bewiesenen Grenzen – ein Gegenbeispiel genügt zur Vorsicht.","beleg":"Werkstück C.4.11 (Schlussfolgerung); Fn. gl-c-nacktmull (Andziak u. a. 2006, Aging Cell 5(6), S. 463–471: hohe oxidative Schäden beim Nacktmull)","status":"entwurf","kurz":"Die Aussage klingt nach Physik, ist aber nur eine Vermutung über das Altern, kein Messergebnis. Der Nacktmull lebt trotz mehr oxidativer Schäden etwa zehnmal so lange wie die Maus. Das widerlegt nichts, mahnt aber zur Vorsicht.","prueffrage":"Was genau wurde beim Nacktmull gemessen, und sagt das etwas darüber aus, ob Unsterblichkeit möglich ist?","rueckmeldung":[{"option":0,"text":"Physikalische Gesetze kennen tatsächlich keine Ausnahmen. Aber dass Oxidation und Schwerkraft ein solches Gesetz des Alterns bilden, ist hier nicht belegt. Und der Nacktmull lebt trotz höherer Schäden länger, passt also nicht zu bloßer Abnutzung."},{"option":1,"text":"Ein einziges echtes Gegenbeispiel kann eine Allaussage tatsächlich kippen. Der Nacktmull ist aber keines: Er lebt zwar rund zehnmal so lange wie eine Maus, stirbt am Ende aber auch. Widerlegt wäre die Aussage erst durch ein unsterbliches Lebewesen."},{"option":3,"text":"Befunde einer Art lassen sich nicht ohne Weiteres auf andere übertragen. Die Aussage soll aber für alle Lebewesen gelten und muss sich deshalb auch an einer einzelnen Art messen lassen. Belanglos ist der Nacktmull daher nicht, er mahnt zur Vorsicht."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Andziak u. a. 2006, High oxidative damage levels in the longest-living rodent, the naked mole-rat, Aging Cell 5(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1111/j.1474-9726.2006.00237.x","url":"https://pubmed.ncbi.nlm.nih.gov/17054663/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d8ddef072ae335ef"}},{"id":"qx-c2-034","clusterId":"C","werkstueckRef":"C.4.11","stufe":4,"question":"Wie solltest du diesen Befund einordnen?","scenario":"Eine Schweizer Studie mit 1,64 Millionen Erwachsenen im Alter von 40 bis 84 Jahren, die in 259 bis 1960 Metern Höhe wohnen, zeigt: Je 1000 Höhenmeter starben 22 Prozent weniger Menschen an koronarer Herzkrankheit und 12 Prozent weniger an Schlaganfall. Frühere Studien zum Thema kamen zu widersprüchlichen Ergebnissen. Jemand folgert daraus: „Dünne Luft schützt das Herz.“","options":["Als Beobachtung mit offener Ursache: Der Zusammenhang selbst ist belegt, ob die dünne Luft der Grund ist, dagegen nicht.","Als Beleg für eine Schutzwirkung der dünnen Luft: Bei 1,64 Millionen Menschen kann der Zufall den Zusammenhang nicht erklären.","Als gesicherte Ursache: Das Risiko sinkt mit jeder Höhenstufe weiter, und ein solcher Stufenverlauf zeigt, dass die dünne Luft wirkt.","Als Handlungsempfehlung: Wer sein Herz schützen will, sollte in höhere Lagen ziehen, denn dort sinkt das Risiko deutlich."],"correctIndex":0,"explanation":"Die Studie fand einen deutlichen Zusammenhang zwischen Wohnhöhe und Sterblichkeit durch Herz- und Gefäßerkrankungen. Aus einem Zusammenhang in Beobachtungsdaten folgt aber noch nicht, was ihn verursacht. Menschen in höheren Lagen unterscheiden sich vermutlich auch in anderen Dingen, die den Effekt ganz oder teilweise erklären könnten; die Ursache bleibt offen. Dass dünne Luft die Ursache ist, bleibt eine Hypothese, die man gezielt prüfen müsste; frühere Studien mit widersprüchlichen Ergebnissen mahnen zusätzlich zur Vorsicht. Eine große Stichprobe macht den Zufall unwahrscheinlicher, räumt aber andere Unterschiede zwischen Höhen- und Tallagen nicht aus. Ein stufenweises Sinken des Risikos spricht eher für einen echten Einfluss, beweist aber nicht, dass gerade die dünne Luft wirkt. Und ob ein Umzug das eigene Risiko senken würde, kann eine reine Beobachtung nicht zeigen.","coreRule":"⚡ Auch ein gut gemessener Zusammenhang erklärt noch nicht, was ihn verursacht.","beleg":"Werkstück C.4.11 (Das Rennen der zwei Läufer); Fn. gl-c-hoehe (Faeh u. a. 2009, Circulation 120(6), S. 495–501)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Belegt ist der Zusammenhang zwischen Wohnhöhe und Herztod, nicht seine Ursache. Menschen in höheren Lagen unterscheiden sich vermutlich auch sonst, und das könnte den Effekt ganz oder teilweise erklären; „dünne Luft“ ist nur eine Hypothese.","prueffrage":"Worin könnten sich Menschen, die auf 1900 Metern wohnen, außer der Höhe noch von denen im Tal unterscheiden?","rueckmeldung":[{"option":1,"text":"Bei so vielen Menschen ist der Zufall als Erklärung tatsächlich unwahrscheinlich. Die Stichprobengröße sagt aber nichts über andere Unterschiede zwischen Höhen- und Tallagen, die den Effekt ebenfalls erzeugen könnten."},{"option":2,"text":"Ein Risiko, das mit der Höhe stufenweise sinkt, spricht eher für einen echten Einfluss. Es beweist aber nicht, dass gerade die dünne Luft wirkt, denn auch andere Unterschiede können mit der Höhe zunehmen."},{"option":3,"text":"Dass das Risiko in höheren Lagen niedriger liegt, zeigen die Daten. Ob ein Umzug das eigene Risiko senken würde, lässt sich daraus nicht ablesen, denn die Menschen dort unterscheiden sich vermutlich auch in anderem."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Faeh, Gutzwiller & Bopp 2009, Lower mortality from coronary heart disease and stroke at higher altitudes in Switzerland, Circulation 120(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1161/CIRCULATIONAHA.108.819250","url":"https://pubmed.ncbi.nlm.nih.gov/19635973/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"beb6a162572a11a5"}},{"id":"qx-c2-035","clusterId":"C","werkstueckRef":"C.5.1","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Politiker schließt aus einem einzelnen kalten Winter an einem Ort auf den langfristigen Temperaturtrend, obwohl dafür der Durchschnitt vieler Jahre entscheidend ist.","Der Politiker beruft sich auf die Zustimmung vieler Menschen im Land, obwohl die Zahl der Anhänger einer Aussage nichts über ihre Richtigkeit sagt.","Der Politiker verwechselt Korrelation und Kausalität, obwohl zwei Ereignisse, die gemeinsam auftreten, nicht in einem Ursache-Wirkung-Verhältnis stehen müssen.","Der Politiker greift die Klimaforscher persönlich an, obwohl die Eigenschaften einer Person nichts über die Richtigkeit ihrer Ergebnisse aussagen."],"correctIndex":0,"explanation":"Das Wetter ist von Natur aus variabel und chaotisch: wie ein Hund, der wild um seinen Besitzer herumläuft, während dieser stetig in eine Richtung geht. Das Klima ist der statistische Durchschnitt des Wetters samt der Häufigkeit von Extremen, typischerweise über rund 30 Jahre. Ein einzelner kalter Tag oder Winter an einem Ort sagt über diesen Trend deshalb ebenso wenig aus wie ein einzelner warmer. Zudem bedeutet Erwärmung nicht, dass es überall und jederzeit wärmer wird: Einzelne harte Kälteeinbrüche bleiben möglich. Wer aus ein paar Tagen auf den Trend schließt, schaut fünf Sekunden auf den Hund und übersieht den Spaziergänger.","coreRule":"⚡ Wetter ist der Hund, Klima ist der Spaziergänger: Ein einzelnes Ereignis widerlegt keinen Langzeittrend.","quote":"Sprechen wir hier gerade über den Hund (das Wetter) oder über den Spaziergänger (das Klima)? Ist diese kurzfristige Beobachtung repräsentativ für den langfristigen Trend?","quoteLabel":"Prüffrage:","beleg":"Werkstück C.5.1 (Kernidee; Kontext & Tiefe; Das Anti-Denkmuster)","status":"entwurf","scenario":"Nach dem kältesten Januar seit Jahrzehnten sagt ein Politiker vor laufender Kamera: „Es ist eiskalt, Schnee bis zum Knie. Die globale Erwärmung ist damit widerlegt!“","kurz":"Ein kalter Winter an einem Ort ist Wetter, kein Klima: Klima ist der Durchschnitt über rund 30 Jahre, und auch bei Erwärmung bleiben einzelne Kälteeinbrüche möglich. Wer aus ein paar Tagen auf den Trend schließt, übersieht den langen Verlauf.","prueffrage":"Wäre ein besonders heißer Januar an demselben Ort ein Beweis für die Erwärmung?","rueckmeldung":[{"option":1,"text":"Dass viele Menschen etwas glauben, beweist tatsächlich nichts. Der Politiker beruft sich hier aber gar nicht auf eine Mehrheit, sondern auf seine eigene Beobachtung von Kälte und Schnee. Der Fehler liegt im Schluss von dieser Beobachtung."},{"option":2,"text":"Dass gemeinsames Auftreten keine Ursache belegt, stimmt allgemein. Der Politiker behauptet aber keinen Zusammenhang zweier Ereignisse, sondern schließt von einem kalten Winter direkt auf den Trend. Es fehlt kein Ursachenbeweis, sondern eine ausreichende Datenbasis."},{"option":3,"text":"Ein persönlicher Angriff würde die Richtigkeit von Ergebnissen tatsächlich nicht widerlegen. Hier greift der Politiker aber niemanden an, er stützt sich nur auf das Wetter vor seiner Tür. Das Problem ist, dass diese Beobachtung für einen Trend nicht ausreicht."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"},{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"da4362ecc7bbe12a"}},{"id":"qx-c2-036","clusterId":"C","werkstueckRef":"C.5.1","stufe":2,"question":"Was ist an dieser Aussage richtig, und was blendet sie aus?","scenario":"Nach einer Hitzewelle sagt ein Bekannter: „Solche Hitzewellen hat es schon immer gegeben. Das ist kein Beweis für irgendeinen Klimawandel.“","options":["Sie stimmt, blendet aber aus, dass es bei Extremwetter nicht darum geht, ob es solche Ereignisse je gab, sondern ob sie häufiger und heftiger werden.","Sie stimmt, blendet aber aus, dass Hitzewellen für Gesundheit und Landwirtschaft gefährlich sind, was unabhängig von ihrer Ursache Vorsorge verlangt.","Sie stimmt, blendet aber aus, dass frische Ereignisse im Gedächtnis überschätzt werden, sodass sich jede neue Hitzewelle häufiger anfühlt als frühere.","Sie stimmt, blendet aber aus, dass der Begriff Hitzewelle in verschiedenen Ländern unterschiedlich definiert wird und Vergleiche über Ländergrenzen deshalb schwierig sind."],"correctIndex":0,"explanation":"Die Aussage ist richtig, aber sie beantwortet eine Frage, die niemand stellt. Die Klimawissenschaft behauptet nicht, Hitzewellen seien neu, sondern dass ihre Häufigkeit und Intensität zunehmen, weil dem System zusätzliche Energie zugeführt wird. Dass etwas früher vorkam, schließt nicht aus, dass es heute häufiger oder heftiger vorkommt. Zur Veranschaulichung: Auch Verkehrsunfälle gab es schon immer; entscheidend ist, ob ihre Zahl steigt. Für Hitzeextreme zeigt der IPCC-Bericht (2021) tatsächlich, dass Hitzewellen seit den 1950er-Jahren in den meisten Landregionen häufiger und heftiger geworden sind, Kälteextreme dagegen seltener und milder. Dabei lohnt Genauigkeit: Bei Hitzeextremen ist die Zunahme praktisch sicher, bei Dürren je nach Region und Dürretyp unterschiedlich gut belegt. Wer „gab es schon immer“ sagt, vergleicht also Existenz mit Häufigkeit und weicht damit der eigentlichen Frage aus. Die Gefahr von Hitze ist real, beantwortet aber nicht, was die Aussage ausblendet. Dass frische Ereignisse überschätzt werden, ist eine bekannte Verzerrung, widerlegt aber nicht die gemessene Zunahme. Dass Hitzewellen je nach Land unterschiedlich definiert werden, stimmt, ändert aber nichts daran, dass Existenz und Häufigkeit zweierlei sind.","coreRule":"⚡ „Gab es schon immer“ ist richtig, aber die Häufigkeit zählt.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage; Anwendung & Relevanz); Fn. gl-c-ipcc-extreme (IPCC 2021, Summary for Policymakers, A.3.1 und A.3.2, S. 8)","status":"entwurf","kurz":"Dass es Hitzewellen schon immer gab, stimmt, beantwortet aber nicht die Frage, um die es geht: ob sie häufiger und heftiger werden. Früheres Vorkommen schließt ein Mehr heute nicht aus, so wenig wie bei Verkehrsunfällen.","prueffrage":"Was müsste man zählen oder messen, um zu prüfen, ob sich bei Hitzewellen in den letzten Jahrzehnten etwas verändert hat?","rueckmeldung":[{"option":1,"text":"Hitzewellen sind tatsächlich gefährlich, und Vorsorge ist sinnvoll, egal wie man ihre Ursache sieht. Das sagt aber nichts darüber, was der Satz „gab es schon immer“ ausblendet: Er beantwortet die Frage nach der Entwicklung gar nicht."},{"option":2,"text":"Frische Ereignisse werden im Gedächtnis tatsächlich überschätzt, das ist eine bekannte Verzerrung. Sie widerlegt aber nicht die gemessene Zunahme von Hitzewellen und benennt auch nicht, was am Satz des Bekannten fehlt."},{"option":3,"text":"Hitzewellen werden je nach Land unterschiedlich definiert, das stimmt, und Ländervergleiche sind deshalb heikel. Der Bekannte vergleicht aber keine Länder, und am Unterschied zwischen „gab es“ und „gibt es häufiger“ ändert das nichts."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1 und A.3.2","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"969ce45497c835e5"}},{"id":"qx-c2-037","clusterId":"C","werkstueckRef":"C.5.1","stufe":3,"question":"Welche Entscheidung zeigt am deutlichsten, dass hier Wetter mit Klima verwechselt wird?","options":["Der Deichbau wird gestoppt, weil es in den letzten Wochen zufällig trocken war – ein kurzfristiger Eindruck ersetzt hier Langzeitdaten.","Der Deichbau wird verschoben, weil die Pegelmessungen der letzten Jahrzehnte erst noch genauer ausgewertet und geprüft werden sollen.","Der Deichbau wird beschlossen, weil die Messreihen zeigen, dass starke Hochwasser im Mittel häufiger und heftiger geworden sind.","Der Deichbau wird in der Gemeinde diskutiert, weil einzelne Anwohner von ihren Erfahrungen mit früheren Überschwemmungen berichtet haben."],"correctIndex":0,"explanation":"Entscheidungen von langer Reichweite müssen sich auf den langfristigen statistischen Trend stützen, nicht auf den Zustand der letzten Tage oder Wochen. Drei trockene Wochen sind Wetter; Klima ist der statistische Durchschnitt über Jahrzehnte (typischerweise 30 Jahre). Einen Deichbau zu stoppen, weil es heute gerade mal nicht regnet, ist ein Fehlschluss. Dasselbe Muster zeigt sich, wenn ein kalter Wintertag als Argument gegen die Erwärmung der Erde ins Feld geführt wird: Ein kurzfristiger Eindruck wird zur Grundlage einer Entscheidung mit langem Zeithorizont, während die Langzeitdaten übergangen werden. Die anderen Varianten stützen sich dagegen auf Messreihen oder diskutieren sie, statt sie durch einen Momenteindruck zu ersetzen.","coreRule":"⚡ Kippt, wenn ein kurzer Eindruck Entscheidungen über Jahrzehnte begründen soll.","beleg":"Werkstück C.5.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"In einer Gemeinde wird über den Bau eines Deiches gegen Hochwasser beraten. Ein Gemeinderat sagt: „Die letzten drei Wochen war es trocken. Wir können das Geld für den Deich sparen.“ Eine Nachbargemeinde dagegen stützt ihre Entscheidung auf Pegelmessungen und Niederschlagsstatistiken der letzten Jahrzehnte.","quote":"","quoteLabel":"","kurz":"Der Deichbau soll Jahrzehnte schützen, also muss sich die Entscheidung auf den langfristigen Trend stützen. Drei trockene Wochen sind Wetter, Klima ist der Durchschnitt über viele Jahre. Wer aus dem Momenteindruck den Verzicht ableitet, übergeht die Langzeitdaten.","prueffrage":"Über welchen Zeitraum liegen die Daten oder Eindrücke vor, auf die sich die jeweilige Entscheidung stützt?","rueckmeldung":[{"option":1,"text":"Sorgfältiges Auswerten wirkt zunächst wie Zögern, und Verschieben kann man kritisieren. Mit dem Wetter-Klima-Fehler hat das aber nichts zu tun: Die Langzeitdaten bleiben die Grundlage und werden nicht durch einen Momenteindruck ersetzt."},{"option":2,"text":"Hier liegt gerade kein Fehler vor, sondern das Gegenbeispiel: Der Beschluss stützt sich auf Messreihen über viele Jahre. Genau so sollte eine Entscheidung mit langem Zeithorizont begründet werden, statt mit dem Zustand weniger Wochen."},{"option":3,"text":"Einzelne Erfahrungsberichte ersetzen zwar keine Messreihen. Hier wird aber nur diskutiert, nicht entschieden, und es wird kein kurzfristiges Wetter gegen Langzeitdaten ausgespielt. Die Verwechslung von Wetter und Klima liegt woanders."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad5a5273a584a26b"}},{"id":"qx-c2-038","clusterId":"C","werkstueckRef":"C.5.1","stufe":4,"question":"Ein Bekannter sagt: „Wenn Wärme immer vom Wärmeren zum Kälteren fließt, müsste sich der Temperaturunterschied zwischen Tropen und Polen längst aufgelöst haben, und es gäbe gar kein wechselhaftes Wetter mehr.“ Was ist an diesem Schluss fehlerhaft?","options":["Er übersieht, dass die Sonne den Unterschied jeden Tag neu schafft, sodass der Ausgleich nie fertig wird und gerade dadurch Wind und Wetter entstehen.","Er übersieht, dass Wolken einen Teil des Sonnenlichts ins All zurückwerfen, sodass die Tropen weniger Energie bekommen, als man allein aus der Einstrahlung erwartet.","Er übersieht, dass die Ozeane große Wärmemengen speichern, sodass sie Temperaturunterschiede abpuffern und die Luftbewegung dadurch eher beruhigen.","Er übersieht, dass die Erdachse geneigt ist, sodass im Jahresverlauf mal der Norden, mal der Süden stärker bestrahlt wird und die Jahreszeiten entstehen."],"correctIndex":0,"explanation":"Der Schluss tut so, als gäbe es nur einen einmaligen Ausgleich. In Wirklichkeit heizt die Sonne die Tropen Tag für Tag stärker als die Pole und schafft den Unterschied immer wieder neu. Wärme fließt vom Wärmeren zum Kälteren, Winde tragen sie polwärts und bauen den Unterschied ab, doch bevor er verschwunden ist, ist er schon wieder da. Dieser nie vollendete Ausgleich hält die Luftbewegung am Laufen und ist der Antrieb des Wettergeschehens (Kleidon 2012). Ein System, das ständig Energie von außen bekommt, kommt nicht zur Ruhe. Dass Wolken einen Teil des Sonnenlichts zurückwerfen, stimmt, doch die Tropen bekommen trotzdem mehr Energie als die Pole, und der Unterschied wird dadurch nicht erneuert. Die Ozeane speichern tatsächlich viel Wärme und puffern Unterschiede, liefern aber keine neue Energie, die das Gefälle immer wieder herstellt. Die Erdneigung erzeugt die Jahreszeiten, erklärt aber nicht, warum der Unterschied zwischen Tropen und Polen trotz des laufenden Ausgleichs bestehen bleibt.","coreRule":"⚡ Wo ein Unterschied ständig neu entsteht, läuft der Ausgleich ständig weiter – und dieser Dauerlauf ist der Motor des Wetters.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage); Fn. gl-c-kleidon (Kleidon 2012, Physik in unserer Zeit 43(3), S. 138–140)","status":"entwurf","scenario":"Die Sonne strahlt auf die Tropen stärker ein als auf die Pole. Wärme fließt von selbst vom Wärmeren zum Kälteren, und Winde tragen sie polwärts.","kurz":"Der Schluss tut so, als wäre der Ausgleich einmalig. Die Sonne heizt die Tropen aber jeden Tag stärker als die Pole und schafft den Unterschied immer wieder neu. So kommt das System nie zur Ruhe, und der Ausgleich treibt das Wetter an.","prueffrage":"Was müsste geschehen, damit Tropen und Pole am Ende tatsächlich gleich warm wären?","rueckmeldung":[{"option":1,"text":"Dass Wolken Sonnenlicht zurückwerfen, stimmt. Die Tropen bekommen aber trotzdem mehr Energie als die Pole, und der Unterschied wird dadurch nicht immer wieder neu hergestellt. Das erklärt den Fehler im Schluss nicht."},{"option":2,"text":"Ozeane speichern tatsächlich viel Wärme und puffern Unterschiede. Sie liefern aber keine neue Energie, die das Gefälle wiederherstellt. Dass der Unterschied bestehen bleibt, erklärt das nicht."},{"option":3,"text":"Die Erdneigung erzeugt die Jahreszeiten, das trifft zu. Sie beantwortet aber eine andere Frage: Warum der Unterschied zwischen Tropen und Polen trotz des laufenden Ausgleichs bestehen bleibt, erklärt sie nicht."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA: Global Atmospheric Circulations","oeffentlich":true,"url":"https://noaa.gov/node/10334","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kleidon, A. (2012): Was leistet die Erde? Physik in unserer Zeit 43(3), 136–144 (doi 10.1002/piuz.201201294)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cf8ff120d1ad5cd8"}},{"id":"qx-c2-039","clusterId":"C","werkstueckRef":"C.5.2","stufe":1,"question":"Wie lässt sich am besten erklären, dass die Freundin ein Ungeheuer gesehen hat, obwohl es nur Otter waren?","scenario":"Eine Freundin schickt dir ein wackeliges, herangezoomtes Handyvideo von einem nebligen See: Ein dunkler, langer Schatten mit seltsamen Höckern bewegt sich durchs Wasser. Sie ist überzeugt: „Das ist ein Seeungeheuer, ich habe es mit eigenen Augen gesehen.“ Später stellt sich heraus, dass drei Otter hintereinander geschwommen sind.","options":["Das Auge hat unvollständige, verzerrte Daten geliefert, und das Gehirn hat die Lücken mit Erwartungen und Vorwissen gefüllt, hier mit einem Ungeheuer.","Erinnerungen verändern sich bei jedem Abruf, sodass die Freundin die Szene im Nachhinein ausgeschmückt hat; beim Sehen selbst war alles noch richtig.","Die Freundin hat die Szene bewusst übertrieben, weil ein Ungeheuer mehr Aufmerksamkeit bringt als drei Otter, und wollte andere damit beeindrucken.","Das Gehirn hat ohne äußeren Reiz ein Bild erzeugt, wie bei einer Halluzination, und die Freundin hat dieses innere Bild für die Wirklichkeit gehalten."],"correctIndex":0,"explanation":"Das Auge hat nicht gelogen, es hat Licht empfangen. Die Deutung kommt vom Gehirn, das unvollständige, verzerrte Daten mit Erwartungen und Vorwissen ergänzt; an einem nebligen See, um den sich Geschichten über Seeungeheuer ranken, kann daraus ein Monster werden. Dazu kommen Nebel, Wellenbewegung und die geringe Auflösung einer Zoom-Kamera, wodurch drei einzelne Tiere zu einer einzigen seltsamen Gestalt verschmelzen können. Die Behauptung „mit eigenen Augen gesehen“ beweist deshalb wenig: Was wir sehen, ist schon im Moment des Sehens eine Deutung der Daten, nicht erst in der Erinnerung. Dass Erinnerungen sich verändern, stimmt, doch hier geht es um das Sehen im Moment selbst. Dass Menschen übertreiben, um aufzufallen, kommt vor, aber die Freundin ist überzeugt und nicht berechnend. Und es gab einen echten äußeren Reiz, nämlich die drei Otter, also keine Halluzination.","coreRule":"⚡ Sehen ist Interpretieren, nicht Aufzeichnen: Bei unklaren Daten füllt das Gehirn die Lücken mit der erwarteten Geschichte.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.2 (Das Monster auf dem See; Kernidee)","status":"entwurf","kurz":"Das Auge hat Licht empfangen, die Deutung kommt vom Gehirn. Es ergänzt verzerrte, unvollständige Daten mit Erwartungen, und an einem nebligen See mit Ungeheuergeschichten kann so aus drei Ottern ein Monster werden. „Mit eigenen Augen gesehen“ beweist darum wenig.","prueffrage":"Wie gut waren Sicht, Entfernung und Bildqualität, und wie viel davon war tatsächlich zu erkennen?","rueckmeldung":[{"option":1,"text":"Erinnerungen verändern sich beim Abruf tatsächlich, das ist gut belegt. Hier liegt der Fehler aber früher: Schon im Moment des Sehens hat das Gehirn die verzerrten Daten gedeutet. Das Video zeigt zudem keine spätere Ausschmückung."},{"option":2,"text":"Manche übertreiben tatsächlich, um aufzufallen. Im Szenario aber ist die Freundin überzeugt, nicht berechnend. Sie hat wirklich ein Ungeheuer gesehen, weil ihr Gehirn die Daten so gedeutet hat, nicht weil sie etwas vorgespielt hat."},{"option":3,"text":"Eine Halluzination entsteht ohne äußeren Reiz, hier gab es aber einen: drei echte Otter im Nebel. Das Gehirn hat nichts aus dem Nichts erzeugt, sondern die vorhandenen, verzerrten Daten mit Erwartungen zu einem Ungeheuer ergänzt."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Gregory, R. L. (1997): Knowledge in perception and illusion. Philosophical Transactions of the Royal Society B 352(1358), 1121–1127","oeffentlich":true,"doi":"10.1098/rstb.1997.0095","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1692018/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d62ad9319e127b52"}},{"id":"qx-c2-040","clusterId":"C","werkstueckRef":"C.5.2","stufe":2,"question":"Welche Erklärung dieser „Orbs“ ist die sparsamste und lässt sich mit einem einfachen Test am besten prüfen?","scenario":"Du fotografierst mit Blitz in einer staubigen Dachkammer und siehst auf dem Bild runde, leuchtende Kugeln, die du vorher nicht bemerkt hast. Jemand sagt: „Das sind Geister.“","options":["Das Blitzlicht wird von nahen Staubpartikeln zurückgeworfen; in staubfreier Luft oder ohne Blitz erscheinen dieselben Kugeln nicht.","Bei wenig Licht entstehen helle Rauschpunkte im Sensor, die sich zu Kugeln verdichten; bei hellerem Licht oder niedriger Empfindlichkeit fehlen sie.","Temperaturunterschiede in der Dachkammer lassen die Luft flimmern und brechen das Licht zu Kugeln; ohne solche Unterschiede erscheinen sie nicht.","Streulicht im Objektiv erzeugt runde Blendenflecke, sobald eine helle Lichtquelle ins Bild strahlt; mit aufgesetzter Streulichtblende fehlen sie."],"correctIndex":0,"explanation":"Die sparsamste Erklärung nutzt nur bekannte Optik und lässt sich einfach testen: Das Blitzlicht der Kamera wird von nahen, unscharfen Staub- oder Feuchtigkeitspartikeln reflektiert (Backscatter) und erscheint als helle Kugel. Wiederholst du dasselbe Foto in staubfreier Luft oder ohne Blitz, sollten die Kugeln verschwinden. Helle Rauschpunkte entstehen bei wenig Licht, hier aber hat der Blitz die Szene hell ausgeleuchtet. Luftflimmern durch Temperaturunterschiede verzerrt Bilder, erzeugt aber keine Kugeln vor der Linse. Blendenflecke im Objektiv brauchen eine helle Lichtquelle im Bild, die hier nicht vorkommt. „Geister“ dagegen setzt etwas Neues voraus, für das es hier keinen Beleg gibt. Ein einzelnes Foto beweist deshalb keine Geistererscheinung.","coreRule":"⚡ Wenn eine bekannte Ursache ein Bild vollständig erklärt und sich testen lässt, brauchst du keine übernatürliche Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei Geister-Fotografie)","status":"entwurf","kurz":"Der Blitz leuchtet nahe Staubteilchen an, und die unscharf abgebildeten Reflexe sehen wie Kugeln aus. Ohne Blitz oder in staubfreier Luft müssten sie verschwinden. Etwas Neues wie „Geister“ braucht es dafür nicht.","prueffrage":"Was ändert sich auf einem zweiten Foto derselben Stelle, wenn du nur eine Bedingung der Aufnahme veränderst?","rueckmeldung":[{"option":1,"text":"Sensorrauschen ist ein echtes Phänomen und plausibel, wenn man an Aufnahmen im Dunkeln denkt. Hier hat der Blitz die Dachkammer aber hell ausgeleuchtet, und Rauschen zeigt sich eher als feines Korn denn als runde Kugeln."},{"option":2,"text":"Flimmernde Luft über Temperaturunterschieden kann ein Bild verzerren, das macht die Idee anschaulich. Kugeln vor der Linse erzeugt sie aber nicht, und von Temperaturunterschieden steht in der Situation auch nichts."},{"option":3,"text":"Blendenflecke im Objektiv sind tatsächlich rund und eine bekannte Fehlerquelle. Sie entstehen aber nur, wenn eine helle Lichtquelle ins Bild strahlt, und die gibt es in der Dachkammer nicht; die Streulichtblende prüft also etwas, das gar nicht vorliegt."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Society for Psychical Research, Psi Encyclopedia: Parsons, S.: Orbs (Light Anomalies)","oeffentlich":true,"url":"https://psi-encyclopedia.spr.ac.uk/articles/orbs-light-anomalies/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schwartz, G. E.; Creath, K. (2005): Anomalous orbic „spirit“ photographs? A conventional optical explanation. Journal of Scientific Exploration 19(3), 343–358","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"999d622ad7bb68ba"}},{"id":"qx-c2-041","clusterId":"C","werkstueckRef":"C.5.2","stufe":3,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir ein unscharfes Nachtvideo eines leuchtenden Punkts, der sich am Himmel zu bewegen scheint, und sagt: „Ich kann mir nicht erklären, was das ist – also muss es außerirdisch sein.“","options":["Der Schluss dreht sich im Kreis: Das Video gilt als Beweis für Außerirdische, und die Außerirdischen gelten wiederum als Beweis dafür, dass das Video echt ist.","Der Schluss deutet in einen Punkt zu viel hinein: Er wird als Gesicht oder Gestalt gelesen, obwohl das Bild gar nichts Erkennbares zeigen kann.","Der Schluss überschätzt die Häufigkeit solcher Ereignisse: Wer gerade eine Dokumentation über Ufos gesehen hat, hält echte Sichtungen für alltäglicher, als sie sind.","Der Schluss macht aus einer Erklärungslücke einen Beleg: Aus „ich kann es nicht erklären“ wird „außerirdisch“, obwohl naheliegendere Erklärungen gar nicht geprüft wurden."],"correctIndex":3,"explanation":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen aus, nicht über das Objekt. Bei unscharfen Nachtaufnahmen gibt es viele alltägliche Erklärungen: Flugzeuge, Satelliten wie Starlink, Ballons oder Drohnen werden ohne Referenzobjekte leicht falsch eingeschätzt, Linsenreflexionen (Lens Flares) wirken wie eigenständige Lichter, und Luftturbulenzen lassen Lichtpunkte flackern oder wandern. Solange diese Möglichkeiten nicht ausgeschlossen sind, trägt der Sprung zur aufregendsten Erklärung nicht. Eine passende Prüffrage lautet: Welche bekannten Gesetze der Optik, der Perspektive oder der Kameratechnik könnten das Gesehene ebenfalls vollständig erklären?","coreRule":"⚡ Eine Erklärungslücke ist kein Beleg für die aufregendste Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei der Ufologie; Red Flags)","status":"entwurf","kurz":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen, nicht über das Objekt. Bei unscharfen Nachtaufnahmen kommen viele alltägliche Erklärungen infrage; solange sie nicht ausgeschlossen sind, trägt der Sprung zur spektakulärsten nicht.","prueffrage":"Was müsste man über Ort, Uhrzeit und Blickrichtung der Aufnahme wissen, um den Lichtpunkt bestimmen zu können?","rueckmeldung":[{"option":0,"text":"Ein Zirkelschluss setzt voraus, was er beweisen will, etwa wenn Video und Außerirdische sich gegenseitig stützen. Hier wird aber nur von „unerklärlich“ auf „außerirdisch“ gesprungen, also von einer Lücke zu einer Erklärung, nicht im Kreis."},{"option":1,"text":"Bei so wenig Bildinformation wird tatsächlich schnell etwas hineingedeutet. Hier ist aber von einem leuchtenden Punkt die Rede, nicht von einer erkannten Gestalt. Der Fehler liegt im Schluss von „unerklärt“ auf „außerirdisch“."},{"option":2,"text":"Medien können beeinflussen, wie häufig uns etwas erscheint. Davon ist hier aber keine Rede: Der Schluss stützt sich nicht auf eine Häufigkeitseinschätzung, sondern auf die eigene Ratlosigkeit."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Office of the Director of National Intelligence (2021): Preliminary Assessment: Unidentified Aerial Phenomena","oeffentlich":true,"url":"https://archive.dni.gov/files/ODNI/documents/assessments/Prelimary-Assessment-UAP-20210625.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"455238f8111a1b04"}},{"id":"qx-c2-042","clusterId":"C","werkstueckRef":"C.5.2","stufe":4,"question":"Welcher Einwand trifft den Schluss von Herrn K. am besten?","options":["Er geht von geradliniger Lichtausbreitung aus. Temperaturschichten, Wasserdampf und Turbulenzen brechen das Licht aber, sodass Objekte am Horizont höher erscheinen können, als sie tatsächlich sind.","Er sucht nur nach Beobachtungen, die zu seiner Überzeugung passen, und blendet alles andere aus. Dieser Bestätigungsfehler lässt ihn jede Sichtung als Beweis für seine Ansicht lesen.","Er bekämpft einen Strohmann: Er widerlegt die überzogene Behauptung, hinter dem Horizont sei nie etwas zu sehen, statt die eigentliche Aussage über die Erdkrümmung zu prüfen.","Er stützt sich auf die Autorität einer Fachperson, ohne deren Aussage zu prüfen. Ein bloßes Autoritätsargument ersetzt aber keine eigene Messung der Sichtweite am Horizont."],"correctIndex":0,"explanation":"Sein Schluss hängt an einer stillschweigenden Annahme: dass Licht in der Luft schnurgerade verläuft. Tatsächlich brechen Temperaturschichten, Wasserdampf und Turbulenzen das Licht; schon bei gewöhnlicher Schichtung lässt diese Brechung (Refraktion) Objekte am Horizont etwas höher erscheinen und gleicht die Krümmung teilweise aus, und liegt warme Luft über kaltem Wasser, kann sie sogar Teile sichtbar machen, die nach geradliniger Rechnung ganz verdeckt wären. Das Flimmern und die Verschiebung in seiner Beobachtung passen zu solchen Verzerrungen, ähnlich wie bei einer Fata Morgana. Wer aus „Ich sehe mehr, als meine Rechnung erlaubt“ schließt, die Erde sei nicht gekrümmt, prüft also die eigene Rechnung nicht, die die Brechung außer Acht lässt. Die anderen Einwände nennen bekannte Denkfehler, die hier aber nicht vorliegen: Herr K. hat gerade nachgerechnet und nichts ausgeblendet, sodass kein Bestätigungsfehler im Spiel ist. Er greift auch keine überzogene Gegenposition an, sondern zieht eine eigene Folgerung. Und eine Fachperson, auf deren Autorität er sich stützt, kommt im Szenario gar nicht vor.","coreRule":"⚡ Wer weit sieht, muss die Brechung der Luft mitrechnen: Eine Beobachtung widerlegt eine Theorie erst, wenn alle bekannten Störeinflüsse in der Rechnung berücksichtigt sind.","beleg":"Werkstück C.5.2 (Kontext & Tiefe, Atmosphärische Verzerrung; Anwendung & Relevanz, Bei der Flache-Erde-Theorie)","status":"entwurf","scenario":"Herr K. steht an einem klaren Tag an einer Küste und sieht ein Hochhaus, das 40 Kilometer entfernt am Horizont liegt. Er hat grob nachgerechnet: Bei einer gekrümmten Erde müsste der untere Teil des Gebäudes hinter dem Horizont verborgen sein. Er sieht aber mehr davon, als seine Rechnung erlaubt, wenn auch etwas flimmernd und leicht verschoben. Er schließt: „Die Erde ist nicht gekrümmt, sonst könnte ich das sehen.“","quote":"","quoteLabel":"","kurz":"Seine Rechnung nimmt geradliniges Licht an, doch Temperaturschichten und Wasserdampf brechen es und lassen Fernes höher erscheinen. Der Fehler: Er prüft nicht, ob die Annahme hinter seiner Rechnung stimmt, und schließt aus der Abweichung gleich auf die Krümmung.","prueffrage":"Wie hoch steht Herr K. über dem Wasser, und wie viele Meter des Gebäudes müssten nach seiner Rechnung verdeckt sein?","rueckmeldung":[{"option":1,"text":"Einseitige Auswahl von Belegen ist ein verbreiteter Fehler, hier aber nicht erkennbar: Herr K. hat nachgerechnet und nichts ausgeblendet. Seine Schwäche liegt in der Rechnung selbst, die eine ungeprüfte Annahme über das Licht enthält."},{"option":2,"text":"Ein Strohmann verzerrt die Aussage einer Gegenseite, doch im Szenario gibt es keine Gegenseite. Herr K. zieht aus seiner eigenen Beobachtung eine Folgerung, und sie ist wegen einer unbemerkten Annahme brüchig."},{"option":3,"text":"Ein Autoritätsargument bräuchte eine Fachperson, auf die sich Herr K. beruft. Im Szenario stützt er sich aber auf eigene Beobachtung und Rechnung, und genau diese Rechnung lässt die Lichtbrechung außer Acht."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Georgia State University, HyperPhysics: Atmospheric Refraction","oeffentlich":true,"url":"https://hyperphysics.gsu.edu/hbase/atmos/mirage.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Young, A. T. (San Diego State University): Looming, Towering, Stooping, and Sinking","oeffentlich":true,"url":"https://aty.sdsu.edu/mirages/mirsims/loom/loom.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ed17c1872a951c0f"}},{"id":"qx-c2-043","clusterId":"C","werkstueckRef":"C.5.3","stufe":1,"question":"Ein Bekannter zeigt dir ein Foto eines langen Streifens hinter einem Flugzeug und sagt: „Das sind Chemikalien, die da versprüht werden. Aus Kerosin entsteht ja nichts, was einen weißen Streifen bilden könnte.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man fragt, was bei der Verbrennung von Kerosin entsteht: Kohlendioxid und heißer Wasserdampf, der in der eiskalten Höhenluft zu Eiskristallen gefriert, wie unser Atem an einem Wintertag.","Man fragt, wer von der Behauptung profitiert: Wer ein Interesse an einer Aussage hat, stellt sie womöglich verzerrt dar, und diese Motive sollte man vor jeder Bewertung klären.","Man fragt, ob auch andere Flugzeuge solche Streifen hinterlassen: Nur was sich an vielen Flügen wiederholt, lässt sich von einem Zufallsbefund unterscheiden, und erst dann wird die Behauptung prüfbar.","Man fragt, ob das Foto bearbeitet wurde: Ein verfälschtes Bild wäre wertlos, und erst ein echtes Foto am Himmel erlaubt überhaupt Aussagen über die Zusammensetzung eines Streifens."],"correctIndex":0,"explanation":"Wie in unserem Atem entstehen bei der Verbrennung vor allem Kohlendioxid und Wasser. In etwa zehn Kilometern Höhe ist es oft kälter als −40 °C: Der heiße Wasserdampf kondensiert zu winzigen Tröpfchen, die rasch zu Eiskristallen gefrieren. Die Behauptung „aus Kerosin entsteht nichts Sichtbares“ ist damit widerlegt, ganz ohne Zusatzstoffe. Rußpartikel aus dem Triebwerk können als Kondensationskerne dienen, nötig sind sie aber nicht, denn die Luft enthält ohnehin genug Partikel. Eine gute Prüffrage fragt nach der einfachsten Erklärung, die schon bekannte Zutaten und Bedingungen nutzt, bevor man ein geheimes Programm annimmt. Die anderen Überlegungen sind in anderer Lage sinnvoll, klären hier aber nichts: Das Motiv des Sprechers sagt nichts über die Chemie des Abgases. Dass auch andere Flugzeuge Streifen hinterlassen, erklärt nicht, woraus diese bestehen. Und ob das Foto echt ist, ändert nichts an der Frage, was aus Kerosin entstehen kann.","coreRule":"⚡ Bevor du einen Zusatzstoff annimmst: Prüfe, ob die bekannten Zutaten und Bedingungen das Phänomen schon erklären.","beleg":"Werkstück C.5.3 (Kontext & Tiefe: Die Zutaten, Die Bedingungen)","status":"entwurf","scenario":"Ein Flugzeug fliegt in etwa zehn Kilometern Höhe, wo es oft kälter als −40 °C ist. Hinter ihm bleibt ein weißer Streifen zurück.","kurz":"Aus der Verbrennung von Kerosin entstehen Kohlendioxid und heißer Wasserdampf, der bei unter −40 °C zu Eiskristallen gefriert, wie dein Atem im Winter. Der Streifen braucht also keine Zusatzstoffe, schon die einfachste Erklärung genügt.","prueffrage":"Welche Stoffe und welche Bedingungen sind in dieser Höhe ohnehin vorhanden, und reichen sie für den Streifen schon aus?","rueckmeldung":[{"option":1,"text":"Wer etwas sagt und warum, ist bei vielen Aussagen aufschlussreich. Hier aber geht es um Abgas und Höhenluft, und diese Chemie ist unabhängig davon, wer sie behauptet. Ein Motiv macht eine Aussage nicht wahr oder falsch."},{"option":2,"text":"Ein Muster über viele Flüge hilft, Zufälle auszuschließen. Es zeigt aber nur, dass Streifen häufig sind, nicht woraus sie bestehen. Die Frage nach der Zusammensetzung bleibt damit unbeantwortet."},{"option":3,"text":"Ein bearbeitetes Foto wäre tatsächlich wertlos, deshalb wirkt die Prüfung gründlich. Hier ist aber nicht das Bild strittig, sondern der Schluss daraus: Auch ein echtes Foto sagt nichts darüber, was aus Kerosin entstehen kann."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schumann, U. (1996): On conditions for contrail formation from aircraft exhausts. Meteorologische Zeitschrift 5(1), 4–23 (doi 10.1127/metz/5/1996/4)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"955a6c73618bfc1c"}},{"id":"qx-c2-044","clusterId":"C","werkstueckRef":"C.5.3","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir eine Regenwasserprobe, in der Aluminium und Barium nachgewiesen wurden: „Das ist der Beweis für Sprühaktionen.“","options":["Der Schluss ist fehlerhaft, weil er aus einem zeitlichen Nacheinander auf eine Ursache schließt; was nach einem Überflug im Regen auftaucht, muss nicht von ihm stammen.","Der Schluss ist fehlerhaft, weil er sich auf Autorität statt auf Messwerte stützt; ein Hinweis auf bekannte Namen ersetzt keine Analyse der Probe.","Der Schluss ist fehlerhaft, weil ein Nachweis allein nichts zeigt; beide Elemente kommen überall in der Erdkruste vor und sind auch ohne Sprühaktionen zu erwarten.","Der Schluss ist fehlerhaft, weil er einen Strohmann aufbaut; er widerlegt eine überzogene Version der Gegenposition statt ihrer tatsächlichen Aussage."],"correctIndex":2,"explanation":"Ein Messwert sagt erst etwas, wenn man ihn mit dem Wert vergleicht, der ohnehin zu erwarten ist. Aluminium und Barium kommen überall in der Erdkruste vor und gelangen etwa mit Staub ins Regenwasser; ihr Nachweis passt deshalb auch ohne Sprühaktionen und spricht nicht für sie. Entscheidend wäre, ob die Mengen deutlich über dem üblichen Gehalt liegen, und daran ändern auch weitere Proben mit bloßem Nachweis nichts. Das stützt auch ein Befund aus der Fachwelt: Shearer u. a. (2016) befragten 77 Fachleute für Kondensstreifen und Staubablagerung; 76 hatten nie einen Beleg für ein geheimes Sprühprogramm gesehen und erklärten die ihnen vorgelegten Messwerte mit gewöhnlichen Ursachen. Ein zeitliches Nacheinander, das man mit einer Ursache verwechseln könnte, wird im Szenario nicht behauptet. Der Schluss beruft sich auch nicht auf eine Autorität, sondern auf einen Messwert, dessen Erwartungswert nicht geprüft wurde. Und eine Gegenposition wird nicht verzerrt wiedergegeben, denn niemand wird hier widerlegt.","coreRule":"⚡ Ein Messwert ohne den Vergleich mit dem natürlichen Gehalt beweist nichts.","beleg":"Werkstück C.5.3 (Red Flags); Fn. gl-c-shearer (Shearer u. a. 2016, Environ. Res. Lett. 11(8), Art. 084011)","status":"entwurf","kurz":"Ein Nachweis sagt nur etwas, wenn man ihn mit dem ohnehin zu erwartenden Wert vergleicht. Aluminium und Barium kommen in der Erdkruste überall vor und gelangen etwa mit Staub ins Regenwasser, der Nachweis spricht also nicht für Sprühaktionen.","prueffrage":"Wie viel Aluminium und Barium enthielt die Probe genau, und mit welchem Wert wurde das verglichen?","rueckmeldung":[{"option":0,"text":"Dass etwas im Regen auftaucht, muss nicht von einem Überflug stammen. Hier ist aber von keinem Überflug und keiner zeitlichen Abfolge die Rede; der Mangel liegt darin, dass der gemessene Wert nicht mit dem üblichen verglichen wird."},{"option":1,"text":"Bekannte Namen ersetzen keine Analyse, das stimmt. Hier beruft sich die Person aber auf keine Autorität, sondern auf einen Messwert, dessen zu erwartende Höhe schlicht nicht geprüft wurde."},{"option":3,"text":"Ein Strohmann setzt voraus, dass eine Gegenposition verzerrt wiedergegeben und dann widerlegt wird. Hier wird niemand widerlegt; es wird eine eigene Behauptung mit einem Messwert gestützt, der ohne Vergleichswert nichts zeigt."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program. Environmental Research Letters 11(8), 084011","oeffentlich":true,"doi":"10.1088/1748-9326/11/8/084011","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a87943da00b5a3b9"}},{"id":"qx-c2-045","clusterId":"C","werkstueckRef":"C.5.3","stufe":3,"question":"Sie sagt: „Kondensstreifen sind harmlos: Wer sich um Flugverkehr und Klima sorgt, soll auf das CO₂ achten. Die Wolken aus Wasser und Eis am Himmel sind nur Wetter und wirken sich nicht aufs Klima aus.“ Welche Antwort ist am besten begründet?","options":["„Ungiftig“ heißt nicht „folgenlos“: Die Schleierwolken aus Kondensstreifen zählen zu den größten Erwärmungsbeiträgen des Luftverkehrs.","„Ungiftig“ heißt auch „folgenlos“: Wolken aus reinem Wasser und Eis können die Temperatur nicht verändern, weil sie keine Energie aufnehmen oder abgeben.","„Ungiftig“ heißt nicht „folgenlos“, aber die Wirkung ist kühlend: Die Schleierwolken aus Kondensstreifen werfen Sonnenlicht zurück, die Erwärmung geht allein vom CO₂ aus.","„Ungiftig“ heißt nicht „folgenlos“, aber der Grund ist ein anderer: Die Schleierwolken aus Kondensstreifen belasten das Klima durch ihre Giftstoffe, auch wenn Messungen das bisher nicht zeigen."],"correctIndex":0,"explanation":"Die Freundin schließt von „ungiftig“ auf „folgenlos“ – das ist ein Fehlschluss, denn Harmlosigkeit für die Gesundheit sagt nichts über die Wirkung auf die Strahlungsbilanz. Langlebige Kondensstreifen gehen in Schleierbewölkung über und beeinflussen, wie viel Wärme die Atmosphäre hält. Nach einer großen Bilanz (Lee u. a. 2021) ist diese Schleierbewölkung nach bestem Schätzwert der größte einzelne Erwärmungsbeitrag des Luftverkehrs, noch vor dessen CO₂: Für 2018 entfielen davon rund 57 mW/m² auf Kondensstreifen-Zirren und 34 auf CO₂. Der Wert für die Zirren ist allerdings deutlich unsicherer als der für CO₂.","coreRule":"⚡ „Kein Gift“ heißt nicht „keine Wirkung“: Prüfe, welche Eigenschaft einer Sache für die Frage zählt.","beleg":"Werkstück C.5.3 (Der Kipppunkt); Fn. gl-c-lee (Lee u. a. 2021, Atmos. Environ. 244, Art. 117834)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über Flugzeuge. Sie hat gerade gelernt, dass Kondensstreifen aus Wasserdampf und Eiskristallen bestehen und kein Gift enthalten.","kurz":"Dass Wolken aus Wasser und Eis ungiftig sind, sagt nichts über ihre Klimawirkung. Langlebige Kondensstreifen werden zu Schleierwolken, die Wärme zurückhalten, und gelten nach einer großen Bilanz sogar als größter Erwärmungsbeitrag des Luftverkehrs.","prueffrage":"Worauf bezieht sich „harmlos“ in ihrem Satz: auf die Gesundheit oder auf die Wärmebilanz der Atmosphäre?","rueckmeldung":[{"option":1,"text":"Dass Wasser und Eis ungiftig sind, stimmt, und so wirkt der Schluss plausibel. Wolken beeinflussen aber die Strahlung: Sie reflektieren Sonnenlicht und halten Wärmestrahlung zurück. Wie giftig etwas ist, sagt nichts über die Klimawirkung."},{"option":2,"text":"Daran stimmt: Wolken werfen auch Sonnenlicht zurück, und das kühlt. Bei langlebigen Kondensstreifen überwiegt im Mittel aber die zurückgehaltene Wärme; nach bestem Schätzwert einer großen Bilanz wärmen sie sogar stärker als das CO₂ des Luftverkehrs."},{"option":3,"text":"Richtig ist: Ungiftig heißt nicht folgenlos. Die Begründung trägt aber nicht, denn Kondensstreifen bestehen aus Wasser und Eis, und ihre Klimawirkung kommt aus der Wärmerückhaltung der Eiskristalle. Giftstoffe spielen dabei keine Rolle."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lee, D. S. u. a. (2021): The contribution of global aviation to anthropogenic climate forcing for 2000 to 2018. Atmospheric Environment 244, 117834","oeffentlich":true,"doi":"10.1016/j.atmosenv.2020.117834","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7468346/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad41281d66c71d28"}},{"id":"qx-c2-046","clusterId":"C","werkstueckRef":"C.5.3","stufe":4,"question":"Was ist an diesem Einwand verkürzt und trägt den Schluss deshalb nicht?","scenario":"In einer Diskussion über Streifen am Himmel sagt jemand: „Wolken werden doch seit Jahren mit Chemikalien besprüht, das nennt man Cloud Seeding! Also stimmt die Sprühtheorie.“","options":["Der Einwand ist verkürzt: Er greift Zweifler persönlich an, statt auf ihre Gründe einzugehen, und ein Angriff auf Personen widerlegt keine Sachaussage.","Der Einwand ist verkürzt: Dass es Wolkenimpfung gibt, stimmt, doch sie wirkt nur örtlich und begrenzt, und daraus folgt kein Sprühprogramm hinter Kondensstreifen.","Der Einwand ist verkürzt: Er verlangt von anderen den Beweis, dass es keine Sprühaktionen gibt; wer etwas behauptet, muss es selbst belegen, statt Gegenbeweise zu fordern.","Der Einwand ist verkürzt: Er stützt sich auf Fachleute, die das Sprühprogramm bestätigt haben sollen, doch deren Aussagen werden nirgends belegt."],"correctIndex":1,"explanation":"Cloud Seeding gibt es wirklich: Dabei werden Stoffe wie Silberiodid gezielt in Wolken eingebracht, um Regen oder Schnee anzuregen. Manche Länder setzen es regelmäßig ein, doch es wirkt nur örtlich, und sein Effekt ist begrenzt und oft schwer nachzuweisen. Der Einwand verwechselt damit zwei verschiedene Dinge: Dass ein bekanntes, örtlich begrenztes Verfahren existiert, sagt nichts darüber, was die langen Streifen hinter Flugzeugen sind. Dafür reicht die Physik: Heißer, feuchter Abgasdampf aus dem Triebwerk gefriert in der eiskalten Höhenluft zu Eiskristallen, und ob der Streifen kurz oder lange bleibt, hängt von der Feuchte der Umgebungsluft ab. Aus der Existenz eines realen, lokalen Verfahrens folgt kein globales Geheimprogramm. Ein persönlicher Angriff kommt im Einwand nicht vor, es wird niemand herabgesetzt. Eine Beweislast wird nicht umgekehrt, denn der Einwand fordert von niemandem einen Gegenbeweis. Und auf Fachleute beruft er sich nicht, sondern auf ein reales Verfahren.","coreRule":"⚡ Ein reales, lokales Verfahren belegt kein globales Geheimprogramm.","beleg":"Werkstück C.5.3 (Verbindungen; Kontext & Tiefe)","status":"entwurf","kurz":"Cloud Seeding gibt es wirklich, wirkt aber nur örtlich und begrenzt. Dass dieses Verfahren existiert, sagt nichts darüber, was die langen Streifen hinter Flugzeugen sind; erklärbar sind sie durch gefrierenden Abgasdampf in der Höhenluft.","prueffrage":"Hinter welchen Flugzeugen entstehen die Streifen, und bei welchem Wetter bleiben sie lange am Himmel stehen?","rueckmeldung":[{"option":0,"text":"Ein persönlicher Angriff widerlegt tatsächlich keine Sachaussage. Hier wird aber niemand herabgesetzt: Der Satz stellt eine Sachbehauptung auf. Verkürzt ist seine Gleichsetzung von Cloud Seeding mit den Streifen am Himmel."},{"option":2,"text":"Dass, wer etwas behauptet, es auch belegen muss, gilt allgemein. Der Einwand fordert aber von niemandem einen Gegenbeweis. Seine Schwäche liegt darin, dass ein reales Verfahren ohne Beleg mit den Streifen am Himmel gleichgesetzt wird."},{"option":3,"text":"Eine Berufung auf unbelegte Fachleute wäre tatsächlich schwach. Im Einwand kommt sie aber nicht vor: Er nennt ein reales Verfahren, kein Expertenurteil. Die Lücke liegt zwischen Cloud Seeding und den Streifen am Himmel."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"World Meteorological Organization: WMO Statement on Weather Modification","oeffentlich":true,"url":"https://wmo.int/content/wmo-statement-weather-modification","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4f78993692068e95"}},{"id":"qx-c2-047","clusterId":"C","werkstueckRef":"C.5.4","stufe":1,"question":"Der Bekannte sagt: „Dafür muss jedes Stockwerk einzeln gesprengt worden sein.“ Welche Überlegung zeigt am besten, was an diesem Schluss nicht trägt?","options":["Ein Gebäude trägt ein Mehrfaches seiner Last, weil Bauvorschriften Sicherheitsreserven verlangen; solche Reserven machen einen Einsturz ohne Fremdeinwirkung selten.","Ein aufprallender Block trägt weit mehr Energie, als das Element darunter aushält; so kann schon der Ausfall einer einzigen Stelle die ganze Kette auslösen.","Ein Verschwörungsglaube lässt sich kaum widerlegen, weil jeder Gegenbeleg als Teil des Plans gedeutet wird; seine Behauptung lässt sich deshalb nicht überprüfen.","Ein Zeitablauf von wenigen Sekunden lässt sich aus Aufnahmen nicht verlässlich ablesen, weil Perspektive und Bildrate die Dauer verfälschen können; die Angabe bleibt unsicher."],"correctIndex":1,"explanation":"Der Schluss „schnell und vollständig, also gesprengt“ übersieht eine einfachere Erklärung. Fällt ein Gebäudeteil auf die Struktur darunter, wird seine Lageenergie zu Bewegungsenergie, und beim Aufprall können Kräfte wirken, die ein Vielfaches der ruhenden Last betragen, für die das nächste Element ausgelegt ist. Übersteigt diese Belastung seine Tragreserve, versagt es, und der Block stürzt samt Trümmern mit noch mehr Masse weiter auf das nächste Element. So kann das Versagen an einer Stelle genügen, damit die Struktur nacheinander nachgibt, schnell und ohne weitere Eingriffe. Eine Sprengung ist dafür nicht nötig: Die vorhandene Physik erklärt das Ergebnis bereits (Ockhams Rasiermesser). Dass Gebäude Sicherheitsreserven haben, erklärt nicht, was geschieht, wenn eine solche Reserve überschritten wird. Dass sich ein Verschwörungsglaube schwer widerlegen lässt, sagt nichts über die Physik des Einsturzes. Und die Dauer von wenigen Sekunden steht im Szenario als gegeben fest.","coreRule":"⚡ Ein geschwächtes Element kann eine Kettenreaktion auslösen, die niemand mehr bremst: Tempo und Vollständigkeit eines Einsturzes sind noch kein Beleg für eine Sprengung.","beleg":"Werkstück C.5.4 (Der Stapel Bücher; Kernidee)","status":"entwurf","scenario":"Ein Bekannter sieht die Bilder vom Einsturz eines Hochhauses nach einem Brand. Der Einsturz dauerte nur wenige Sekunden und erfasste das ganze Gebäude, obwohl nur einige Stockwerke gebrannt hatten.","kurz":"Schnell und vollständig ist kein Beleg für eine Sprengung: Fällt ein Block auf die Struktur darunter, kann der Aufprall deren Tragreserve übersteigen, und die Kette setzt sich fort. Die Fehlschlussstelle ist, eine einfachere Erklärung zu übergehen.","prueffrage":"Wo begann der Einsturz auf den Bildern: in Höhe der brennenden Stockwerke oder an vielen Stellen zugleich?","rueckmeldung":[{"option":0,"text":"Sicherheitsreserven machen einen Einsturz ohne Fremdeinwirkung tatsächlich selten. Sie gelten aber für die ruhende Last und sagen nicht, was geschieht, wenn ein herabstürzender Block sie durch den Aufprall überschreitet."},{"option":2,"text":"Dass sich ein Verschwörungsglaube schwer widerlegen lässt, stimmt oft. Es sagt aber nichts darüber, ob ein Einsturz physikalisch auch ohne Sprengung ablaufen kann, und genau das müsste der Schluss des Bekannten entkräften."},{"option":3,"text":"Aufnahmen können Zeitangaben verfälschen, das kommt vor. Hier steht die Dauer von wenigen Sekunden aber als gegeben fest, und selbst eine andere Dauer würde nicht erklären, warum ein Versagen an einer Stelle zur Sprengung führen müsste."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"75569bb8234f93b1"}},{"id":"qx-c2-048","clusterId":"C","werkstueckRef":"C.5.4","stufe":2,"question":"Jemand sagt: „Das Hochhaus wurde von keinem Flugzeug getroffen und ist trotzdem komplett eingestürzt. Das kann nur eine Sprengung gewesen sein.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man prüft, ob Feuer allein genügt: Stundenlange Brände können Stahlträger ausdehnen und schwächen, bis eine kritische Stütze ihren Halt verliert und eine Einsturzkaskade auslöst. Ein Flugzeugeinschlag ist dafür nicht nötig.","Man prüft, ob sich die Behauptung überhaupt widerlegen ließe: Eine Aussage, die jeden Gegenbefund als Teil der Verschwörung umdeutet, taugt als Erklärung nicht, ganz gleich, wie plausibel sie wirkt.","Man prüft, wer vom Einsturz profitiert hätte: Wer ein Motiv für eine Tat hatte, ist verdächtig, und daraus lässt sich ableiten, ob eine Sprengung wahrscheinlicher ist als ein Brandschaden.","Man prüft, ob die Person selbst vom Fach ist: Nur wer Statik studiert hat, kann beurteilen, was ein Gebäude aushält, und deshalb entscheidet ihre Ausbildung über die Aussage."],"correctIndex":0,"explanation":"Die Behauptung tut so, als gäbe es nur Flugzeugeinschlag oder Sprengung. Stahl muss nicht schmelzen, um zu versagen: Bei 600 bis 800 °C verliert er über die Hälfte seiner Tragfähigkeit, und schon bei geringeren Temperaturen dehnt er sich deutlich aus. Nach der Untersuchung des NIST schoben sich ausdehnende Deckenträger einen Unterzug von seinem Auflager an einer tragenden Stütze; Decken brachen ein, die Stütze verlor ihre seitliche Halterung, knickte aus, und das Versagen pflanzte sich durch die Struktur fort. Weil die Sprinkler trocken blieben, wirkten die Brände stundenlang ungehindert; die Trümmerschäden spielten nach NIST für den Einsturz selbst kaum eine Rolle. Diese schon vorhandene Ursache erklärt den Einsturz ohne zusätzliche Sprengung. Nach NIST war es der erste bekannte Totaleinsturz eines Hochhauses vor allem durch Feuer, doch ungewöhnlich ist nicht dasselbe wie unerklärbar. Andere Prüfungen sind in anderer Lage nützlich, klären hier aber nichts: Ob die Behauptung widerlegbar ist, ist nachrangig, denn sie lässt sich anhand der Untersuchungsbefunde durchaus prüfen. Das Motiv möglicher Täter sagt nichts darüber, ob Feuer einen Stahlbau zum Einsturz bringen kann. Und die Ausbildung einer Person entscheidet nicht darüber, ob ihr Schluss trägt.","coreRule":"⚡ Hitze dehnt Stahl, und eine verrutschte Stütze genügt für die Kaskade.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5 WTC 7); Fn. gl-c-nist (NIST NCSTAR 1A, 2008); Fn. gl-c-wtc7-freifall (NIST 2008, S. 45 und 48)","status":"entwurf","scenario":"Das Gebäude stand in der Nähe zweier Türme, die kurz zuvor eingestürzt waren. Es wurde von herabfallenden Trümmern getroffen, danach brannte es viele Stunden lang auf mehreren Etagen unkontrolliert. Die Sprinkler der unteren Stockwerke blieben trocken, weil die einstürzenden Türme die städtische Wasserleitung beschädigt hatten.","kurz":"Die Behauptung stellt nur Flugzeugeinschlag oder Sprengung zur Wahl, doch Stundenlanges Feuer ohne Löschwasser kann Stahl so schwächen und dehnen, dass die Struktur versagt. Dass der Einsturz ungewöhnlich war, heißt nicht, dass er unerklärbar ist.","prueffrage":"Welche Schäden hatte das Gebäude schon vor dem Einsturz, und welche davon wurden behoben, welche nicht?","rueckmeldung":[{"option":1,"text":"Widerlegbarkeit ist ein gutes Kriterium, wenn eine Aussage jeden Einwand wegerklärt. Hier lässt sich die Behauptung aber an den Untersuchungsbefunden prüfen, und genau das klärt, ob eine Sprengung nötig war."},{"option":2,"text":"Ein Motiv kann Ermittlungen lenken, wirkt deshalb aber auch aussagekräftig. Es sagt jedoch nichts darüber, was Feuer mit einem Stahlbau anrichten kann, und genau das ist hier die Frage."},{"option":3,"text":"Fachwissen kann beim Beurteilen von Statik helfen. Ob ein Schluss trägt, hängt aber nicht an der Ausbildung der Person, sondern daran, ob die Gründe und Belege ihn stützen, und die lassen sich prüfen."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation (Festigkeitsverlust von Stahl)","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e3826ed63bb11655"}},{"id":"qx-c2-049","clusterId":"C","werkstueckRef":"C.5.4","stufe":3,"question":"Jemand sagt: „Das Dach von WTC 7 ist beim Einsturz im freien Fall gefallen. Das geht nur mit Sprengstoff, weil sonst jedes Stockwerk Widerstand geleistet hätte.“ Welche Prüfung klärt, ob das den Schluss auf eine Sprengung trägt?","options":["Du prüfst, ob der Freifall den ganzen Einsturz betraf oder nur einen Teilabschnitt, und ob dieser Abschnitt auch ohne Sprengstoff erklärbar ist.","Du prüfst, ob das Video unbearbeitet ist, weil nur ungeschnittenes Material eine verlässliche Aussage über den Ablauf des Einsturzes erlaubt.","Du prüfst, wem eine Sprengungsthese nützen würde, weil das Motiv der Person verrät, ob ihre Aussage über den Einsturz zutrifft.","Du prüfst, ob die Person den Einsturz selbst miterlebt hat, weil nur Augenzeugen beurteilen können, ob die Stützen vorher gesprengt wurden."],"correctIndex":0,"explanation":"Der Schluss „Freifall, also Sprengung“ setzt voraus, dass der Freifall den ganzen Einsturz betraf und nur durch Sprengstoff möglich ist. Beides lässt sich prüfen. Gemessen wurde: Die Dachlinie brauchte für 18 Stockwerke rund 5,4 Sekunden, im freien Fall wären es 3,9 Sekunden gewesen, also rund 40 Prozent länger. Nur die Nordfassade fiel etwa 2,25 Sekunden lang über rund acht Stockwerke mit Erdbeschleunigung. In dieser Phase trugen die zuvor ausgeknickten Außenstützen sie praktisch nicht mehr, es gab also kaum Widerstand. Ein kurzer Freifall-Abschnitt folgt damit schon aus einem Einsturz durch Feuer und beweist keinen Sprengstoff. Wer den Teilabschnitt zum ganzen Einsturz verallgemeinert und die einfachere Erklärung nicht prüft, schließt zu weit. Die anderen Schritte sind in anderer Lage sinnvoll, klären hier aber nichts: Ein unbearbeitetes Video sagt noch nichts darüber, was der Freifall bedeutet. Das Motiv der Person verrät nichts über den Ablauf des Einsturzes. Und ob jemand dabei war, entscheidet nicht darüber, ob aus einem Freifall-Abschnitt auf Sprengstoff geschlossen werden darf.","coreRule":"⚡ Ein kurzer Freifall-Abschnitt ist kein Fingerabdruck für Sprengstoff: Prüfe, wie lange und woran er galt, bevor du auf die Ursache schließt.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5); Fn. gl-c-wtc7-freifall (NIST 2008, NCSTAR 1A, S. 45 und 48)","status":"entwurf","scenario":"In einer Diskussion über den Einsturz von WTC 7 wird ein Videoclip gezeigt, in dem das Gebäude in wenigen Sekunden in sich zusammenfällt. Die Person behauptet, jeder Fall mit Erdbeschleunigung beweise, dass die Stützen vorher gezielt gesprengt wurden.","kurz":"Der Schluss trägt nur, wenn der Freifall den ganzen Einsturz betraf und nur Sprengstoff ihn erklärt. Gemessen fiel aber nur ein Teilstück frei, nachdem ausgeknickte Stützen kaum noch Widerstand boten, und das folgt auch aus einem Einsturz durch Feuer.","prueffrage":"Wie lange dauerte der Einsturz der Dachlinie von WTC 7 laut Messung, und wie lange hätte ein freier Fall aus derselben Höhe gedauert?","rueckmeldung":[{"option":1,"text":"Ein geschnittenes Video wäre tatsächlich ein Problem für jede Aussage über den Ablauf. Aber selbst ein unbearbeitetes Video sagt nicht, was ein Freifall bedeutet. Es liefert nur die Messdaten, aus denen sich der Schluss erst prüfen lässt."},{"option":2,"text":"Wem eine These nützt, wirkt wie ein Hinweis, ob sie stimmt. Das Motiv verrät aber nichts darüber, wie das Gebäude eingestürzt ist. Ob der Schluss „Freifall, also Sprengung“ trägt, zeigen nur die Daten zum Einsturz selbst."},{"option":3,"text":"Wer dabei war, kennt vielleicht Eindrücke und Geräusche. Ob aus einem Freifall-Abschnitt auf Sprengstoff geschlossen werden darf, lässt sich aber nicht aus Erlebnissen beantworten. Das entscheidet sich an Messung und Ablauf des Einsturzes."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"doi","kurz":"NIST (2008): Final Report on the Collapse of World Trade Center Building 7 (NCSTAR 1A)","oeffentlich":true,"doi":"10.6028/NIST.NCSTAR.1a","seite":"45, 48"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"97bbe4427172ae84"}},{"id":"qx-c2-050","clusterId":"C","werkstueckRef":"C.5.5","stufe":1,"question":"In einer Doku heißt es: „Die Wikinger in Grönland starben aus, weil sie dekadent und weniger anpassungsfähig waren als die Inuit.“ Du kennst folgende Fakten: Die Siedlungen bestanden fast 500 Jahre, ihre Energiebilanz war von Anfang an knapp, ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer, der Meeresspiegel stieg und überflutete Weideland, das Walrosselfenbein verlor seinen Markt und die Schiffe aus Norwegen blieben aus. Welche Beurteilung wird dem am besten gerecht?","options":["Die Erklärung ist unvollständig: Sie führt das Ende auf Charakter zurück, obwohl mehrere harte Umstände zugleich wirkten.","Die Erklärung lässt sich nicht beurteilen: Ob ein Volk dekadent war, zeigen ohne eigene Aufzeichnungen weder Funde noch Quellen.","Die Erklärung ist widerlegt, weil allein der Verlust des Elfenbeinmarktes das Ende erklärt und kein Charakterzug nötig ist.","Die Erklärung stimmt im Kern: Die Inuit überlebten im selben Land und erwiesen sich damit nachweislich als anpassungsfähiger."],"correctIndex":0,"explanation":"Der Vorwurf der Dekadenz erklärt das Ende durch einen vermuteten Charakterzug, ohne die Umstände zu prüfen. Dabei lagen mehrere harte Faktoren gleichzeitig vor: Von Anfang an war die Energiebilanz knapp, das Vieh allein konnte die Höfe nicht ernähren. Ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer (nach neueren Seesedimenten vor allem trockener; ob auch kälter, ist umstritten), der Meeresspiegel stieg, der Markt für Walrosselfenbein brach weg und die Schiffe blieben aus. Gegen eine Charakterschwäche spricht schon die Dauer: Fast 500 Jahre hielten die Siedlungen durch. Als viele Belastungen zugleich zuschlugen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Dass die Inuit überlebten, beweist keine überlegene Moral: Die Wikinger übernahmen etwa die Eisjagd der Inuit nie, blieben europäische Viehzüchter und waren schließlich verwundbar. Auch lückenhafte Quellen heißen nicht, dass man nichts beurteilen kann: Man kann Erklärungen danach beurteilen, wie gut sie zu den bekannten Fakten passen. Und der Verlust des Elfenbeinmarktes war nur einer von mehreren Faktoren, nicht der einzige.","coreRule":"⚡ Wer ein Scheitern mit einem Charakterfehler erklärt, ohne Umstände wie Energie, Klima und Handel zu prüfen, erklärt zu wenig.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3658–3663); Fn. gl-c-davis (Janes in Hakluyt, Davis' erste Reise 1585)","status":"entwurf","scenario":"","kurz":"Mehrere harte Umstände wirkten zugleich: knappe Energiebilanz, unberechenbares Klima, steigendes Meer, verlorener Elfenbeinmarkt, ausbleibende Schiffe. Der Charakterzug „dekadent“ erklärt das Ende nur, weil man die Umstände gar nicht erst prüft.","prueffrage":"Was müsste man über Menschen wissen, um sie dekadent zu nennen, und welche der bekannten Tatsachen sagen überhaupt etwas über ihr Verhalten?","rueckmeldung":[{"option":1,"text":"Quellen sind tatsächlich lückenhaft, und einen Charakterzug wie Dekadenz kann man kaum belegen. Daraus folgt aber nicht, dass man nichts beurteilen kann: Man kann Erklärungen daran messen, wie gut sie zu den bekannten Fakten passen."},{"option":2,"text":"Der Verlust des Marktes für Walrosselfenbein spielte durchaus eine Rolle. Er war aber nur einer von mehreren Faktoren neben knapper Energiebilanz, Klima, Meeresspiegel und ausbleibenden Schiffen, und er allein erklärt das Ende nicht."},{"option":3,"text":"Dass die Inuit im selben Land überlebten, ist richtig, beweist aber keine überlegene Anpassungsfähigkeit. Die Wikinger blieben europäische Viehzüchter und übernahmen etwa die Eisjagd nie; der Unterschied lag in der Lebensweise, nicht im Charakter."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Zhao, B. u. a. (2022): Prolonged drying trend coincident with the demise of Norse settlement in southern Greenland. Science Advances 8(12), eabm4346","oeffentlich":true,"doi":"10.1126/sciadv.abm4346","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8942370/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Borreggine, M. u. a. (2023): Sea-level rise in Southwest Greenland as a contributor to Viking abandonment. PNAS 120(17), e2209615120","oeffentlich":true,"doi":"10.1073/pnas.2209615120","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10151458/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0b399156719441dc"}},{"id":"qx-c2-051","clusterId":"C","werkstueckRef":"C.5.5","stufe":2,"question":"Wie lässt sich am besten erklären, dass die Wikinger in Grönland nach fast 500 Jahren verschwanden, die Inuit aber überlebten?","options":["Sie passten sich nur teilweise an: Die Winterjagd der Nachbarn übernahmen sie nie, daher fehlten ihnen bei mehreren Belastungen zugleich die Reserven.","Sie gerieten durch Klima und Meeresspiegel an eine Grenze: Gegen solche Veränderungen hilft keine Anpassung, daher war ihr Ende unausweichlich.","Sie waren zu träge für den Wandel: Ihre Gewohnheiten blieben starr, daher spielten Klima, Weiden und Handel für ihr Ende keine entscheidende Rolle.","Sie passten sich zu stark an: Mit dem Umstieg auf die Robbenjagd gaben sie ihre Höfe auf, daher fehlte ihnen das Heu für das Vieh."],"correctIndex":0,"explanation":"Die Siedler waren keine Verlierer durch Dekadenz oder Unfähigkeit. Sie haben sich durchaus angepasst: Sie stellten auf gemeinschaftliche Robbenjagd um, und der Meeresanteil in ihren Knochen stieg im Lauf der Jahrhunderte von rund 40 auf rund 80 Prozent. Zugleich blieben sie Viehzüchter mit Höfen, Ställen und Steinkirchen, und die Eisjagd der Nachbarn, die Robben auch im Winter erreichbar machte, übernahmen sie nie. Ihre Energiebilanz war von Anfang an knapp. Als ab dem späten 13. Jahrhundert Klima, Meeresspiegel und Handel zugleich gegen sie liefen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Die Geografie setzte die Grenzen, aber die Kultur entschied mit, welche Anpassung die Siedler vollzogen und welche nicht. Wer nur die Umwelt oder nur den Charakter als Ursache nimmt, übersieht dieses Zusammenspiel. Die anderen Gedanken klingen zwar vernünftig, passen aber nicht: Klima und Meeresspiegel trafen hart, doch die Nachbarn überlebten unter denselben Bedingungen, also war das Ende nicht unausweichlich. Der Umstieg auf die Robbenjagd widerspricht dem Bild starrer Gewohnheiten. Und ihre Höfe und ihr Vieh haben die Siedler nicht aufgegeben, sie blieben Viehzüchter.","coreRule":"⚡ Die Umwelt setzt die Grenzen, aber die Kultur entscheidet mit, welche Anpassung gelingt.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland; Der Kipppunkt); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3659–3662)","status":"entwurf","scenario":"Eine Siedlergemeinschaft aus Europa lebt rund 500 Jahre in der Arktis. Sie hält Vieh, baut Höfe und Steinkirchen und ist auf Heu angewiesen. Sie stellt auf gemeinschaftliche Robbenjagd um, bleibt dabei aber europäische Viehzüchterin. Als das Klima unberechenbarer wird, Küstenweiden überflutet werden, ihr wichtigstes Handelsgut seinen Markt verliert und die Schiffe ausbleiben, bricht die Siedlung zusammen. Ein Volk, das die Robben auch im Winter an Atemlöchern und Eiskanten jagt, lebt im selben Land weiter.","kurz":"Die Siedler passten sich teilweise an: Sie jagten Robben, blieben aber Viehzüchter und übernahmen die Winterjagd nie. Als Klima, Meeresspiegel und Handel zugleich kippten, fehlten Reserven. Weder Umwelt noch Charakter allein erklärt das Ende.","prueffrage":"Was änderten die Siedler im Lauf der Zeit an ihrer Nahrungssuche, und hielten sie danach weiter Vieh?","rueckmeldung":[{"option":1,"text":"Klima und Meeresspiegel trafen die Siedler tatsächlich hart, und die Küstenweiden gingen verloren. Doch das Volk mit der Winterjagd lebte unter denselben Bedingungen weiter, also war das Ende nicht unausweichlich."},{"option":2,"text":"Starrheit steckt darin: Die Siedler blieben Viehzüchter und übernahmen die Eisjagd nie. Doch sie stellten auch auf Robbenjagd um, und Klima, Weiden und Handel setzten ihnen spürbar zu. Dass sie keine Rolle gespielt hätten, trägt nicht."},{"option":3,"text":"Eine Anpassung gab es wirklich: Die Robbenjagd wurde wichtig. Aber die Siedler gaben ihre Höfe und ihr Vieh nicht auf, sondern blieben Viehzüchter. Ihr Problem war nicht zu viel Anpassung, sondern eine unvollständige."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b4506db20f6c25d9"}},{"id":"qx-c2-052","clusterId":"C","werkstueckRef":"C.5.5","stufe":3,"question":"Ein Artikel behauptet: „Die Menschheit hat Holz durch Kohle, Kohle durch Öl und Öl nun durch Sonne und Wind ersetzt. Jede Stufe ist dichter und leistungsfähiger als die vorige.“ Was ist an dieser Behauptung fehlerhaft?","options":["Sie unterstellt, dass neue Energieträger die alten abgelöst haben, und sie übersieht, dass Sonne und Wind eine weit geringere Energiedichte haben als Kohle oder Öl.","Sie unterstellt, dass der Energieverbrauch überall gleich stark gewachsen ist, und sie übersieht die großen Unterschiede zwischen reichen und armen Ländern.","Sie unterstellt, dass jeder Energieträger das Klima gleich stark belastet, und sie übersieht, dass Kohle und Öl weit mehr CO₂ freisetzen als Wind und Sonne.","Sie unterstellt, dass die Vorräte an Energieträgern unbegrenzt sind, und sie übersieht, dass Kohle und Öl nur in endlicher Menge in der Erde lagern."],"correctIndex":0,"explanation":"Zwei Denkfehler stecken in der Behauptung. Erstens: Neue Energieträger sind meist hinzugekommen, statt alte zu ersetzen; Biomasse dominierte bis weit ins 19. Jahrhundert, und Kohle, Öl und Gas wurden dazugenommen, nicht eingetauscht. Zweitens: Die Reihe „immer dichter“ bricht beim letzten Glied, denn Sonnenstrahlung und Wind haben eine viel geringere Energiedichte als Kohle oder Öl. Die übrigen Gedanken sind für sich richtig, treffen aber nicht diese Behauptung: Über die regionale Verteilung des Verbrauchs sagt der Artikel nichts. Zur Klimawirkung der Träger äußert er sich nicht. Und von der Endlichkeit der Vorräte ist ebenfalls nicht die Rede.","coreRule":"⚡ Energiestufen addieren sich, sie ersetzen sich nicht – und nicht jedes Glied einer Reihe passt ins Muster.","beleg":"Werkstück C.5.5 (Kontext & Tiefe, Energie ist die Währung des Fortschritts); Fn. gl-c-energiestufen (Schabbach/Wesselak 2012, S. 56, 69 und 113–114)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Neue Energieträger kamen meist hinzu, statt alte zu ersetzen, und die Reihe „immer dichter“ bricht bei Sonne und Wind, deren Energiedichte viel geringer ist. Der Fehler liegt in der Abfolge selbst, nicht in Verbrauch, Klima oder Vorräten.","prueffrage":"Welche Aussagen macht der Artikel wörtlich, und welche davon ließen sich mit Verbrauchszahlen oder Messwerten nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass Verbrauch und Wohlstand weltweit sehr ungleich verteilt sind, stimmt. Der Artikel sagt dazu aber nichts, weder zum Wachstum noch zu Regionen. Geprüft werden muss, was er behauptet: die Abfolge der Träger und die steigende Dichte."},{"option":2,"text":"Dass Kohle und Öl mehr CO₂ freisetzen als Wind und Sonne, ist richtig. Davon handelt der Artikel jedoch gar nicht: Er behandelt weder Klimawirkung noch Belastung, sondern nur die Abfolge der Träger und ihre Dichte."},{"option":3,"text":"Kohle und Öl lagern tatsächlich nur in endlicher Menge in der Erde. Vorräte kommen im Artikel aber nicht vor, und seine Behauptung hängt nicht davon ab. Sie scheitert an der Ersetzungsreihe und an der Dichte."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Our World in Data: Ritchie, H. (2021): How have the world’s energy sources changed over the last two centuries?","oeffentlich":true,"url":"https://ourworldindata.org/global-energy-200-years","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schabbach, T.; Wesselak, V. (2012): Energie. Die Zukunft wird erneuerbar. Berlin/Heidelberg: Springer","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"568e0a34da4d2c8c"}},{"id":"qx-c2-053","clusterId":"C","werkstueckRef":"C.5.5","stufe":4,"question":"Jemand sagt: „Die Geografie erklärt, warum manche Länder heute reich und andere arm sind. Eurasien hatte Weizen, Rinder und Pferde, Amerika hatte das nicht.“ Als Gegenargument wird angeführt: Zur Zeit der Eroberung verdiente ein Spanier wahrscheinlich weniger als das Doppelte eines Bewohners des Inkareichs, heute ist der durchschnittliche Spanier über sechsmal so reich wie der durchschnittliche Peruaner. Was folgt aus diesem Zahlenvergleich?","options":["Die Geografie erklärt auch die wachsende Kluft, weil der Vorsprung Eurasiens über die Jahrhunderte weiterwirkte; weitere Faktoren braucht es dafür nicht.","Kulturelle Unterschiede erklären die Kluft besser als die Geografie, weil Institutionen aus den Wertvorstellungen einer Gesellschaft folgen.","Weil der Abstand zu Beginn noch gering war, erklärt die Geografie schon den frühen Vorsprung nicht; sie spielt auch am Anfang keine Rolle.","Die Geografie erklärt den frühen Vorsprung, nicht aber die später wachsende Kluft; dafür braucht es weitere Faktoren wie Institutionen."],"correctIndex":3,"explanation":"Der Abstand wuchs von weniger als dem Doppelten auf über das Sechsfache. Laut Acemoglu und Robinson liefert Diamonds Geografie-These einen plausiblen Ansatz für den Vorsprung Eurasiens zu Beginn der Neuzeit, erklärt aber nicht, warum sich der Abstand später immer weiter öffnete. Daraus folgt nicht, dass die Geografie keine Rolle spielt: Sie kann den Start erklären, etwa durch domestizierbare Pflanzen und Tiere in Eurasien. Der spätere Abstand verlangt zusätzliche Faktoren. Acemoglu und Robinson sehen sie in Institutionen, also Regeln, die Eigentum sichern, Neuerungen belohnen und die Mehrheit am Wirtschaftsleben beteiligen, oder solchen, mit denen Herrschende auf Kosten der Übrigen Gewinn ziehen. Diese Regeln entstehen in politischen Prozessen und sind kein vorherbestimmtes Ergebnis der Geografie; sie folgen auch nicht einfach aus den Wertvorstellungen einer Gesellschaft. Ein Vorsprung, der nur weiterwirkt, ließe den Abstand gleich bleiben, statt ihn zu vergrößern. Eine rein kulturelle Erklärung wird durch den Zahlenvergleich nicht belegt. Und ein anfangs kleinerer Abstand heißt nicht, dass es keinen Vorsprung gab; erst die Entwicklung danach lässt sich mit der Geografie nicht erklären.","coreRule":"⚡ Ein Faktor, der gleich bleibt, erklärt keine wachsende Kluft allein: Geografie erklärt oft den Start, Institutionen und andere Entscheidungen den späteren Abstand.","beleg":"Werkstück C.5.5 (Der Kipppunkt); Fn. gl-c-acemoglu (Acemoglu/Robinson 2013, Kap. 2, Abschnitt „Die Geographie-Hypothese“)","status":"entwurf","scenario":"","kurz":"Der frühe Vorsprung ist geografisch plausibel, aber der Abstand wuchs von unter dem Doppelten auf über das Sechsfache. Ein Vorsprung allein bliebe gleich groß, das Auseinanderdriften braucht weitere Faktoren wie Institutionen.","prueffrage":"Was zeigt der Zahlenvergleich über den Abstand zwischen beiden Gruppen zu den zwei Zeitpunkten, und was zeigt er nicht?","rueckmeldung":[{"option":0,"text":"Dass ein Vorsprung nachwirkt, ist plausibel. Er würde den Abstand aber eher erhalten, als ihn zu vervielfachen: Aus weniger als dem Doppelten wurde mehr als das Sechsfache. Dieses Wachsen verlangt zusätzliche Erklärungen."},{"option":1,"text":"Kultur und Institutionen können durchaus mitspielen. Der Zahlenvergleich belegt aber keine kulturelle Erklärung: Er zeigt nur, dass der Abstand wuchs. Institutionen entstehen zudem in politischen Prozessen und folgen nicht einfach aus Wertvorstellungen."},{"option":2,"text":"Der anfangs kleine Abstand ist richtig beobachtet. Daraus folgt aber nicht, dass es keinen Vorsprung gab: Domestizierbare Pflanzen und Tiere können den Start erklären. Unerklärt bleibt erst die spätere Entwicklung."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Nobel Prize Outreach: Popular information – The Prize in Economic Sciences 2024","oeffentlich":true,"url":"https://www.nobelprize.org/prizes/economic-sciences/2024/popular-information/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Acemoglu, D.; Robinson, J. A. (2013): Warum Nationen scheitern. Frankfurt a. M.: S. Fischer, Kap. 2 „Die Geographie-Hypothese“","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a830428dd3bd9c4e"}},{"id":"qx-c2-054","clusterId":"C","werkstueckRef":"C.5.6","stufe":1,"question":"Eine Dokumentation zeigt: Eine ältere Frau ist in ihrem Wohnzimmer fast vollständig verbrannt, der Sessel ist zerstört, der Rest des Raumes kaum beschädigt. Im Film heißt es: „Es gab keine erkennbare Zündquelle, also muss sich die Frau von selbst entzündet haben.“ Welche Prüfung ist als Erstes sinnvoll?","options":["Prüfen, ob in Reichweite der Frau eine alltägliche Zündquelle wie Zigarette, Kerze oder Kamin stand und ob sie nur eingeschränkt beweglich war.","Prüfen, ob es weitere Fälle mit ähnlichem Muster gibt, denn ein Phänomen, das sich oft wiederholt, hat vermutlich eine gemeinsame, bisher unbekannte Ursache.","Prüfen, ob die Dokumentation von einem Sender stammt, der für Sensationsberichte bekannt ist, und die Erklärung allein nach dessen Ruf einzuordnen.","Prüfen, ob Augenzeugen im Wohnzimmer den Brandbeginn beobachtet haben, denn deren Aussagen sind verlässlicher als jede spätere Spurenauswertung."],"correctIndex":0,"explanation":"Aus „Ich sehe keine offensichtliche Ursache“ folgt nicht „Es gab keine Ursache“. Ein umgekippter Aschenbecher oder eine heruntergefallene Kerze reicht bereits. Die geringe Zerstörung der Umgebung spricht auch nicht gegen ein gewöhnliches Feuer: Wenn eine äußere Flamme die Haut einige Minuten erhitzt, brennt das schmelzende Unterhautfett im verkohlten Gerüst aus Haut und Kleidung wie bei einer umgedrehten Kerze über Stunden mit kleinen Flammen weiter. So wird der Körper stark zerstört, der Raum kaum. Ein Versuch von DeHaan und Nurbakhsh (2001) mit einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigte genau das: Das Feuer hielt sich über 6,5 Stunden selbst am Leben. Erst die systematische Prüfung von Zündquelle, Brennstoff (Unterhautfett) und Beweglichkeit der Person zeigt, ob der Fall zum bekannten Dochteffekt-Muster passt, bevor man eine übernatürliche Erklärung erwägt. Weitere Fälle, der Ruf eines Senders oder Augenzeugen sind kein Ersatz dafür: Häufigkeit sagt nichts über die Ursache, der Ruf des Senders nichts über den Brand selbst, und Augenzeugen irren sich beim Brandbeginn leicht.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ heißt nicht „keine Zündquelle“: Erst suchen, dann „unerklärlich“ sagen.","beleg":"Werkstück C.5.6 (Kontext & Tiefe; Anwendung & Relevanz, Bei „spontaner menschlicher Selbstentzündung“)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von einer Dokumentation und hält den Fall für ein Beispiel „spontaner Selbstentzündung“.","kurz":"Dass keine Zündquelle zu sehen ist, heißt nicht, dass es keine gab: Eine Zigarette oder Kerze kann schon gereicht haben. Wer daraus eine Selbstentzündung ableitet, schließt von Unwissen auf Nichtvorhandensein.","prueffrage":"Was zeigen die Aufnahmen vom Tisch und vom Boden neben dem Sessel, und was weiß man über die Gewohnheiten der Frau?","rueckmeldung":[{"option":1,"text":"Weitere Fälle zu sammeln wirkt gründlich. Wie oft etwas vorkommt, sagt aber nichts über seine Ursache: Ähnliche Fälle können alle denselben gewöhnlichen Mechanismus haben. Erst der Einzelfall zeigt, ob eine bekannte Erklärung reicht."},{"option":2,"text":"Bei einem Sender, der für Sensationen bekannt ist, ist Vorsicht angebracht. Sein Ruf sagt aber nichts darüber, was im Wohnzimmer tatsächlich geschah. Entscheidend ist, was sich am Brand selbst prüfen lässt."},{"option":3,"text":"Zeugen klingen nach dem direktesten Beleg. Doch gerade bei Brandbeginn irren sie sich leicht, und von Zeugen im Raum ist im Fall nirgends die Rede. Spuren von Zündquelle, Brennstoff und Beweglichkeit lassen sich nachprüfen, Erinnerungen kaum."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e19394ce0b93a391"}},{"id":"qx-c2-055","clusterId":"C","werkstueckRef":"C.5.6","stufe":2,"question":"Welche Erklärung ist die sparsamste, und was würdest du zuerst prüfen?","scenario":"Nach einem Wohnungsbrand sagt ein Gutachter: Der Rumpf der Person sei fast vollständig verbrannt, Arme, Beine und Kopf dagegen vergleichsweise unversehrt. Im Raum selbst gibt es nur mäßige Brandschäden. Ein Bekannter meint: „Wenn der Körper so ungleichmäßig brennt, muss ein besonderer Brandbeschleuniger im Spiel gewesen sein.“","options":["Der Rumpf hat viel Unterhautfett, das schmilzt, von verkohlter Haut und Kleidung aufgesaugt wird und langsam weiterbrennt. Prüfen: Zündquelle, Kleidung, Fettanteil.","Ein Brandbeschleuniger wurde gezielt am Rumpf ausgebracht, sodass dieser weit stärker brannte als der Rest. Prüfen: Rückstände, Kleidungsreste, Brandmuster.","Der Rumpf lag dem Brandherd am nächsten und war der Hitze länger ausgesetzt als Arme, Beine und Kopf. Prüfen: Lage des Körpers, Brandherd, Wärmestrahlung.","Unter dem Rumpf schwelte ein Polster, etwa von Sofa oder Matratze, und erhitzte ihn über Stunden von unten. Prüfen: Polstermöbel, Schwelspuren, Liegeposition."],"correctIndex":0,"explanation":"Ungleichmäßige Zerstörung ist kein Beweis für einen Brandbeschleuniger. Sie ist genau das, was die bekannte Verbrennungsphysik vorhersagt: Brennstoff ist das Unterhautfett, das durch Hitze schmilzt und von verkohlter Haut und Kleidung wie von einem Docht aufgesogen wird. So brennt es langsam mit niedrigen Flammen, ähnlich einer Öllampe, und die Umgebung bleibt vergleichsweise geschont. Arme, Beine und Kopf haben meist weniger Fett als der Rumpf und liefern diesem Docht-Feuer deshalb weniger Brennstoff. Experimente an einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigten, dass sich ein solches Feuer über mehr als 6,5 Stunden selbst am Leben hielt, bis die Forscher es löschten, nachdem eine äußere Flamme es einmal entzündet hatte. Die sparsamste Erklärung ist daher die, die ohne zusätzliche Annahme auskommt, und sie lässt sich an Zündquelle, Kleidung und Fettverteilung überprüfen. Ein Brandbeschleuniger wäre eine zusätzliche Annahme, die erst Rückstände belegen müssten. Die größere Nähe zum Brandherd erklärt nicht, warum der Rumpf fast völlig verbrannt ist, während der Raum nur mäßig geschädigt ist. Ein schwelendes Polster setzt Möbel voraus, von denen im Szenario keine Rede ist. Dass ein Brandbeschleuniger hier nichts erklärt, heißt nicht, dass er ausgeschlossen ist: Würden Spuren davon gefunden, änderte das die Lage.","coreRule":"⚡ Wo das Fett sitzt, brennt der Docht weiter.","beleg":"Werkstück C.5.6 (Anwendung & Relevanz, In der Forensik allgemein)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ungleichmäßige Zerstörung belegt keinen Brandbeschleuniger: Das Unterhautfett des Rumpfes kann wie bei einer Kerze mit Docht langsam weiterbrennen. Sparsam ist, was ohne zusätzliche Annahme auskommt; die Spurensuche kann sie dennoch prüfen.","prueffrage":"Welche Körperteile sind stark verbrannt, welche kaum, und worin unterscheiden sie sich außer in ihrer Lage?","rueckmeldung":[{"option":1,"text":"Ein Brandbeschleuniger wäre ein Schluss aus der Ungleichmäßigkeit allein, ohne dass Spuren davon genannt werden. Rückstände zu suchen ist richtig; ausgeschlossen ist er nicht, aber erklären muss er hier nichts, was nicht auch ohne ihn erklärbar ist."},{"option":2,"text":"Je näher am Brandherd, desto länger die Hitze: Das ist grundsätzlich einleuchtend und prüfbar. Es erklärt aber nicht, warum der Rumpf fast völlig verbrannt ist, während der Raum nur mäßige Schäden zeigt."},{"option":3,"text":"Ein schwelendes Polster könnte einen Körper lange erhitzen. Im Szenario ist aber von Sofa oder Matratze keine Rede; die Erklärung setzt damit etwas voraus, das erst belegt werden müsste, statt mit dem Gegebenen auszukommen."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7953f46d01448f01"}},{"id":"qx-c2-056","clusterId":"C","werkstueckRef":"C.5.6","stufe":3,"question":"Welche Folge ist bei diesem Vorgehen am wahrscheinlichsten und warum problematisch?","scenario":"Bei den Ermittlungen zu einem Brandtod liegt ein fast völlig verbrannter Körper in einem kaum beschädigten Zimmer. Ein Ermittler sieht keine offensichtliche Zündquelle und schreibt „unerklärlich“ in den Bericht.","options":["Aus einem Einzelfall kann eine allgemeine Regel entstehen, weil ein einziges Ereignis für eine Gesetzmäßigkeit gehalten wird.","Ein echter Zündvorgang, etwa ein Unfall oder eine Tat, kann unentdeckt bleiben, weil die Ursachensuche vorzeitig endet.","Eine Zeugenaussage kann überschätzt werden, weil das selbstsichere Auftreten des Zeugen mit Richtigkeit verwechselt wird.","Der Ausgang kann rückblickend als vorhersehbar gelten, weil man das Ergebnis kennt und frühere Warnzeichen überschätzt."],"correctIndex":1,"explanation":"Der Schluss „Ich sehe keine offensichtliche Ursache, also gab es keine“ ist ein Fehlschluss: Dass etwas nicht sofort erkennbar ist, heißt nicht, dass es nicht existiert. Zudem ist die Unversehrtheit der Umgebung kein Beweis gegen ein gewöhnliches Feuer. Brandversuche (DeHaan und Nurbakhsh, 2001) zeigten, dass ein in eine Baumwolldecke gewickelter Schweinekadaver, gewählt als Ersatz für einen menschlichen Körper, sich über mehr als 6,5 Stunden selbst am Leben erhaltend verbrannte, mit der Decke als Docht und dem Körperfett als Brennstoff. Wer vorschnell „unerklärlich“ schreibt, prüft nicht mehr, ob in Reichweite eine Zigarette, Kerze oder ein Kamin stand und ob der Körper genug Fett als Brennstoff hatte. So kann ein Unfall oder eine Tat übersehen werden. Dass aus einem Einzelfall keine Regel folgt, ist richtig, doch der Ermittler sagt nichts über andere Fälle. Zeugen kommen im Fall nicht vor, daher geht es nicht um die Überschätzung ihrer Aussagen. Einen Rückblick auf frühere Warnzeichen gibt es ebenfalls nicht, denn der Bericht beschreibt nur den Fund und das Fehlen einer sichtbaren Zündquelle.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ ist nicht „keine Zündquelle“.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.6 (Anwendung & Relevanz; Red Flags; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer „unerklärlich“ schreibt, hört auf zu suchen, obwohl „nicht sofort sichtbar“ nicht „nicht vorhanden“ heißt. So kann eine Zigarette, Kerze oder eine Tat unentdeckt bleiben, denn ein gewöhnliches Feuer kann einen Körper verzehren und den Raum kaum beschädigen.","prueffrage":"Welche alltäglichen Zündquellen kämen in einem Wohnzimmer infrage, und welche davon hinterlassen nach einem Brand kaum Spuren?","rueckmeldung":[{"option":0,"text":"Dass ein einzelner Fall noch keine Regel ergibt, stimmt. Der Ermittler sagt aber nichts über andere Fälle, sondern beendet nur die Suche im eigenen. Der Fehler liegt im vorzeitigen Schluss, nicht in einer Verallgemeinerung."},{"option":2,"text":"Selbstsicheres Auftreten mit Richtigkeit zu verwechseln, ist ein bekannter Fehler. In diesem Fall tritt jedoch gar kein Zeuge auf: Es gibt nur den Fund und das Fehlen einer sichtbaren Zündquelle."},{"option":3,"text":"Der Rückschaufehler braucht einen bekannten Ausgang und einen Blick auf frühere Warnzeichen. Davon steht hier nichts: Der Bericht hält nur den Fund und die fehlende sichtbare Zündquelle fest."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8d7d8f42ba78fe79"}}]`);export{t as n,n as t};